const $ = (s, r=document) => r.querySelector(s);
const $$ = (s, r=document) => [...r.querySelectorAll(s)];
const app = $('#app');
const state = { me:null, view:'dashboard', dashboard:null, accounts:[], selected:null, searchTimer:null, globalShortcutsBound:false };
const DRAFT_DB='serviceslate-field-v2', DRAFT_STORE='drafts', OUTBOX_STORE='outbox', CACHE_STORE='cache';

function esc(v=''){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}
function fmtDate(v){ if(!v)return '—'; try{return new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric'}).format(new Date(v));}catch{return v;} }
function fmtTime(v){ if(!v)return ''; try{return new Intl.DateTimeFormat('en-US',{hour:'numeric',minute:'2-digit'}).format(new Date(v));}catch{return v;} }
function mins(n){return n>=60?`${Math.floor(n/60)}h ${n%60?`${n%60}m`:''}`:`${n}m`;}
function money(cents=0){return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format((+cents||0)/100);}
function bytes(n=0){if(n<1024)return `${n} B`;if(n<1048576)return `${(n/1024).toFixed(1)} KB`;if(n<1073741824)return `${(n/1048576).toFixed(1)} MB`;return `${(n/1073741824).toFixed(1)} GB`;}
function tone(v=''){v=String(v).toUpperCase();if(['READY','RECEIVED','RESERVED','LOADED','INSTALLED','APPROVED','LOCKED','COMPLETED','CONFIRMED','ACTIVE','AVAILABLE','SYNCED','VIEWED'].includes(v))return 'good';if(['HIGH','OVERDUE','BACKORDERED','BLOCKED','RESTRICTED','DECLINED','CANCELED','FAILED','STALE'].includes(v))return 'high';if(['ORDERED','NEEDED','SNOOZED','DEFERRED','AWAITING_FORMS','AWAITING_CUSTOMER_APPROVAL','NEEDS_CORRECTION','AWAITING_CONFIRMATION','CHANGE_REQUESTED'].includes(v))return 'warn';return 'blue';}
const FRIENDLY_LABELS={NEW_REQUEST:'New Request',TRIAGE:'Needs Review',AWAITING_INFORMATION:'Waiting for Information',ESTIMATE_REQUIRED:'Estimate Needed',AWAITING_CUSTOMER_APPROVAL:'Waiting for Approval',APPROVED_UNSCHEDULED:'Ready to Schedule',SCHEDULED:'Scheduled',IN_SERVICE:'In Service',BLOCKED:'Waiting / Blocked',WORK_COMPLETE:'Work Complete',READY_TO_INVOICE:'Ready for Billing',INVOICED:'Invoiced',CLOSED:'Closed',CANCELED:'Canceled',FLEXIBLE_DAY:'Service Day',DAY_COMMITMENT:'Scheduled Day',ARRIVAL_WINDOW:'Arrival Window',EXACT_TIME:'Exact Time',TENTATIVE:'Tentative',EMERGENCY:'Emergency',AWAITING_CONFIRMATION:'Awaiting Customer',CHANGE_REQUESTED:'New Day Requested',STALE:'Date Changed',PREPARED:'Ready to send',SUBMITTED:'Submitted for Review',NEEDS_CORRECTION:'Needs Correction',LIKELY_AVAILABLE:'Likely Available',NEEDS_RESTOCK:'Needs Restock',CONFIRMED_LOADED:'Loaded & Confirmed'};
function nice(v=''){const raw=String(v??'');return FRIENDLY_LABELS[raw.toUpperCase()]||raw.replaceAll('_',' ').toLowerCase().replace(/\b\w/g,c=>c.toUpperCase());}
function uid(){return crypto.randomUUID?.() || `${Date.now()}-${Math.random()}`;}
function toast(msg,type=''){const e=document.createElement('div');e.className=`toast ${type}`;e.setAttribute('role',type==='bad'?'alert':'status');e.innerHTML=`<span class="toast-mark">${type==='good'?'✓':type==='bad'?'!':'•'}</span><span>${esc(msg)}</span><button aria-label="Dismiss notification">×</button>`;e.querySelector('button').onclick=()=>e.remove();$('#toast-root').append(e);setTimeout(()=>e.remove(),4200);}
function closeModal(value=false){const m=$('.modal-backdrop');if(!m)return;const done=m._resolve,returnFocus=m._returnFocus;m._cleanup?.();m.classList.add('closing');setTimeout(()=>{m.remove();document.body.classList.remove('modal-open');done?.(value);if(returnFocus&&document.contains(returnFocus))returnFocus.focus()},100);}
function modalShell({title,message='',body='',confirmLabel='Continue',cancelLabel='Cancel',danger=false,hideCancel=false}){return `<div class="modal-backdrop" role="presentation"><section class="modal-card" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal-head"><div><div class="eyebrow">ServiceSlate</div><h2 id="modalTitle">${esc(title)}</h2>${message?`<p>${esc(message)}</p>`:''}</div><button class="modal-x" aria-label="Close">×</button></div>${body?`<div class="modal-body">${body}</div>`:''}<div class="modal-actions">${hideCancel?'':`<button class="btn" data-modal-cancel>${esc(cancelLabel)}</button>`}<button class="btn ${danger?'danger':'primary'}" data-modal-confirm>${esc(confirmLabel)}</button></div></section></div>`}
function askConfirm({title='Are you sure?',message='',confirmLabel='Continue',cancelLabel='Cancel',danger=false}={}){return new Promise(resolve=>{document.body.insertAdjacentHTML('beforeend',modalShell({title,message,confirmLabel,cancelLabel,danger}));const m=$('.modal-backdrop');m._resolve=resolve;m._returnFocus=document.activeElement;document.body.classList.add('modal-open');const card=$('.modal-card',m);requestAnimationFrame(()=>m.classList.add('open'));$('[data-modal-confirm]',m).onclick=()=>closeModal(true);$('[data-modal-cancel]',m).onclick=()=>closeModal(false);$('.modal-x',m).onclick=()=>closeModal(false);m.onclick=e=>{if(e.target===m)closeModal(false)};const onKey=e=>{if(e.key==='Escape')closeModal(false)};m._cleanup=()=>document.removeEventListener('keydown',onKey);document.addEventListener('keydown',onKey);$('[data-modal-confirm]',card)?.focus();})}
function askText({title,message='',label='Value',value='',placeholder='',type='text',confirmLabel='Continue',required=false}={}){return new Promise(resolve=>{const body=`<div class="field modal-field"><label>${esc(label)}</label>${type==='textarea'?`<textarea id="modalInput" placeholder="${esc(placeholder)}">${esc(value)}</textarea>`:`<input id="modalInput" type="${esc(type)}" value="${esc(value)}" placeholder="${esc(placeholder)}">`}</div>`;document.body.insertAdjacentHTML('beforeend',modalShell({title,message,body,confirmLabel}));const m=$('.modal-backdrop');m._resolve=resolve;m._returnFocus=document.activeElement;document.body.classList.add('modal-open');requestAnimationFrame(()=>m.classList.add('open'));const input=$('#modalInput',m),finish=()=>{const v=input.value.trim();if(required&&!v){input.focus();input.classList.add('field-error');return}closeModal(v)};$('[data-modal-confirm]',m).onclick=finish;$('[data-modal-cancel]',m).onclick=()=>closeModal(undefined);$('.modal-x',m).onclick=()=>closeModal(undefined);m.onclick=e=>{if(e.target===m)closeModal(undefined)};input.onkeydown=e=>{if(e.key==='Enter'&&type!=='textarea'){e.preventDefault();finish()}if(e.key==='Escape')closeModal(undefined)};setTimeout(()=>{input.focus();if(value)input.select()},20);})}
async function api(path,opt={}){const headers={'Content-Type':'application/json',...(state.me?.csrf_token?{'X-CSRF-Token':state.me.csrf_token}:{}),...(opt.headers||{})};let r;try{r=await fetch(path,{...opt,headers})}catch(err){err.isNetworkError=true;throw err}if(r.status===401&&state.me){state.me=null;renderLogin();const err=new Error('Sign in required');err.status=401;throw err;}let body=null;try{body=await r.json()}catch{}if(!r.ok){const err=new Error(body?.detail||`Request failed (${r.status})`);err.status=r.status;throw err}return body;}
function bindRemoteFilter(inputSelector,rowSelector,loadRows,renderRows){const input=$(inputSelector);if(!input)return;let timer=0,request=0;input.addEventListener('input',()=>{clearTimeout(timer);const query=input.value.trim(),token=++request;timer=setTimeout(async()=>{try{const rows=await loadRows(query);const target=$(rowSelector);if(token===request&&target)target.innerHTML=renderRows(rows)}catch(err){if(token===request)toast(`Could not update this list: ${err.message}`,'bad')}},180)})}
function profileLabel(p){return p==='grooming'?'Pet Grooming':'Automotive Equipment';}
function initials(n=''){return n.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();}
function navItems(){
 const role=state.me.role, grooming=state.me.organization_profile==='grooming';
 if(grooming){
   if(role==='GROOMER') return [['tech','✓','My Appointments'],['pets','◇','Pets']];
   return [['dashboard','◫','Today'],['calendar','▦','Calendar'],['customers','◎','Customers'],['pets','◇','Pets'],['waitlist','◷','Waitlist'],['rebooking','↻','Rebooking'],['services','◌','Services'],['forms','▤','Forms'],...(role==='ADMIN'||role==='MANAGER'?[['team','♙','Team']]:[]),['tech','✓','My Appointments']];
 }
 if(role==='TECHNICIAN') return [['tech','↗','My Work'],['equipment','◇','Equipment']];
 if(role==='BILLING') return [['dashboard','◫','Billing Ready'],['jobs','▣','Jobs'],['estimates','$','Estimates'],['reports','▥','Reports']];
 return [['dashboard','◫','Coordinator Assist'],['calendar','▦','Calendar'],['customers','◎','Customers'],['jobs','▣','Jobs'],['equipment','◇','Equipment'],['inspections','◈','Inspections'],['parts','⌁','Parts'],['recurring','↻','Recurring'],['estimates','$','Estimates'],...(['ADMIN','MANAGER','COORDINATOR'].includes(role)?[['sales','◇','Sales & Install']]:[]),['reviews','✓','Work Review'],['vehicles','▱','Vehicles'],['services','◌','Services'],['forms','▤','Forms'],['reports','▥','Reports'],...(role==='ADMIN'||role==='MANAGER'?[['team','♙','Team']]:[]),['tech','↗','Technician']];
}
function shell(content){const items=navItems();return `<div class="app-shell">
<aside class="sidebar"><div class="side-brand"><img class="brand-logo" src="/static/brand-icon-192.png" alt=""><div class="wordmark">Service<em>Slate</em><span class="product-badge">ALPHA</span></div></div>
<div class="org-chip"><strong>${esc(state.me.organization_name)}</strong><span>${profileLabel(state.me.organization_profile)}${state.me.is_demo?' · Demo':''}</span></div>
<nav class="nav">${items.map(([id,ic,l])=>`<button data-nav="${id}" class="${state.view===id?'active':''}"><span class="icon">${ic}</span>${l}</button>`).join('')}</nav>
<div class="nav-section">System</div><nav class="nav"><button data-nav="office" class="${state.view==='office'?'active':''}"><span class="icon">↔</span>Office Network</button><button data-nav="tools" class="${state.view==='tools'?'active':''}"><span class="icon">⌘</span>Tools & Connections</button><button data-nav="search"><span class="icon">⌕</span>Search</button><button data-nav="system"><span class="icon">⚙</span>Settings & Backup</button></nav>
<div class="side-foot"><div class="sync-indicator"><span class="dot"></span><span>Workspace ready</span></div><button class="btn ghost small block" id="logoutBtn">Sign out</button></div></aside>
<header class="topbar"><div class="searchbox"><input id="globalSearch" placeholder="Search customers, work orders, equipment…" autocomplete="off"><span class="search-kbd">Ctrl K</span></div><div class="top-actions"><span class="top-status" title="ServiceSlate workspace connection is ready"><span class="dot"></span><span>Connected</span></span><button class="btn small help-btn" id="helpBtn" title="Help with this screen">?</button><button class="btn small quick-add" id="quickAdd">＋ New Work</button><button class="user-button" id="userMenu"><span class="avatar">${initials(state.me.name)}</span><span class="user-meta"><strong>${esc(state.me.name)}</strong><span>${esc(state.me.role.replaceAll('_',' '))}</span></span></button></div></header>
<main class="main">${content}</main>
<nav class="mobile-only-nav">${items.slice(0,4).map(([id,ic,l])=>`<button data-nav="${id}" class="${state.view===id?'active':''}"><span>${ic}</span>${l.split(' ')[0]}</button>`).join('')}<button data-nav="more" class="${state.view==='more'?'active':''}"><span>•••</span>More</button></nav>
</div>`}
async function signOut(){const pending=await outboxList(),drafts=await draftCount();if((pending.length||drafts)&&!(await askConfirm({title:'Sign out with saved field work?',message:`${pending.length+drafts} saved field item${pending.length+drafts===1?'':'s'} remain on this device. They will stay here and will only reopen for this same account.`,confirmLabel:'Sign Out'})))return;await api('/api/logout',{method:'POST'});state.me=null;renderLogin()}
function wireShell(){ const qa=$('#quickAdd');if(qa)qa.textContent=state.me.organization_profile==='grooming'?'＋ Book Appointment':'＋ New Work'; $$('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav)); $('#logoutBtn')?.addEventListener('click',signOut); $('#userMenu')?.addEventListener('click',()=>navigate('system')); $('#helpBtn')?.addEventListener('click',openHelp); $('#userMenu')?.setAttribute('title','Account and settings'); $('#quickAdd')?.addEventListener('click',()=>state.me.organization_profile==='grooming'?openGroomingQuick():openNewJob()); const gs=$('#globalSearch'); if(gs){gs.setAttribute('aria-label','Search ServiceSlate');gs.addEventListener('keydown',e=>{if(e.key==='Enter'&&gs.value.trim().length>=2){state.pendingSearch=gs.value.trim();navigate('search')}})}if(!state.globalShortcutsBound){document.addEventListener('keydown',hotkey);state.globalShortcutsBound=true;}}
function hotkey(e){if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&!$('.modal-backdrop')&&!e.target.matches('input,textarea,select')){e.preventDefault();$('#globalSearch')?.focus()}}
async function navigate(v){state.view=v;app.innerHTML=shell(`<div class="page-loading" aria-busy="true"><div class="loading-line wide"></div><div class="loading-line"></div><div class="loading-grid"><span></span><span></span><span></span></div></div>`);wireShell();try{if(v==='dashboard')await renderDashboard();else if(v==='customers')await renderCustomers();else if(v==='jobs')await renderJobs();else if(v==='equipment')await renderEquipment();else if(v==='inspections')await renderInspections();else if(v==='calendar')await renderCalendar();else if(v==='reviews')await renderReviews();else if(v==='vehicles')await renderVehicles();else if(v==='parts')await renderParts();else if(v==='recurring')await renderRecurring();else if(v==='followups')await renderFollowups();else if(v==='estimates')await renderEstimates();else if(v==='services')await renderServices();else if(v==='forms')await renderForms();else if(v==='reports')await renderReports();else if(v==='sales')await renderSales();else if(v==='readiness')await renderReadiness();else if(v==='team')await renderTeam();else if(v==='waitlist')await renderWaitlist();else if(v==='rebooking')await renderRebooking();else if(v==='tech')await renderTech();else if(v==='pets')await renderPets();else if(v==='search')await renderSearchPage();else if(v==='tools')await renderTools();else if(v==='office')await renderOffice();else if(v==='more')await renderMore();else if(v==='system')await renderSystem();}catch(e){renderError(e);}}
function setMain(html){const main=$('.main');if(!main)return;main.innerHTML=html;main.setAttribute('data-view',state.view);document.title=`${nice(state.view)} · ServiceSlate`;requestAnimationFrame(()=>main.classList.add('view-ready'));}
function renderError(e){setMain(`<div class="page-head"><div><div class="eyebrow">Needs attention</div><h1>That didn’t open correctly</h1><p>Anything already saved is still safe.</p></div></div><section class="panel error-panel"><div class="empty-state"><div class="empty-icon">!</div><strong>${esc(e.message)}</strong><span>Try the page again. If it keeps happening, Settings & Backup has the health check.</span><div class="empty-actions"><button class="btn" id="errorBack">Go Back</button><button class="btn primary" id="errorRetry">Try Again</button></div></div></section>`);$('#errorBack')?.addEventListener('click',()=>navigate('dashboard'));$('#errorRetry')?.addEventListener('click',()=>navigate(state.view));}

async function renderLogin(){state.view='dashboard';let accounts=[];try{accounts=await api('/api/demo-accounts')}catch{}app.innerHTML=`<div class="login-page"><section class="login-pane"><div class="login-brand"><img class="brand-logo" src="/static/brand-icon-192.png" alt=""><div class="wordmark">Service<em>Slate</em></div></div><div class="login-card"><h1>Everything connected.<br>Nothing forgotten.</h1><p>Customers, scheduling, field paperwork and history stay connected in one simple workspace.</p><form id="loginForm"><div class="field"><label>Email</label><input id="email" value="coordinator@demo.example.com" autocomplete="username"></div><div class="field"><label>Password</label><input id="password" type="password" value="ServiceSlateDemo!26" autocomplete="current-password"></div><button class="btn primary block" type="submit">Open ServiceSlate</button><button class="btn ghost block" type="button" id="microsoftLogin">Sign in with company Microsoft</button><button class="btn ghost block secondary-login" type="button" id="setupBusiness">Set up my business</button></form><div class="demo-list"><h3>Demo roles</h3>${accounts.filter(a=>['COORDINATOR','TECHNICIAN','MANAGER','RECEPTION','GROOMER'].includes(a.role)).slice(0,6).map(a=>`<button class="demo-account btn ghost block" data-email="${esc(a.email)}"><span>${esc(a.name)} · ${esc(a.role)}</span><span>${esc(a.organization_name)}</span></button>`).join('')}</div></div><div class="tiny muted">Runs locally · No server or paid service required</div></section><section class="login-art"><div class="art-grid"></div><div class="art-copy"><div class="eyebrow">Operational Memory Software</div><h2>Some jobs need to be<br>set in stone.</h2><p><strong>Every customer. Every job. Nothing forgotten.</strong><br>Scheduling, field work and permanent service history—without rebuilding the story later.</p></div></section></div>`;
$('#loginForm').onsubmit=async e=>{e.preventDefault();try{const r=await api('/api/login',{method:'POST',body:JSON.stringify({email:$('#email').value,password:$('#password').value})});if(r.mfa_required){openMfaLogin();return}await boot();}catch(err){toast(err.message,'bad')}};$('#microsoftLogin').onclick=async()=>{const email=$('#email').value.trim();if(!email)return toast('Enter your work email first','bad');try{const r=await api('/api/security/microsoft/start',{method:'POST',body:JSON.stringify({email})});location.href=r.url}catch(err){toast(err.message,'bad')}};$('#setupBusiness').onclick=openBusinessSetup;$$('.demo-account').forEach(b=>b.onclick=()=>{$('#email').value=b.dataset.email;$('#password').value='ServiceSlateDemo!26';$('#loginForm').requestSubmit();});}
function openMfaLogin(){openDrawer('Authenticator code','Your password was accepted. Enter the 6-digit code from your authenticator app.',`<form id="mfaLoginForm"><div class="field"><label>6-digit code</label><input id="mfaCode" inputmode="numeric" autocomplete="one-time-code" maxlength="8" autofocus required></div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer();renderLogin()">Cancel</button><button class="btn primary">Sign in</button></div></form>`);$('#mfaLoginForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/login/mfa',{method:'POST',body:JSON.stringify({code:$('#mfaCode').value})});closeDrawer();await boot()}catch(err){toast(err.message,'bad')}}}
async function boot(){try{state.me=await api('/api/me');await navigate('dashboard');if(state.me.force_password_change)setTimeout(()=>openForcedPasswordChange(),250);else setTimeout(maybeWelcomeGuide,450);setTimeout(startMailboxWatch,1200);setTimeout(startLanHeartbeat,900);}catch{renderLogin();}}


const GUIDES={
 welcome_office:{title:'A quick orientation',roles:['ADMIN','MANAGER','COORDINATOR','BILLING','RECEPTION'],steps:[
  ['Start with what needs attention','Coordinator Assist and Today put unfinished work first. You do not need to memorize every customer or callback.','dashboard'],
  ['Open the record, not another program','Customer, job, equipment, communication and history stay linked. Search works from anywhere.','search'],
  ['Approve exceptions, not duplicate entry','Technicians and imported forms do the data entry. You review anything important before it becomes trusted history.','reviews']]},
 welcome_field:{title:'A quick field orientation',roles:['TECHNICIAN','GROOMER'],steps:[
  ['My Work is the starting point','Open the assigned job or appointment. Relevant customer and equipment history is already attached.','tech'],
  ['Your draft saves on this device','Notes and photos survive a browser close or poor signal. Watch the Saved / Sync status at the bottom.','tech'],
  ['Send once','Complete the work record once. ServiceSlate routes it for review and builds history after approval.','tech']]},
 schedule:{title:'Schedule work',roles:['ADMIN','MANAGER','COORDINATOR'],steps:[
  ['Open Calendar','Unscheduled approved work appears alongside technician capacity.','calendar'],
  ['Review the fit','Compass explains qualification, crew and geographic fit. It never silently changes the schedule.','calendar'],
  ['Confirm the service day','After scheduling, use Customer Confirmation. The customer confirms the day—not an internal planning hour.','calendar']]},
 fastfield:{title:'Review a FastField submission',roles:['ADMIN','MANAGER','COORDINATOR'],steps:[
  ['Check Outlook','Tools & Connections can check the designated Outlook folder for FastField reports.','tools'],
  ['Review what ServiceSlate extracted','Structured attachments are mapped first. Anything imported stays Awaiting Human Review.','system'],
  ['Approve only what is right','Accept clean records with one action. Fix uncertain customer/equipment matches instead of letting software guess.','system']]},
 history:{title:'Find equipment history',roles:['ADMIN','MANAGER','COORDINATOR','TECHNICIAN','READ_ONLY'],steps:[
  ['Search the equipment','Serial, model, customer and work-order text are searchable.','equipment'],
  ['Read the service story','Completed work is organized as complaint, finding, cause, correction and verification.','equipment'],
  ['Use approved history as context','Technicians can read approved company knowledge without seeing another technician’s live draft.','equipment']]},
 backup:{title:'Back up ServiceSlate',roles:['ADMIN','MANAGER','COORDINATOR'],steps:[
  ['Open Settings & Backup','Backups include the database and attached files.','system'],
  ['Create one copy','Choose Back Up ServiceSlate. ServiceSlate verifies the archive before you rely on it.','system'],
  ['Keep a second copy elsewhere','Download a backup to a company-managed drive or storage location when real data is in use.','system']]}
};
function guideStorageKey(){return `serviceslate-guides:${state.me?.id||'anon'}`}
function guideState(){try{return JSON.parse(localStorage.getItem(guideStorageKey())||'{}')}catch{return {}}}
function setGuideState(next){localStorage.setItem(guideStorageKey(),JSON.stringify(next))}
function roleGuides(){return Object.entries(GUIDES).filter(([,g])=>g.roles.includes(state.me.role))}
function maybeWelcomeGuide(){if(!state.me)return;const st=guideState(),key=['TECHNICIAN','GROOMER'].includes(state.me.role)?'welcome_field':'welcome_office';if(st.welcome_seen)return;st.welcome_seen=true;setGuideState(st);openDrawer('New to ServiceSlate?','Optional · about one minute',`<div class="guide-welcome"><div class="guide-symbol">?</div><h2>${esc(GUIDES[key].title)}</h2><p>Three short pointers. Skip it now and Help will always be available later.</p><div class="form-actions"><button class="btn" id="skipWelcome">Not now</button><button class="btn primary" id="startWelcome">Show me</button></div></div>`);$('#skipWelcome').onclick=closeDrawer;$('#startWelcome').onclick=()=>{closeDrawer();runGuide(key,0)}}
function openHelp(){const current=state.view,available=roleGuides();openDrawer('Help','Only when you need it.',`<div class="help-intro"><strong>What are you trying to do?</strong><p>Choose one short guide. Nothing here is required.</p></div><div class="help-guide-grid">${available.map(([key,g])=>`<button class="help-guide" data-guide="${key}"><span>${g.steps.length} steps</span><strong>${esc(g.title)}</strong><small>${g.steps[0][0]}</small></button>`).join('')}</div><div class="tiny muted">Current screen: ${esc(nice(current))}. Completed guides stay available here but never pop up again.</div>`);$$('[data-guide]').forEach(b=>b.onclick=()=>{closeDrawer();runGuide(b.dataset.guide,0)})}
function runGuide(key,index=0){const g=GUIDES[key];if(!g)return;const step=g.steps[index],last=index===g.steps.length-1;const st=guideState();openDrawer(g.title,`Step ${index+1} of ${g.steps.length}`,`<div class="guide-step"><div class="guide-count">${index+1}</div><h2>${esc(step[0])}</h2><p>${esc(step[1])}</p>${step[2]&&step[2]!==state.view?`<button class="btn block" id="guideGo">Open ${esc(nice(step[2]))}</button>`:''}</div><div class="form-actions"><button class="btn" id="guideStop">Done for now</button><button class="btn primary" id="guideNext">${last?'Finish':'Next'}</button></div>`);$('#guideGo')?.addEventListener('click',()=>{closeDrawer();navigate(step[2]);setTimeout(()=>runGuide(key,index),250)});$('#guideStop').onclick=closeDrawer;$('#guideNext').onclick=()=>{closeDrawer();if(last){st[key]='completed';setGuideState(st);toast('Guide complete','good')}else setTimeout(()=>runGuide(key,index+1),120)}}

function queueSection(title,rows,action,tone){return `<div class="queue-section"><div class="queue-title">${title}<span class="count-badge">${rows.length}</span></div>${rows.length?rows.map(j=>`<div class="queue-row"><div class="queue-main"><strong>${esc(j.customer_name)}</strong><span>${esc(j.job_number)} · ${esc(j.description)}</span></div><div class="queue-secondary">${esc(j.next_action||'No next action')}<span>${j.city?esc(j.city):''}</span></div><div><span class="pill ${j.priority==='HIGH'?'high':tone}">${nice(j.status)}</span></div><div class="queue-action"><button class="btn small ${action==='Schedule'?'primary':''}" data-job="${j.id}">${action}</button></div></div>`).join(''):`<div class="empty"><strong>All clear.</strong><span>Nothing in this group needs attention.</span></div>`}</div>`}

async function renderCustomers(){const rows=await api('/api/customers');setMain(`<div class="page-head"><div><h1>Customers</h1><p>Find the account first. ServiceSlate keeps the rest connected.</p></div><button class="btn primary" id="addCustomer">＋ Add customer</button></div><div class="toolbar"><input id="customerFilter" placeholder="Name, phone or email" aria-label="Filter customers"><span class="toolbar-spacer"></span><span class="tiny muted">${rows.length} customers</span></div><section class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Customer</th><th>Contact</th><th>Locations</th><th>Equipment</th><th>Status</th></tr></thead><tbody id="customerRows">${customerRows(rows)}</tbody></table></div></section>`);$('#addCustomer').onclick=openNewCustomer;bindRemoteFilter('#customerFilter','#customerRows',q=>api('/api/customers?q='+encodeURIComponent(q)),customerRows);}
function customerRows(rows){return rows.map(c=>`<tr><td><button class="link" onclick="openCustomer('${c.id}')"><strong>${esc(c.name)}</strong></button><div class="tiny muted">${esc(c.business_type||'Customer')}</div></td><td>${esc(c.phone||'—')}<div class="tiny muted">${esc(c.email||'')}</div></td><td>${c.location_count}</td><td>${c.equipment_count}</td><td><span class="pill good">${esc(c.status)}</span></td></tr>`).join('')}

async function renderJobs(){const rows=await api('/api/jobs');setMain(`<div class="page-head"><div><h1>Jobs</h1><p>One problem, one identity, complete history.</p></div><button class="btn primary" id="newJob">＋ New service request</button></div><div class="toolbar"><input id="jobFilter" placeholder="Search this list"><select id="statusFilter"><option value="">All states</option>${[...new Set(rows.map(r=>r.status))].map(s=>`<option>${s}</option>`).join('')}</select></div><section class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Work order</th><th>Customer</th><th>Work</th><th>Owner</th><th>Crew</th><th>Status</th></tr></thead><tbody id="jobRows">${jobRows(rows)}</tbody></table></div></section>`);$('#newJob').onclick=openNewJob;const filter=()=>{const q=$('#jobFilter').value.toLowerCase(),s=$('#statusFilter').value;$$('#jobRows tr').forEach(tr=>tr.hidden=!(tr.dataset.text.includes(q)&&(!s||tr.dataset.status===s)))};$('#jobFilter').oninput=filter;$('#statusFilter').onchange=filter;}
function jobRows(rows){return rows.map(j=>`<tr data-status="${j.status}" data-text="${esc(`${j.job_number} ${j.customer_name} ${j.description}`.toLowerCase())}"><td><button class="link" onclick="openJob('${j.id}')"><strong>${esc(j.job_number)}</strong></button><div class="tiny muted">${esc(j.job_type)}</div></td><td>${esc(j.customer_name)}<div class="tiny muted">${esc(j.city||'')}</div></td><td>${esc(j.description)}<div class="tiny muted">${esc([j.manufacturer,j.model,j.serial_number].filter(Boolean).join(' · '))}</div></td><td>${esc(j.owner_name||'Unassigned')}</td><td><span class="pill ${j.crew_min>1?'warn':''}">${j.crew_min} tech${j.crew_min>1?'s':''}</span></td><td><span class="pill ${j.status==='BLOCKED'?'warn':j.status==='READY_TO_INVOICE'?'good':'blue'}">${nice(j.status)}</span></td></tr>`).join('')}

async function renderEquipment(){const rows=await api('/api/equipment');setMain(`<div class="page-head"><div><h1>Equipment</h1><p>Permanent equipment identity and lifetime service memory.</p></div></div><div class="toolbar"><input id="eqFilter" placeholder="Serial, model, manufacturer or customer" aria-label="Filter equipment"></div><section class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Equipment</th><th>Customer</th><th>Location</th><th>Serial</th><th>Status</th></tr></thead><tbody id="eqRows">${equipmentRows(rows)}</tbody></table></div></section>`);bindRemoteFilter('#eqFilter','#eqRows',q=>api('/api/equipment?q='+encodeURIComponent(q)),equipmentRows);}
function equipmentRows(rows){return rows.map(e=>`<tr><td><button class="link" onclick="openEquipment('${e.id}')"><strong>${esc(e.manufacturer||'')} ${esc(e.model||e.category)}</strong></button><div class="tiny muted">${esc(e.category)} · ${esc(e.bay||'No bay')}</div></td><td>${esc(e.customer_name)}</td><td>${esc(e.location_name)}<div class="tiny muted">${esc(e.city||'')}</div></td><td class="mono">${esc(e.serial_number||'—')}</td><td><span class="pill good">${esc(e.operational_status)}</span></td></tr>`).join('')}
window.openEquipment=async id=>{const d=await api(`/api/equipment/${id}/history`),e=d.equipment,canEdit=state.me.organization_profile==='automotive_equipment';openDrawer(`${e.manufacturer||''} ${e.model||e.category}`,`${e.customer_name} · ${e.location_name}`,`<div class="record-hero"><div><span class="pill ${tone(e.operational_status)}">${nice(e.operational_status||'ACTIVE')}</span><h2>${esc(e.manufacturer||'')} ${esc(e.model||e.category)}</h2><p>Serial <span class="mono">${esc(e.serial_number||'Not recorded')}</span> · ${esc(e.bay||'No bay')}</p></div><div class="next-box"><small>Inspection due</small><strong>${e.inspection_due_date?fmtDate(e.inspection_due_date):'Not set'}</strong></div></div><div class="drawer-toolbar">${canEdit?`<button class="btn small" onclick="openEquipmentEdit('${e.id}')">Edit Equipment</button>`:''}${e.serial_number?`<button class="btn small" onclick="window.open('/api/tools/equipment_print/download?serial=${encodeURIComponent(e.serial_number)}','_blank')">Print History</button>`:''}<button class="btn small" onclick="openFilePicker('equipment','${e.id}')">＋ File / Photo</button><button class="btn small" onclick="runGuide('history',0)">? History Guide</button></div><div class="context-card"><h3>Identity & lifecycle</h3><div class="content">Category: ${esc(e.category)}<br>Installed: ${fmtDate(e.install_date)}<br>Warranty: ${e.warranty_until?fmtDate(e.warranty_until):'Not recorded'}${e.notes?`<br><br>${esc(e.notes)}`:''}</div></div><div class="context-card"><h3>Approved service history</h3><div class="content">${d.approved_work.map(w=>`<article class="service-story"><header><strong>${esc(w.job_number)} · ${esc(w.description)}</strong><span>${fmtDate(w.performed_at||w.reviewed_at||w.submitted_at||w.created_at)}</span></header><div class="service-story-grid"><div><small>Complaint</small><p>${esc(w.complaint||w.description||'—')}</p></div><div><small>Finding</small><p>${esc(w.finding||'—')}</p></div><div><small>Cause</small><p>${esc(w.cause||'Not established')}</p></div><div><small>Correction</small><p>${esc(w.correction||w.customer_report||'—')}</p></div><div class="story-wide"><small>Verification</small><p>${esc(w.verification||'—')}</p></div></div>${w.measurements?.length?`<div class="story-evidence"><strong>Measurements</strong>${w.measurements.map(m=>`<span>${esc(m.name)}: ${m.before??'—'} → ${m.after??m.value??'—'} ${esc(m.unit||'')}</span>`).join('')}</div>`:''}${w.parts?.length?`<div class="story-evidence"><strong>Parts</strong>${w.parts.map(x=>`<span>${esc(x.part||x.name||x.description||'Part')}${x.qty?` × ${x.qty}`:''}</span>`).join('')}</div>`:''}<footer><span class="pill good">Human approved</span>${w.reviewed_by_name?`<span>Approved by ${esc(w.reviewed_by_name)}</span>`:''}</footer></article>`).join('')||'No approved work recorded.'}</div></div>`) };
window.openEquipmentEdit=async id=>{const d=await api(`/api/equipment/${id}/history`),e=d.equipment;openDrawer('Edit Equipment','Correct the current record; previous values remain auditable.',`<form id="equipmentEdit"><div class="form-grid"><div class="field"><label>Serial number</label><input name="serial_number" value="${esc(e.serial_number||'')}"></div><div class="field"><label>Bay / area</label><input name="bay" value="${esc(e.bay||'')}"></div><div class="field"><label>Operational status</label><select name="operational_status">${['ACTIVE','OUT_OF_SERVICE','RESTRICTED','RETIRED'].map(x=>`<option ${e.operational_status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Warranty until</label><input type="date" name="warranty_until" value="${esc((e.warranty_until||'').slice(0,10))}"></div><div class="field"><label>Inspection due</label><input type="date" name="inspection_due_date" value="${esc((e.inspection_due_date||'').slice(0,10))}"></div><div class="field"><label>Inspection interval</label><select name="inspection_interval_months"><option value="">Not set</option><option value="6" ${e.inspection_interval_months===6?'selected':''}>6 months</option><option value="12" ${e.inspection_interval_months===12?'selected':''}>12 months</option><option value="24" ${e.inspection_interval_months===24?'selected':''}>24 months</option></select></div></div><div class="field"><label>Notes</label><textarea name="notes">${esc(e.notes||'')}</textarea></div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Save Equipment</button></div></form>`);$('#equipmentEdit').onsubmit=async ev=>{ev.preventDefault();const b=Object.fromEntries(new FormData(ev.target).entries());b.version=e.version;b.inspection_interval_months=b.inspection_interval_months?+b.inspection_interval_months:null;for(const k of ['serial_number','bay','warranty_until','inspection_due_date','notes'])b[k]=b[k]||null;try{await api(`/api/equipment/${id}`,{method:'PATCH',body:JSON.stringify(b)});toast('Equipment updated — history preserved','good');closeDrawer();openEquipment(id)}catch(err){toast(err.message,'bad')}}};

async function renderCalendar(){
 if(state.me.organization_profile==='grooming')return renderGroomCalendar();
 const [d,comp,confirmations]=await Promise.all([api('/api/calendar'),api('/api/compass'),api('/api/service-confirmations')]);
 const now=Date.now(),horizon=now+7*86400000,activeVisits=d.visits.filter(v=>v.execution_status!=='CANCELED'&&Date.parse(v.end_at)>=now-12*3600000&&Date.parse(v.start_at)<=horizon);
 const byTech=Object.fromEntries(d.technicians.map(t=>[t.id,[]]));
 activeVisits.forEach(v=>{(byTech[v.technician_user_id] ||= []).push(v);if(v.helper_user_id)(byTech[v.helper_user_id] ||= []).push({...v,isHelper:true,end_at:v.helper_end_at||v.end_at})});
 const currentConfirmations=confirmations.filter(c=>c.status!=='STALE'&&c.scheduled_date>=new Date().toISOString().slice(0,10));
 setMain(`<div class="page-head"><div><div class="eyebrow">Scheduling</div><h1>Calendar</h1><p>Plan the workday without turning internal estimates into customer promises.</p></div><div class="page-actions"><button class="btn" onclick="navigate('jobs')">All Work Orders</button></div></div>
 <div class="schedule-principle"><span class="principle-icon">◷</span><div><strong>Service-day scheduling by default</strong><p>Compass can arrange the day internally. Customers see only the commitment the office intentionally makes.</p></div></div>
 <div class="content-grid"><section><div class="panel" style="margin-bottom:15px"><div class="panel-head"><div><h2>Next 7 days</h2><p>Scheduled technician load with partial crew overlap respected.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Technician</th><th>Scheduled work</th><th>Visits</th><th>Planning note</th></tr></thead><tbody>${d.technicians.map(t=>{const vs=byTech[t.id]||[],total=vs.reduce((n,v)=>n+(Date.parse(v.end_at)-Date.parse(v.start_at))/60000,0);return `<tr><td><strong>${esc(t.name)}</strong></td><td>${total?mins(total):'<span class="muted">Open</span>'}</td><td>${vs.length}</td><td>${vs.some(v=>v.isHelper)?'<span class="pill warn">Crew assist included</span>':'<span class="pill blue">Available for matching</span>'}</td></tr>`}).join('')}</tbody></table></div></div>
 <div class="panel"><div class="panel-head"><div><h2>Ready to schedule</h2><p>Approved work waiting for a day and crew.</p></div><span class="count-badge">${d.unscheduled.length}</span></div>${d.unscheduled.map(j=>`<div class="queue-row"><div class="queue-main"><strong>${esc(j.customer_name)}</strong><span>${esc(j.job_number)} · ${esc(j.description)}</span></div><div class="queue-secondary">${esc(j.city)} · ${mins(j.estimated_minutes)}${j.crew_min>1?` · ${j.crew_min} techs`:''}</div><div><span class="pill ${j.crew_min>1?'warn':'blue'}">${nice(j.commitment_type)}</span></div><div class="queue-action"><button class="btn small primary" onclick="openSchedule('${j.id}')">Choose day & crew</button></div></div>`).join('')||'<div class="empty"><strong>Scheduling is caught up.</strong><span>No approved work is waiting for placement.</span></div>'}</div></section>
 <aside class="suggestion-col"><section class="panel"><div class="panel-head"><div><h2>Customer awareness</h2><p>Sent is not the same as confirmed.</p></div></div><div class="panel-body">${currentConfirmations.slice(0,6).map(c=>`<div class="compact-item"><div><strong>${esc(c.customer_name)}</strong><span>${fmtDate(c.scheduled_date)} · ${esc(c.job_number)}</span></div><span class="pill ${tone(c.status)}">${nice(c.status)}</span></div>`).join('')||'<div class="empty"><strong>No confirmations waiting.</strong><span>Scheduled-day acknowledgements will appear here.</span></div>'}</div></section>
 <section class="panel aside-gap"><div class="panel-head"><div><h2>Compass</h2><p>Explainable crew and geographic fit.</p></div></div><div class="panel-body">${comp.suggestions.slice(0,5).map(s=>`<div class="suggestion"><h3>${esc(s.customer)} · ${esc(s.job_number)}</h3><p>${esc(s.reason)}</p><button class="btn small" onclick="openSchedule('${s.job_id}')">Review fit</button></div>`).join('')||'<div class="empty">No placement suggestions right now.</div>'}</div></section></aside></div>`)
}
window.openSchedule=async jobId=>{
 const [cal,comp]=await Promise.all([api('/api/calendar'),api('/api/compass')]),job=cal.unscheduled.find(j=>j.id===jobId),sug=comp.suggestions.find(s=>s.job_id===jobId);
 if(!job)return toast('This work order is no longer waiting to schedule','bad');
 const tomorrow=new Date(Date.now()+86400000),day=tomorrow.toISOString().slice(0,10);
 openDrawer(`Schedule ${job.job_number}`,job.customer_name,`<div class="schedule-summary"><span class="pill blue">${nice(job.commitment_type)}</span><strong>${esc(job.description)}</strong><p>${esc(sug?.reason||'Choose a qualified technician and a workable day.')}</p></div><form id="scheduleForm"><div class="field"><label>Primary technician</label><select id="schedTech">${cal.technicians.map(t=>`<option value="${t.id}" ${sug?.recommended_technicians?.[0]===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div>${job.crew_min>1?`<div class="field"><label>Second technician</label><select id="schedHelper"><option value="">Choose second technician</option>${cal.technicians.map(t=>`<option value="${t.id}" ${sug?.recommended_technicians?.[1]===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div>`:''}<div class="form-grid"><div class="field"><label>Service day</label><input id="schedDate" type="date" value="${day}"></div><div class="field"><label>Internal planning start</label><input id="schedTime" type="time" value="08:00"><small class="muted">Used for workload planning. It is not shown as a customer promise unless an exact-time commitment is intentionally created.</small></div></div><div class="field"><label>Expected work time</label><input value="${mins(job.estimated_minutes)}" disabled></div><div class="service-day-inline"><strong>Customer wording stays simple</strong><span>“Your service is scheduled for <b>the service day</b>.” Arrival order stays internal.</span></div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Schedule Work</button></div></form>`);
 $('#scheduleForm').onsubmit=async e=>{e.preventDefault();const start=new Date(`${$('#schedDate').value}T${$('#schedTime').value}:00`),end=new Date(start.getTime()+job.estimated_minutes*60000);try{await api('/api/schedule',{method:'POST',body:JSON.stringify({command_id:uid(),job_id:job.id,technician_user_id:$('#schedTech').value,helper_user_id:$('#schedHelper')?.value||null,start_at:start.toISOString(),end_at:end.toISOString()})});toast('Scheduled — customer confirmation is still required','good');closeDrawer();renderCalendar()}catch(err){toast(err.message,'bad')}}
};

async function renderReviews(){const rows=await api('/api/reviews');setMain(`<div class="page-head"><div><h1>Technician Work Review</h1><p>Clean submissions should take seconds. Review only what matters.</p></div></div><section class="panel">${rows.length?rows.map(r=>`<div class="queue-row"><div class="queue-main"><strong>${esc(r.customer_name)}</strong><span>${esc(r.job_number)} · ${esc(r.description)}</span></div><div class="queue-secondary">${esc(r.technician_name)}<span>${r.validation.clean?'No issues detected':`Missing: ${r.validation.missing.join(', ')}`}</span></div><div><span class="pill ${r.validation.clean?'good':'warn'}">${r.validation.clean?'Ready to approve':'Needs review'}</span></div><div class="queue-action"><button class="btn small ${r.validation.clean?'primary':''}" onclick="openReview('${r.id}')">Review</button></div></div>`).join(''):`<div class="empty"><strong>Paperwork caught up.</strong>No technician submissions need review.</div>`}</section>`)}
window.openReview=async id=>{const rows=await api('/api/reviews'),r=rows.find(x=>x.id===id);if(!r)return;openDrawer(`${r.job_number} · Work Review`,`${r.customer_name} · ${r.technician_name}`,`<div class="context-card"><h3>Technician record</h3><div class="content"><b>Complaint</b><br>${esc(r.complaint||'—')}<br><br><b>Finding</b><br>${esc(r.finding||'—')}<br><br><b>Cause</b><br>${esc(r.cause||'—')}<br><br><b>Correction</b><br>${esc(r.correction||'—')}<br><br><b>Verification</b><br>${esc(r.verification||'—')}</div></div><div class="context-card"><h3>Parts / measurements</h3><div class="content">${r.parts.length?r.parts.map(p=>`${esc(p.part||p.name)} × ${p.qty||1}`).join('<br>'):'No parts recorded'}<br>${r.measurements.length?r.measurements.map(m=>`${esc(m.name)}: ${m.before??'—'} → ${m.after??m.value??'—'} ${esc(m.unit||'')}`).join('<br>'):''}</div></div>${!r.validation.clean?`<div class="notice">Missing required completion fields: ${esc(r.validation.missing.join(', '))}</div>`:''}<div class="field"><label>Coordinator note (optional)</label><textarea id="reviewNote" placeholder="Only add a note if useful."></textarea></div><div class="form-actions"><button class="btn" id="returnWork">Return for correction</button><button class="btn primary" id="approveWork" ${r.validation.clean?'':'disabled'}>Approve</button></div>`);$('#approveWork').onclick=()=>reviewAction(r.id,'approve');$('#returnWork').onclick=()=>reviewAction(r.id,'return')};
async function reviewAction(id,action){try{await api(`/api/reviews/${id}`,{method:'POST',body:JSON.stringify({command_id:uid(),action,note:$('#reviewNote').value||null})});toast(action==='approve'?'Paperwork approved':'Returned to technician','good');closeDrawer();renderReviews()}catch(e){toast(e.message,'bad')}}




async function renderSearchPage(){setMain(`<div class="page-head"><div><h1>Search</h1><p>Search by customer, job, equipment or serial number.</p></div></div><div class="toolbar"><input id="searchPageInput" autofocus placeholder="Start typing…" value="${esc(state.pendingSearch||'')}"></div><div id="searchResults" class="panel"><div class="empty">Search company records.</div></div>`);$('#searchPageInput').oninput=e=>renderGlobalSearch(e.target.value,true);if(state.pendingSearch){const q=state.pendingSearch;state.pendingSearch='';await renderGlobalSearch(q,true)}}
function searchOpenAction(r){if(r.type==='equipment')return `openEquipment('${r.id}')`;if(r.type==='job'||r.type==='history')return `openJob('${r.id}')`;if(r.type==='customer')return state.me?.role==='TECHNICIAN'?`openTechCustomer('${r.id}')`:`openCustomer('${r.id}')`;if(r.type==='contact'&&r.customer_id)return `openCustomer('${r.customer_id}')`;if(r.type==='pet')return `navigate('pets')`;return 'void 0'}
async function renderGlobalSearch(q,inPage=false){if(!q||q.trim().length<2){if(inPage)$('#searchResults').innerHTML='<div class="empty">Type at least two characters.</div>';return}const rows=await api('/api/search?q='+encodeURIComponent(q.trim()));const html=rows.length?rows.map(r=>{const action=searchOpenAction(r),open=action==='void 0'?'':`<button class="btn small" onclick="${action}">Open</button>`;return `<div class="queue-row"><div class="queue-main"><strong>${esc(r.label)}</strong><span>${esc(r.subtitle||r.type)}</span></div><div><span class="pill blue">${esc(r.type)}</span></div><div></div><div class="queue-action">${open}</div></div>`}).join(''):'<div class="empty"><strong>No matches</strong>Try another term.</div>';if(inPage){$('#searchResults').innerHTML=html}else{openDrawer(`Search results`,q,html)}}

async function renderGroomDashboard(d){setMain(`<div class="page-head"><div><h1>Scheduling Assistant</h1><p>Keep appointments flowing.</p></div><button class="btn primary" id="groomQuick">＋ Book appointment</button></div><div class="stat-row"><div class="stat"><div class="stat-label">Appointments</div><div class="stat-value">${d.counts.appointments}</div><div class="stat-foot">On the schedule</div></div><div class="stat"><div class="stat-label">Forms incomplete</div><div class="stat-value">${d.counts.forms_incomplete}</div><div class="stat-foot">Needs customer action</div></div><div class="stat"><div class="stat-label">Rebooking cadence</div><div class="stat-value">${d.counts.rebooking_due}</div><div class="stat-foot">Pets with a recurring interval</div></div><div class="stat"><div class="stat-label">Profile</div><div class="stat-value" style="font-size:21px">Grooming</div><div class="stat-foot">No automotive modules loaded</div></div></div><div id="groom-grid"><section class="panel"><div class="panel-head"><div><h2>Upcoming appointments</h2><p>Customer, pet, service, next action.</p></div></div>${d.appointments.map(a=>`<div class="pet-row"><div><strong>${esc(a.customer_name)} · ${esc(a.pet_name)}</strong><span>${esc(a.breed||'')} · ${esc(a.service_name)}</span></div><div><strong>${esc(a.groomer_name||'Unassigned')}</strong><span>Groomer</span></div><div><strong>${fmtDate(a.start_at)} · ${fmtTime(a.start_at)}</strong><span>${a.forms_complete?'Forms complete':'Forms required'}</span></div><div><span class="pill ${a.forms_complete?'good':'warn'}">${esc(a.status.replaceAll('_',' '))}</span></div></div>`).join('')}</section><aside class="panel"><div class="panel-head"><div><h2>Purpose-built</h2><p>This organization loads grooming only.</p></div></div><div class="panel-body"><div class="suggestion"><h3>Low-friction front desk</h3><p>Pet, appointment, forms, safety information and rebooking stay connected without jobs, equipment, parts or vehicles.</p></div></div></aside></div>`);$('#groomQuick').onclick=openGroomingQuick;}
async function renderPets(){const rows=await api('/api/grooming/pets');state.groomPets=rows;setMain(`<div class="page-head"><div><h1>Pets</h1><p>Grooming history, preferences and safety context.</p></div>${state.me.role!=='READ_ONLY'?'<button class="btn primary" id="addPet">＋ Add Pet</button>':''}</div><section class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Pet</th><th>Customer</th><th>Breed</th><th>Preferred groomer</th><th>Safety</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td><button class="link" onclick="openPet('${p.id}')"><strong>${esc(p.name)}</strong></button></td><td>${esc(p.customer_name)}</td><td>${esc(p.breed||'—')}</td><td>${esc(p.preferred_groomer_name||'No preference')}</td><td>${p.safety_notes?`<span class="pill warn">Review notes</span>`:'<span class="pill good">No alert</span>'}</td><td><button class="btn small" onclick="openPet('${p.id}')">Open</button></td></tr>`).join('')}</tbody></table></div></section>`);if($('#addPet'))$('#addPet').onclick=openPetCreate}

async function openPetCreate(){const [customers,groomers]=await Promise.all([api('/api/customers'),api('/api/grooming/groomers')]);openDrawer('Add Pet','Only information useful for grooming and safety.',`<form id="petCreate"><div class="field"><label>Customer</label><select name="customer_id">${customers.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="form-grid"><div class="field"><label>Pet name</label><input name="name" required autofocus></div><div class="field"><label>Breed</label><input name="breed"></div><div class="field"><label>Weight (lb)</label><input name="weight_lbs" type="number" step=".1" min="0"></div><div class="field"><label>Coat type</label><input name="coat_type"></div><div class="field"><label>Preferred groomer</label><select name="preferred_groomer_user_id"><option value="">No preference</option>${groomers.map(g=>`<option value="${g.id}">${esc(g.name)}</option>`).join('')}</select></div><div class="field"><label>Typical return interval</label><select name="recurring_weeks"><option value="">Not set</option><option value="4">4 weeks</option><option value="6">6 weeks</option><option value="8">8 weeks</option><option value="10">10 weeks</option><option value="12">12 weeks</option></select></div></div><div class="field"><label>Safety / handling notes</label><textarea name="safety_notes" placeholder="Only information relevant to safe handling and grooming."></textarea></div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Add Pet</button></div></form>`);$('#petCreate').onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(e.target).entries()),body={...fd,weight_lbs:fd.weight_lbs?+fd.weight_lbs:null,recurring_weeks:fd.recurring_weeks?+fd.recurring_weeks:null,preferred_groomer_user_id:fd.preferred_groomer_user_id||null,safety_notes:fd.safety_notes||null};try{const r=await api('/api/grooming/pets',{method:'POST',body:JSON.stringify(body)});toast('Pet added','good');closeDrawer();await renderPets();openPet(r.id)}catch(err){toast(err.message,'bad')}}}
window.openPet=async id=>{const pets=state.groomPets?.length?state.groomPets:await api('/api/grooming/pets'),p=pets.find(x=>x.id===id);if(!p)return toast('Pet not found','bad');const forms=await api(`/api/forms/completions?pet_id=${encodeURIComponent(id)}`);openDrawer(p.name,`${p.customer_name} · ${p.breed||'Pet'}`,`<div class="record-hero"><div><h2>${esc(p.name)}</h2><p>${esc(p.breed||'')} ${p.weight_lbs?`· ${p.weight_lbs} lb`:''}${p.coat_type?` · ${esc(p.coat_type)}`:''}</p></div><div class="next-box"><small>Preferred groomer</small><strong>${esc(p.preferred_groomer_name||'No preference')}</strong></div></div>${p.safety_notes?`<div class="notice warn"><strong>Safety / handling</strong><br>${esc(p.safety_notes)}</div>`:''}<div class="context-card"><h3>Return preference</h3><div class="content">${p.recurring_weeks?`Usually return in ${p.recurring_weeks} weeks.`:'No recurring interval set.'}</div></div><div class="context-card"><h3>Forms & acknowledgements</h3><div class="content">${forms.map(f=>`<div class="history-item"><strong>${esc(f.template_name)}</strong><p>${nice(f.state)} · ${fmtDate(f.completed_at||f.created_at)}${f.completed_by_name?` · ${esc(f.completed_by_name)}`:''}</p></div>`).join('')||'No forms completed yet.'}</div></div><div class="form-actions"><button class="btn" onclick="openPetForm('${p.id}','${p.customer_id}')">Complete Form</button><button class="btn primary" onclick="closeDrawer();openGroomingQuick()">Book Appointment</button></div>`)};
async function openPetForm(petId,customerId){const templates=await api('/api/forms/templates');if(!templates.length)return toast('No published forms available','bad');openDrawer('Complete Pet Form','The exact published wording and version are preserved.',`<form id="petFormCompletion"><div class="field"><label>Form</label><select id="petFormTemplate">${templates.map(t=>`<option value="${t.id}">${esc(t.name)} · v${t.version}</option>`).join('')}</select></div><div id="petDynamicFields"></div><div class="field"><label>Completed / signed by</label><input name="completed_by_name"></div><div class="field"><label>Signature text (if required)</label><input name="signature_text"></div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Complete Form</button></div></form>`);const draw=()=>{const t=templates.find(x=>x.id===$('#petFormTemplate').value);$('#petDynamicFields').innerHTML=`<div class="form-wording">${esc(t.wording||'')}</div>`+t.schema.map(f=>formFieldHtml(f)).join('')};$('#petFormTemplate').onchange=draw;draw();$('#petFormCompletion').onsubmit=async e=>{e.preventDefault();const values={};$$('[data-form-key]').forEach(x=>values[x.dataset.formKey]=x.type==='checkbox'?x.checked:x.value);const fd=Object.fromEntries(new FormData(e.target).entries());await api('/api/forms/completions',{method:'POST',body:JSON.stringify({command_id:uid(),template_id:$('#petFormTemplate').value,customer_id:customerId,pet_id:petId,completed_by_name:fd.completed_by_name||null,signature_text:fd.signature_text||null,values,submit:true})});toast('Form completed','good');closeDrawer();openPet(petId)}}
function formFieldHtml(f){const req=f.required?' required':'';if(f.type==='long_text')return `<div class="field"><label>${esc(f.label)}${f.required?' *':''}</label><textarea data-form-key="${esc(f.key)}"${req}></textarea></div>`;if(f.type==='choice')return `<div class="field"><label>${esc(f.label)}${f.required?' *':''}</label><select data-form-key="${esc(f.key)}"${req}>${(f.options||[]).map(o=>`<option>${esc(o)}</option>`).join('')}</select></div>`;if(f.type==='checkbox')return `<label class="checkline"><input type="checkbox" data-form-key="${esc(f.key)}"> ${esc(f.label)}</label>`;return `<div class="field"><label>${esc(f.label)}${f.required?' *':''}</label><input data-form-key="${esc(f.key)}" type="${f.type==='number'?'number':f.type==='date'?'date':'text'}"${req}></div>`}

async function renderGroomCalendar(){const d=await api('/api/dashboard');renderGroomDashboard(d)}
function renderGroomerTech(d){setMain(`<div class="page-head"><div><div class="eyebrow">My work</div><h1>Today</h1><p>Your appointments, pet notes and forms—nothing else to sort through.</p></div></div><div class="mobile-shell"><div class="tech-list">${d.appointments.map(a=>`<div class="tech-job"><div><h3>${esc(a.pet_name)} · ${esc(a.customer_name)}</h3><p>${fmtTime(a.start_at)} · ${esc(a.service_name)} · ${esc(a.breed||'')}</p>${a.safety_notes?`<p style="color:#d8bf86">Safety note: ${esc(a.safety_notes)}</p>`:''}</div><div><span class="pill ${a.forms_complete?'good':'warn'}">${a.forms_complete?'Ready':'Forms'}</span><button class="btn small" onclick="openGroomAppointment('${a.id}')">Open</button></div></div>`).join('')}</div></div>`)}

window.openGroomAppointment=async id=>{
 const a=await api(`/api/grooming/appointments/${id}`);const terminal=['COMPLETED','CANCELED','NO_SHOW'].includes(a.status);const canCancel=['ADMIN','MANAGER','RECEPTION'].includes(state.me.role);
 openDrawer(`${a.pet_name} · ${a.service_name}`,`${a.customer_name} · ${fmtDate(a.start_at)} ${fmtTime(a.start_at)}`,`<div class="record-hero"><div><span class="pill ${tone(a.status)}">${nice(a.status)}</span><h2>${esc(a.pet_name)}</h2><p>${esc(a.breed||'')} ${a.weight_lbs?`· ${a.weight_lbs} lb`:''} · ${esc(a.groomer_name||'Unassigned')}</p></div></div>${a.safety_notes?`<div class="notice warn"><strong>Safety / handling</strong><br>${esc(a.safety_notes)}</div>`:''}<div class="context-card"><h3>Appointment</h3><div class="content">${fmtTime(a.start_at)} – ${fmtTime(a.end_at)}<br>${a.forms_complete?'Forms complete':'Forms still needed'}${a.customer_phone?`<br>${esc(a.customer_phone)}`:''}${a.checkout_note?`<br><br><b>Checkout:</b> ${esc(a.checkout_note)}`:''}</div></div>${!terminal?`<form id="groomCompleteForm"><div class="field"><label>Checkout note</label><textarea name="checkout_note" placeholder="What was done, coat/skin observations, preferences for next time…"></textarea></div><div class="field"><label>Bring them back in</label><select name="rebook_weeks"><option value="">No reminder</option><option value="4">4 weeks</option><option value="6" selected>6 weeks</option><option value="8">8 weeks</option><option value="10">10 weeks</option><option value="12">12 weeks</option></select></div><div class="form-actions">${canCancel?`<button type="button" class="btn danger" id="cancelGroomAppt">Cancel Appointment</button>`:''}<button class="btn primary">Complete Appointment</button></div></form>`:''}`);
 if(!terminal){$('#groomCompleteForm').onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(e.target).entries());try{await api(`/api/grooming/appointments/${id}/complete`,{method:'POST',body:JSON.stringify({command_id:uid(),checkout_note:fd.checkout_note||null,rebook_weeks:fd.rebook_weeks?+fd.rebook_weeks:null})});toast('Appointment completed; rebooking remembered','good');closeDrawer();navigate(state.view)}catch(err){toast(err.message,'bad')}};if(canCancel)$('#cancelGroomAppt').onclick=()=>cancelGroomAppointment(id)}
};
async function cancelGroomAppointment(id){let reason=await askText({title:'Cancel appointment',message:'Add a reason if it will help the team later.',label:'Reason (optional)',type:'textarea',confirmLabel:'Cancel Appointment'});if(reason===undefined)return;reason=reason||null;try{const r=await api(`/api/grooming/appointments/${id}/cancel`,{method:'POST',body:JSON.stringify({command_id:uid(),reason})});const matches=r.waitlist_matches||[];openDrawer('Opening created',matches.length?'ServiceSlate found waitlist matches for this opening.':'The appointment is canceled. No matching waitlist requests were found.',matches.length?`<div class="panel-body">${matches.map(m=>`<div class="history-item"><strong>${esc(m.pet_name)} · ${esc(m.customer_name)}</strong><p>${esc(m.breed||'')} · ${esc(m.service_name)}${m.notes?` · ${esc(m.notes)}`:''}</p></div>`).join('')}</div><div class="form-actions"><button class="btn primary" onclick="closeDrawer();navigate('waitlist')">Review Waitlist</button></div>`:'<div class="form-actions"><button class="btn primary" onclick="closeDrawer();navigate(\'dashboard\')">Done</button></div>')}catch(err){toast(err.message,'bad')}}
async function openGroomingQuick(){
 const [pets,groomers,services]=await Promise.all([api('/api/grooming/pets'),api('/api/grooming/groomers'),api('/api/service-catalog')]);
 if(!pets.length||!groomers.length)return toast('Add a pet and groomer first.','bad');
 const tomorrow=new Date(Date.now()+86400000).toISOString().slice(0,10),svcList=services.length?services:[{id:'fallback-full',name:'Full Groom',default_minutes:120},{id:'fallback-bath',name:'Bath & Tidy',default_minutes:90}];
 openDrawer('Book Appointment','Customer, pet, service, time. ServiceSlate fills routine duration from the service catalog.',`<form id="groomBookForm"><div class="field"><label>Pet</label><select id="groomPet" name="pet_id">${pets.map(p=>`<option value="${p.id}" data-pref="${p.preferred_groomer_user_id||''}">${esc(p.name)} · ${esc(p.customer_name)}</option>`).join('')}</select></div><div class="field"><label>Service</label><select id="groomService" name="service_name">${svcList.map(x=>`<option value="${esc(x.name)}" data-minutes="${x.default_minutes||60}">${esc(x.name)}</option>`).join('')}</select><div id="groomDefault" class="smart-default"></div></div><div class="field"><label>Groomer</label><select id="groomerSelect" name="groomer_user_id">${groomers.map(g=>`<option value="${g.id}">${esc(g.name)}</option>`).join('')}</select></div><div class="form-grid"><div class="field"><label>Date</label><input name="date" type="date" value="${tomorrow}" required></div><div class="field"><label>Start</label><input name="time" type="time" value="09:00" required></div><div class="field"><label>Duration</label><input id="groomDuration" name="duration" type="number" min="15" step="15" value="${svcList[0].default_minutes||60}" required></div><div class="field"><label>Forms</label><select name="forms_complete"><option value="false">Need forms</option><option value="true">Already complete</option></select></div></div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Book Appointment</button></div></form>`);
 const setPreferred=()=>{const opt=$('#groomPet').selectedOptions[0],pref=opt.dataset.pref;if(pref&&[...$('#groomerSelect').options].some(o=>o.value===pref))$('#groomerSelect').value=pref};
 const applyService=()=>{const opt=$('#groomService').selectedOptions[0],m=+opt.dataset.minutes||60;$('#groomDuration').value=m;$('#groomDefault').innerHTML=`<strong>Smart default:</strong> ${mins(m)}. Change it if this pet needs more or less time.`};
 $('#groomPet').onchange=setPreferred;$('#groomService').onchange=applyService;setPreferred();applyService();
 $('#groomBookForm').onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(e.target).entries());const start=new Date(`${fd.date}T${fd.time}:00`),end=new Date(start.getTime()+(+fd.duration)*60000);try{await api('/api/grooming/appointments',{method:'POST',body:JSON.stringify({command_id:uid(),pet_id:fd.pet_id,groomer_user_id:fd.groomer_user_id,service_name:fd.service_name,start_at:start.toISOString(),end_at:end.toISOString(),forms_complete:fd.forms_complete==='true'})});toast('Appointment booked','good');closeDrawer();renderDashboard()}catch(err){toast(err.message,'bad')}}
}

function openTeamAccount(member){if(!member)return;openDrawer('Account · '+member.name,'Administrators can unlock an account or issue a temporary password. ServiceSlate does not use security questions.',`<div class="notice"><strong>${esc(member.email||'')}</strong><p>${member.locked_until?'This account is currently locked.':'Account is available.'}</p></div><button class="btn block" id="unlockMember">Unlock Account</button><button class="btn block" id="resetMember">Issue Temporary Password</button>`);$('#unlockMember').onclick=async()=>{try{await api(`/api/security/users/${member.id}/unlock`,{method:'POST'});toast('Account unlocked','good');closeDrawer();renderTeam()}catch(err){toast(err.message,'bad')}};$('#resetMember').onclick=async()=>{const password=await askText({title:'Temporary password',message:'Use at least 12 characters. The person will be required to change it after signing in.',label:'Temporary password',type:'password',required:true,confirmLabel:'Reset Password'});if(!password)return;try{await api(`/api/security/users/${member.id}/reset-password`,{method:'POST',body:JSON.stringify({temporary_password:password,require_change:true})});toast('Temporary password issued','good');closeDrawer();renderTeam()}catch(err){toast(err.message,'bad')}}}
async function openForcedPasswordChange(){openDrawer('Choose Your Own Password','An administrator issued the current temporary password. Replace it before continuing with normal work.',`<form id="forcedPasswordForm"><div class="field"><label>Temporary password</label><input name="current_password" type="password" autocomplete="current-password" required></div><div class="field"><label>New password</label><input name="new_password" type="password" minlength="12" autocomplete="new-password" required><div class="tiny muted">Use at least 12 characters.</div></div><div class="form-actions"><button class="btn primary block">Save New Password</button></div></form>`);$('.drawer-close')?.remove();$('#forcedPasswordForm').onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.target).entries());try{await api('/api/security/password',{method:'POST',body:JSON.stringify(body)});state.me.force_password_change=false;toast('Password updated','good');closeDrawer();setTimeout(maybeWelcomeGuide,250)}catch(err){toast(err.message,'bad')}}}

async function openNewCustomer(){
 openDrawer('Add Customer','Start with the minimum. ServiceSlate can look up public business details, but you approve anything it finds.',`<form id="customerForm"><div class="field"><label>Business / customer name</label><input name="name" required autofocus></div><div class="form-grid"><div class="field"><label>Phone</label><input name="phone"></div><div class="field"><label>Email</label><input name="email" type="email"></div><div class="wide field"><label>Website</label><input name="website"></div><div class="wide field"><label>Address</label><input name="address1"></div><div class="field"><label>City</label><input name="city"></div><div class="field"><label>State</label><input name="state" value="CA"></div><div class="field"><label>ZIP</label><input name="postal_code"></div><div class="field"><label>Business type</label><input name="business_type" placeholder="Dealership, repair shop…"></div></div><div id="enrichmentResult"></div><div class="form-actions"><button type="button" class="btn" id="findBusiness">Find Public Details</button><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Create Customer</button></div></form>`);
 const form=$('#customerForm');
 $('#findBusiness').onclick=async()=>{const f=Object.fromEntries(new FormData(form).entries());if(!f.name.trim())return toast('Enter the business name first','bad');try{const r=await api('/api/cloud/business-enrichment',{method:'POST',body:JSON.stringify({business_name:f.name,address:[f.address1,f.city,f.state,f.postal_code].filter(Boolean).join(', '),website:f.website||null})});const c=r.candidates?.[0],wf=r.website_facts||{};$('#enrichmentResult').innerHTML=`<div class="notice"><strong>Public details found for review</strong><p>${c?esc(c.display_name):'No map candidate found.'}${wf.page_title?`<br>${esc(wf.page_title)}`:''}</p><div class="tiny muted">Nothing is added until you choose Use These Details and then create the customer.</div>${c||wf.phones?.length||wf.emails?.length?'<button type="button" class="btn small" id="useEnrichment">Use These Details</button>':''}</div>`;$('#useEnrichment')?.addEventListener('click',()=>{if(c?.address){form.elements.address1.value=form.elements.address1.value||[c.address.house_number,c.address.road].filter(Boolean).join(' ');form.elements.city.value=form.elements.city.value||c.address.city||c.address.town||c.address.village||'';form.elements.state.value=form.elements.state.value||c.address.state||'';form.elements.postal_code.value=form.elements.postal_code.value||c.address.postcode||''}if(wf.phones?.[0])form.elements.phone.value=form.elements.phone.value||wf.phones[0];if(wf.emails?.[0])form.elements.email.value=form.elements.email.value||wf.emails[0];toast('Public details copied into the draft — review before saving','good')})}catch(err){toast(err.message,'bad')}};
 form.onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.target).entries());body.command_id=uid();try{await api('/api/customers',{method:'POST',body:JSON.stringify(body)});toast('Customer created','good');closeDrawer();renderCustomers()}catch(err){toast(err.message,'bad')}}
}
async function openNewJob(customerId=null){
  const [customers,services]=await Promise.all([api('/api/customers'),api('/api/service-catalog')]);
  if(!customers.length)return openNewCustomer();
  const initialCustomer=customerId&&customers.some(c=>c.id===customerId)?customerId:customers[0].id;
  const serviceOptions=(services||[]).map(s=>`<option value="${s.id}">${esc(s.name)}${s.category?` · ${esc(s.category)}`:''}</option>`).join('');
  openDrawer('New Service Request','Tell ServiceSlate what is needed. It will fill the routine scheduling details.',`<form id="jobForm">
    <div class="field"><label>Customer</label><select id="jobCustomer" name="customer_id">${customers.map(c=>`<option value="${c.id}" ${c.id===initialCustomer?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div>
    <div id="locEquipFields"></div>
    <div class="field"><label>Service</label><select id="jobService"><option value="">Other / not sure yet</option>${serviceOptions}</select><div id="serviceDefaultNote" class="smart-default">Choose a service and ServiceSlate will suggest time, crew, and qualification.</div></div>
    <div class="field"><label>What do they need?</label><textarea name="description" required placeholder="Customer complaint or requested work"></textarea></div>
    <div class="form-grid">
      <div class="field"><label>Work type</label><select id="jobType" name="job_type"><option>Service Call</option><option>Repair</option><option>Inspection</option><option>Preventive Maintenance</option><option>Installation</option><option>Return Visit</option></select></div>
      <div class="field"><label>Expected time</label><select id="jobMinutes" name="estimated_minutes"><option value="30">30 minutes</option><option value="60">1 hour</option><option value="90">1.5 hours</option><option value="120" selected>2 hours</option><option value="180">3 hours</option><option value="240">4 hours</option><option value="360">6 hours</option><option value="480">8 hours</option></select></div>
      <div class="field"><label>Crew</label><select id="jobCrew" name="crew_min"><option value="1">1 technician</option><option value="2">2 technicians</option><option value="3">3 technicians</option></select></div>
      <div class="field"><label>Priority</label><select name="priority"><option value="NORMAL">Normal</option><option value="HIGH">High</option></select></div>
      <div class="field"><label>Customer commitment</label><select name="commitment_type"><option value="FLEXIBLE_DAY">Flexible day</option><option value="DAY_COMMITMENT">Specific day</option><option value="ARRIVAL_WINDOW">Arrival window</option><option value="EXACT_TIME">Exact time</option><option value="TENTATIVE">Tentative</option><option value="EMERGENCY">Emergency</option></select></div>
      <div class="field"><label>Required qualification</label><input id="jobQualification" name="qualification_required" placeholder="None required"></div>
    </div>
    <div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Create Request</button></div>
  </form>`);
  const loadCustomer=async()=>{
    const d=await api(`/api/customers/${$('#jobCustomer').value}`);
    $('#locEquipFields').innerHTML=`<div class="field"><label>Location</label><select name="location_id" required>${d.locations.map(l=>`<option value="${l.id}">${esc(l.name)}${l.city?` · ${esc(l.city)}`:''}</option>`).join('')}</select></div><div class="field"><label>Equipment <span class="muted">optional</span></label><select name="equipment_id"><option value="">Not selected</option>${d.equipment.map(e=>`<option value="${e.id}">${esc(e.manufacturer||'')} ${esc(e.model||e.category)}${e.serial_number?` · ${esc(e.serial_number)}`:''}</option>`).join('')}</select></div>`;
    if(!d.locations.length)$('#locEquipFields').innerHTML=`<div class="notice warn"><strong>This customer needs a location first.</strong><p>Open the customer and add a service location before creating work.</p></div>`;
  };
  const mapType=category=>{
    const c=(category||'').toLowerCase();
    if(c.includes('inspection'))return 'Inspection';
    if(c.includes('install'))return 'Installation';
    if(c.includes('maintenance')||c.includes('prevent'))return 'Preventive Maintenance';
    if(c.includes('repair'))return 'Repair';
    return 'Service Call';
  };
  const applyService=()=>{
    const svc=(services||[]).find(x=>x.id===$('#jobService').value);
    if(!svc){$('#serviceDefaultNote').textContent='No preset selected. Enter only the details you know.';return}
    const mins=String(svc.default_minutes||60),crew=String(svc.default_crew||1);
    const minSel=$('#jobMinutes'),crewSel=$('#jobCrew');
    if(![...minSel.options].some(o=>o.value===mins)){const o=document.createElement('option');o.value=mins;o.textContent=`${mins} minutes`;minSel.append(o)}
    if(![...crewSel.options].some(o=>o.value===crew)){const o=document.createElement('option');o.value=crew;o.textContent=`${crew} technicians`;crewSel.append(o)}
    minSel.value=mins;crewSel.value=crew;$('#jobQualification').value=svc.qualification_required||'';$('#jobType').value=mapType(svc.category);
    $('#serviceDefaultNote').innerHTML=`<strong>Smart default:</strong> ${svc.default_minutes||60} min · ${svc.default_crew||1} tech${(svc.default_crew||1)>1?'s':''}${svc.qualification_required?` · ${esc(svc.qualification_required)}`:''}. You can override any of it.`;
  };
  $('#jobCustomer').onchange=loadCustomer;$('#jobService').onchange=applyService;
  await loadCustomer();
  $('#jobForm').onsubmit=async e=>{
    e.preventDefault();
    const b=Object.fromEntries(new FormData(e.target).entries());b.command_id=uid();
    if(!b.location_id)return toast('Add a customer location before creating work.','bad');
    b.estimated_minutes=+b.estimated_minutes;b.crew_min=+b.crew_min;b.crew_recommended=b.crew_min;
    b.simultaneous_crew_minutes=b.crew_min>1?Math.min(60,b.estimated_minutes):0;b.equipment_id=b.equipment_id||null;b.qualification_required=b.qualification_required||null;
    try{const r=await api('/api/jobs',{method:'POST',body:JSON.stringify(b)});toast(`${r.job_number} created`,'good');closeDrawer();navigate(state.view==='dashboard'?'dashboard':'jobs')}catch(err){toast(err.message,'bad')}
  };
}

function openDrawer(title,subtitle,html){closeDrawer();state.drawerReturnFocus=document.activeElement;const back=document.createElement('div');back.className='drawer-backdrop';back.id='drawerBackdrop';back.innerHTML=`<aside class="drawer" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="drawer-head"><div><h2>${esc(title)}</h2><p>${esc(subtitle||'')}</p></div><button class="icon-btn" onclick="closeDrawer()" aria-label="Close">×</button></div><div class="drawer-body">${html}</div></aside>`;document.body.append(back);back.addEventListener('mousedown',e=>{if(e.target===back)closeDrawer()});setTimeout(()=>back.querySelector('[autofocus],input,select,textarea,button')?.focus(),0);}
window.closeDrawer=()=>{const back=$('#drawerBackdrop');if(!back)return;back.remove();if(state.drawerReturnFocus?.isConnected)state.drawerReturnFocus.focus();state.drawerReturnFocus=null;};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#drawerBackdrop'))closeDrawer()});

function openDraftDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DRAFT_DB,2);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains(DRAFT_STORE))db.createObjectStore(DRAFT_STORE);if(!db.objectStoreNames.contains(OUTBOX_STORE))db.createObjectStore(OUTBOX_STORE,{keyPath:'id'});if(!db.objectStoreNames.contains(CACHE_STORE))db.createObjectStore(CACHE_STORE);};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function localScope(){return state.me?`${state.me.organization_id}:${state.me.id}`:'anonymous'}
function scopedKey(k){return `${localScope()}:${k}`}
async function draftGet(k){try{const db=await openDraftDB();return await new Promise((res,rej)=>{const r=db.transaction(DRAFT_STORE).objectStore(DRAFT_STORE).get(scopedKey(k));r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}catch{return null}}
async function draftPut(k,v){const db=await openDraftDB();return new Promise((res,rej)=>{const tx=db.transaction(DRAFT_STORE,'readwrite');tx.objectStore(DRAFT_STORE).put(v,scopedKey(k));tx.oncomplete=res;tx.onerror=()=>rej(tx.error)})}
async function draftDelete(k){const db=await openDraftDB();return new Promise((res,rej)=>{const tx=db.transaction(DRAFT_STORE,'readwrite');tx.objectStore(DRAFT_STORE).delete(scopedKey(k));tx.oncomplete=res;tx.onerror=()=>rej(tx.error)})}
async function draftCount(){try{const db=await openDraftDB();return await new Promise((res,rej)=>{const r=db.transaction(DRAFT_STORE).objectStore(DRAFT_STORE).getAllKeys();r.onsuccess=()=>res((r.result||[]).filter(k=>String(k).startsWith(`${localScope()}:`)).length);r.onerror=()=>rej(r.error)})}catch{return 0}}

// --- V2 expanded product surfaces -------------------------------------------------
function miniAction(icon,label,view,count=''){return `<button class="action-tile" onclick="navigate('${view}')"><span class="action-icon">${icon}</span><span><strong>${esc(label)}</strong>${count!==''?`<small>${count} needs attention</small>`:''}</span>${count!==''?`<b>${count}</b>`:''}</button>`}
function liveWorkspaceCard(readiness){if(!readiness||readiness.is_demo)return '';const next=readiness.items.find(item=>!item.complete);return `<section class="live-workspace" aria-label="Live workspace launch checklist"><div class="live-workspace-copy"><div class="eyebrow">Live workspace</div><h2>${readiness.complete===readiness.total?'Your workspace is ready for daily use':'Make this your working system'}</h2><p>${readiness.complete===readiness.total?'Your essential business records and safeguards are in place.':'A few deliberate setup steps turn this into your company’s reliable source of truth.'}</p>${next?`<button class="btn primary small" onclick="navigate('${next.action}')">${esc(next.label)}</button>`:`<button class="btn small" onclick="navigate('system')">Review backups</button>`}</div><div class="launch-progress"><strong>${readiness.complete}<span>/${readiness.total}</span></strong><small>launch steps complete</small><div class="progress-track"><i style="width:${Math.round(readiness.complete/readiness.total*100)}%"></i></div></div><div class="launch-items">${readiness.items.map(item=>`<button class="launch-item ${item.complete?'complete':''}" onclick="navigate('${item.action}')"><span aria-hidden="true">${item.complete?'✓':'○'}</span><div><strong>${esc(item.label)}</strong><small>${esc(item.detail)}</small></div></button>`).join('')}</div></section>`}

async function renderDashboard(){
  const [d,readiness]=await Promise.all([api('/api/dashboard'),api('/api/workspace/readiness')]); state.dashboard=d;
  if(d.profile==='grooming') return renderGroomDashboardV2(d,readiness);
  const [compass,ops,followups,notes,confirmations]=await Promise.all([api('/api/compass'),api('/api/operations-summary'),api('/api/followups'),api('/api/notifications'),api('/api/service-confirmations')]);
  const confirmationCount=confirmations.filter(c=>['AWAITING_CONFIRMATION','CHANGE_REQUESTED','STALE'].includes(c.status)).length;
  const q=d.queues;
  setMain(`<div class="page-head"><div><div class="eyebrow">Today</div><h1>${state.me.role==='BILLING'?'Billing Ready':'Coordinator Assist'}</h1><p>${state.me.role==='BILLING'?'Completed work and estimates that need billing attention.':'The few things that need a person to decide.'}</p></div><div class="page-actions"><button class="btn" onclick="navigate('reviews')">Review paperwork</button><button class="btn primary" id="newJob">＋ New service request</button></div></div>
  <div class="stat-row"><div class="stat"><div class="stat-label">New requests</div><div class="stat-value">${d.counts.new_requests}</div><div class="stat-foot">Needs triage</div></div><div class="stat"><div class="stat-label">Ready to schedule</div><div class="stat-value">${d.counts.needs_scheduling}</div><div class="stat-foot">Ready to place</div></div><div class="stat"><div class="stat-label">Open parts holds</div><div class="stat-value">${ops.parts_open}</div><div class="stat-foot">Waiting on parts</div></div><div class="stat"><div class="stat-label">Work review</div><div class="stat-value">${d.counts.reviews}</div><div class="stat-foot">Ready for sign-off</div></div></div>
  <div class="action-strip">${miniAction('✓','Customer Confirmations','calendar',confirmationCount)}${miniAction('▤','FastField Review','tools',d.counts.fastfield_review||0)}${miniAction('⌁','Parts','parts',ops.parts_open)}${miniAction('↻','Recurring','recurring',ops.recurring_due_45)}${miniAction('$','Estimates','estimates',ops.estimates_open)}${miniAction('◷','Follow-ups','followups',ops.followups_due)}</div>
  <div class="content-grid"><section class="panel"><div class="panel-head"><div><h2>Needs You Now</h2><p>Only work that needs a decision or follow-through.</p></div></div>${queueSection('New requests',q.new_requests,'Review','blue')}${queueSection('Needs scheduling',q.needs_scheduling,'Schedule','good')}${queueSection('Blocked / waiting',q.blocked,'Review','warn')}${queueSection('Work completed',q.work_complete,'Review','blue')}</section>
  <aside class="suggestion-col"><section class="panel"><div class="panel-head"><div><h2>Compass</h2><p>Explainable staffing guidance.</p></div></div><div class="panel-body">${compass.suggestions.slice(0,3).map(s=>`<div class="suggestion"><h3>${esc(s.customer)} · ${esc(s.job_number)}</h3><p>${esc(s.reason)}</p><button class="btn small" onclick="openSchedule('${s.job_id}')">Review assignment</button></div>`).join('')||'<div class="empty"><strong>No placement suggestions.</strong>Nothing needs scheduling.</div>'}${compass.duplication_warnings?.length?`<div class="notice"><b>Area overlap</b><br>${esc(compass.duplication_warnings[0].customer_a)} and ${esc(compass.duplication_warnings[0].customer_b)} are about ${compass.duplication_warnings[0].distance_miles} mi apart with different technicians.</div>`:''}</div></section>
  <section class="panel aside-gap"><div class="panel-head"><div><h2>Due follow-ups</h2><p>Things a person promised to remember.</p></div></div><div class="panel-body">${followups.slice(0,4).map(f=>`<div class="compact-item"><div><strong>${esc(f.customer_name||f.kind)}</strong><span>${esc(f.summary)}</span></div><span class="pill ${f.due_at&&f.due_at.slice(0,10)<=new Date().toISOString().slice(0,10)?'warn':'blue'}">${f.due_at?fmtDate(f.due_at):'No date'}</span></div>`).join('')||'<div class="empty">No pending follow-ups.</div>'}</div></section>
  ${(d.fastfield_batches||[]).length?`<section class="panel aside-gap"><div class="panel-head"><div><h2>FastField waiting for review</h2><p>Extracted information stays untrusted until a person accepts it.</p></div></div><div class="panel-body">${d.fastfield_batches.slice(0,3).map(b=>`<div class="compact-item"><div><strong>${esc(b.filename||'FastField submission')}</strong><span>${b.ready_count} ready · ${b.issue_count} need attention</span></div><button class="btn small" onclick="openImportReview('${b.id}')">Review</button></div>`).join('')}</div></section>`:''}${notes.some(n=>!n.read_at)?`<section class="panel aside-gap"><div class="panel-head"><div><h2>Quiet alerts</h2></div></div><div class="panel-body">${notes.filter(n=>!n.read_at).slice(0,3).map(n=>`<div class="compact-item"><div><strong>${esc(n.kind)}</strong><span>${esc(n.summary)}</span></div></div>`).join('')}</div></section>`:''}</aside></div>`);
  if(!readiness.is_demo) $('.main')?.insertAdjacentHTML('afterbegin',liveWorkspaceCard(readiness));
  $('#newJob')?.addEventListener('click',openNewJob); $$('[data-job]').forEach(b=>b.onclick=()=>openJob(b.dataset.job));
}

window.openCustomer=async id=>{
  const d=await api(`/api/customer-workspace/${id}`), c=d.customer;
  openDrawer(c.name,`${d.locations.length} location${d.locations.length===1?'':'s'} · ${d.equipment.length} equipment · ${d.jobs.length} work records`,`
  <div class="drawer-toolbar"><button class="btn small" id="editCustomerBtn">Edit Account</button><button class="btn small" id="addContactBtn">＋ Contact</button><button class="btn small" id="logContactBtn">Log Contact</button><button class="btn small" id="addLocationBtn">＋ Location</button>${state.me.organization_profile==='automotive_equipment'?'<button class="btn small" id="addEquipmentBtn">＋ Equipment</button>':''}<button class="btn small primary" id="newCustomerJob">＋ Service request</button></div>
  <div class="workspace-grid"><div>
   <div class="context-card"><h3>Account</h3><div class="content"><b>${esc(c.phone||'No phone')}</b><br>${esc(c.email||'No email')}${c.website?`<br>${esc(c.website)}`:''}${c.business_type?`<br><span class="pill blue">${esc(c.business_type)}</span>`:''}</div></div>
   <div class="context-card"><h3>Contacts</h3><div class="content">${d.contacts.map(x=>`<div class="history-item"><strong>${esc(x.name)}</strong><p>${esc(x.title||'')} ${x.phone?`· ${esc(x.phone)}`:''}${x.email?`<br>${esc(x.email)}`:''}</p>${x.can_approve_estimates?'<span class="pill good">Can approve estimates</span>':''} ${x.can_sign_work?'<span class="pill blue">Can sign work</span>':''}</div>`).join('')||'No contacts added yet.'}</div></div>
   <div class="context-card"><h3>Locations</h3><div class="content">${d.locations.map(l=>`<div class="history-item"><strong>${esc(l.name)}</strong><p>${esc([l.address1,l.city,l.state,l.postal_code].filter(Boolean).join(', '))}</p>${l.access_notes?`<p><b>Access:</b> ${esc(l.access_notes)}</p>`:''}</div>`).join('')}</div></div>
  </div><div>
   ${state.me.organization_profile==='automotive_equipment'?`<div class="context-card"><h3>Equipment</h3><div class="content">${d.equipment.map(e=>`<div class="history-item"><button class="link" onclick="openEquipment('${e.id}')"><strong>${esc(e.manufacturer||'')} ${esc(e.model||e.category)}</strong></button><p>${esc(e.serial_number||'No serial')} · ${esc(e.bay||'No bay')}</p></div>`).join('')||'No equipment recorded.'}</div></div>`:''}
   <div class="context-card"><h3>Recent work</h3><div class="content">${d.jobs.slice(0,10).map(j=>`<div class="history-item"><button class="link" onclick="openJob('${j.id}')"><strong>${esc(j.job_number)} · ${esc(j.description)}</strong></button><p><span class="pill ${tone(j.status)}">${nice(j.status)}</span> · ${esc(j.next_action||'')}</p></div>`).join('')||'No work history yet.'}</div></div>
   ${d.recurring.length?`<div class="context-card"><h3>Recurring obligations</h3><div class="content">${d.recurring.map(r=>`<div class="history-item"><strong>${esc(r.service_name)}</strong><p>Next due ${fmtDate(r.next_due_date)} · every ${r.frequency_months} months</p></div>`).join('')}</div></div>`:''}
   ${d.estimates.length?`<div class="context-card"><h3>Estimates</h3><div class="content">${d.estimates.slice(0,5).map(e=>`<div class="history-item"><button class="link" onclick="openEstimate('${e.id}')"><strong>${esc(e.estimate_number)} r${e.revision}</strong></button><p>${money(e.total_cents)} · ${nice(e.status)}</p></div>`).join('')}</div></div>`:''}
   <div class="context-card"><h3>Contact history</h3><div class="content">${(d.communications||[]).slice(0,8).map(m=>`<div class="history-item communication-history"><div><strong>${nice(m.direction)} ${nice(m.channel)}${m.contact_name?` · ${esc(m.contact_name)}`:''}</strong><p>${esc(m.subject||m.outcome||m.body||'Contact logged')}<br>${fmtDate(m.occurred_at)} ${fmtTime(m.occurred_at)} · <span class="pill ${m.status==='PREPARED'?'warn':m.status==='FAILED'?'high':'good'}">${nice(m.status)}</span>${m.delivery_provider?` · ${esc(nice(m.delivery_provider))}`:''}</p></div>${['PREPARED','FAILED'].includes(m.status)&&m.direction==='OUTBOUND'&&['EMAIL','SMS'].includes(m.channel)?`<button class="btn small" onclick="sendPreparedCommunication('${m.id}','${m.channel}')">Send</button>`:''}</div>`).join('')||'No contact history yet.'}</div></div>
  </div></div>`);
  $('#newCustomerJob').onclick=()=>{closeDrawer();openNewJob(id)};
  $('#editCustomerBtn').onclick=()=>openCustomerEdit(c);
  $('#addContactBtn').onclick=()=>openAddContact(id,d.locations);
  $('#logContactBtn').onclick=()=>openLogContact(id,d.contacts,d.jobs);
  $('#addLocationBtn').onclick=()=>openAddLocation(id);
  $('#addEquipmentBtn')?.addEventListener('click',()=>openAddEquipment(id,d.locations));
};

function openCustomerEdit(c){openDrawer('Edit Customer','Update the existing account. ServiceSlate keeps the old values in history.',`<form id="customerEdit"><div class="field"><label>Business / customer name</label><input name="name" value="${esc(c.name)}" required></div><div class="form-grid"><div class="field"><label>Phone</label><input name="phone" value="${esc(c.phone||'')}"></div><div class="field"><label>Email</label><input name="email" type="email" value="${esc(c.email||'')}"></div><div class="field"><label>Website</label><input name="website" value="${esc(c.website||'')}"></div><div class="field"><label>Business type</label><input name="business_type" value="${esc(c.business_type||'')}"></div><div class="field"><label>Status</label><select name="status"><option ${c.status==='ACTIVE'?'selected':''}>ACTIVE</option><option ${c.status==='INACTIVE'?'selected':''}>INACTIVE</option></select></div></div><div class="field"><label>Account notes</label><textarea name="notes">${esc(c.notes||'')}</textarea></div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Save Changes</button></div></form>`);$('#customerEdit').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target).entries());for(const k of ['phone','email','website','business_type','notes'])b[k]=b[k]||null;b.version=c.version;try{await api(`/api/customers/${c.id}`,{method:'PATCH',body:JSON.stringify(b)});toast('Customer updated — history preserved','good');closeDrawer();openCustomer(c.id)}catch(err){toast(err.message,'bad')}}}

function openLogContact(customerId,contacts=[],jobs=[]){openDrawer('Log Customer Contact','Record the conversation once. Email/SMS stay “prepared” until a real transport is connected.',`<form id="contactLog"><div class="form-grid"><div class="field"><label>Channel</label><select name="channel"><option>PHONE</option><option>EMAIL</option><option>IN_PERSON</option><option>SMS</option><option>OTHER</option></select></div><div class="field"><label>Direction</label><select name="direction"><option>OUTBOUND</option><option>INBOUND</option></select></div><div class="field"><label>Contact</label><select name="contact_id"><option value="">General customer contact</option>${contacts.map(c=>`<option value="${c.id}">${esc(c.name)}${c.title?` · ${esc(c.title)}`:''}</option>`).join('')}</select></div><div class="field"><label>Related work</label><select name="job_id"><option value="">Not tied to a job</option>${jobs.slice(0,20).map(j=>`<option value="${j.id}">${esc(j.job_number)} · ${esc(j.description)}</option>`).join('')}</select></div></div><div class="field"><label>Subject / reason</label><input name="subject" placeholder="Scheduling, estimate follow-up, callback…"></div><div class="field"><label>What happened?</label><textarea name="body" required placeholder="Short factual summary"></textarea></div><div class="field"><label>Outcome</label><input name="outcome" placeholder="Confirmed, left voicemail, requested callback…"></div><div class="panel inset"><div class="panel-head"><div><h3>Remember something later?</h3><p>Optional. This becomes a real follow-up obligation.</p></div></div><div class="panel-body"><div class="field"><label>Follow-up</label><input name="followup_summary" placeholder="Call back after parts arrive"></div><div class="field"><label>Due</label><input type="date" name="followup_due_at"></div></div></div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Save Contact</button></div></form>`);$('#contactLog').onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(e.target).entries());for(const k of ['contact_id','job_id','subject','outcome','followup_summary','followup_due_at'])fd[k]=fd[k]||null;try{const r=await api(`/api/customers/${customerId}/communications`,{method:'POST',body:JSON.stringify({command_id:uid(),...fd})});toast(r.status==='PREPARED'?'Message prepared — delivery is not connected':'Contact logged','good');closeDrawer();openCustomer(customerId)}catch(err){toast(err.message,'bad')}}}

async function sendPreparedCommunication(id,channel){const providers=await api('/api/integrations/catalog');const eligible=channel==='EMAIL'?providers.filter(p=>['OUTLOOK','SMTP','O365_OUTBOUND','APPRISE','WEBHOOK'].includes(p.id)&&['CONNECTED','CONFIGURED'].includes(p.state)):providers.filter(p=>['TWILIO_SMS','APPRISE','WEBHOOK'].includes(p.id)&&['CONNECTED','CONFIGURED'].includes(p.state));if(!eligible.length){const handoff=providers.find(p=>p.id==='MOBILE_SMS');openDrawer('No automatic transport connected',channel==='SMS'?'You can still use your paired phone/carrier without paying for an SMS API.':'You can still draft this in the computer’s normal email app.',`${channel==='SMS'?`<div class="notice"><strong>Use the phone you already have.</strong><p>Open Phone Link, Google Messages for web, KDE Connect, or the device SMS composer. ServiceSlate keeps this message as Ready to send until you confirm it was sent.</p></div>${(handoff?.links||[]).map(l=>`<a class="btn block integration-link" href="${esc(l.url)}" target="_blank" rel="noopener">${esc(l.label)} ↗</a>`).join('')}`:'<div class="notice"><strong>Email transport is optional.</strong><p>Connect SMTP or Microsoft 365 in Tools & Connections for one-click delivery, or use Draft in Email App from the Toolbox.</p></div>'}<button class="btn block" onclick="closeDrawer();navigate('tools')">Open Tools & Connections</button>`);return}openDrawer('Send prepared message','Choose the transport. ServiceSlate records the result; a failed provider never turns into a fake “sent.”',`<div class="choice-stack">${eligible.map(p=>`<button class="choice-card" data-send-provider="${p.id}"><strong>${esc(p.name)}</strong><span>${esc(p.description)}</span></button>`).join('')}</div>`);$$('[data-send-provider]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api(`/api/integrations/communications/${id}/deliver`,{method:'POST',body:JSON.stringify({provider:b.dataset.sendProvider})});toast('Message sent','good');closeDrawer()}catch(err){toast(err.message,'bad');b.disabled=false}})}

function openAddContact(customerId,locations=[]){openDrawer('Add Contact','Keep approval authority explicit.',`<form id="contactForm"><div class="field"><label>Name</label><input name="name" required autofocus></div><div class="form-grid"><div class="field"><label>Title</label><input name="title"></div><div class="field"><label>Location</label><select name="location_id"><option value="">All / account</option>${locations.map(l=>`<option value="${l.id}">${esc(l.name)}</option>`).join('')}</select></div><div class="field"><label>Phone</label><input name="phone"></div><div class="field"><label>Email</label><input name="email" type="email"></div></div><label class="checkline"><input type="checkbox" name="can_approve_estimates"> Can approve estimates</label><label class="checkline"><input type="checkbox" name="can_sign_work"> Can sign completed work</label><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Add Contact</button></div></form>`);$('#contactForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),b=Object.fromEntries(f.entries());b.location_id=b.location_id||null;b.can_approve_estimates=f.has('can_approve_estimates');b.can_sign_work=f.has('can_sign_work');await api(`/api/customers/${customerId}/contacts`,{method:'POST',body:JSON.stringify(b)});toast('Contact added','good');closeDrawer();openCustomer(customerId)}}
function openAddLocation(customerId){openDrawer('Add Location','Only information useful for service.',`<form id="locationForm"><div class="field"><label>Location name</label><input name="name" required placeholder="Main Service Department"></div><div class="field"><label>Address</label><input name="address1"></div><div class="form-grid"><div class="field"><label>City</label><input name="city"></div><div class="field"><label>State</label><input name="state" value="CA"></div><div class="field"><label>ZIP</label><input name="postal_code"></div><div class="field"><label>Area label</label><input name="area_label" placeholder="Service shop"></div></div><div class="field"><label>Access notes</label><textarea name="access_notes" placeholder="Gate, check-in, bay access…"></textarea></div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Add Location</button></div></form>`);$('#locationForm').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target).entries());await api(`/api/customers/${customerId}/locations`,{method:'POST',body:JSON.stringify(b)});toast('Location added','good');closeDrawer();openCustomer(customerId)}}
function openAddEquipment(customerId,locations){openDrawer('Add Equipment','Give the machine a permanent identity.',`<form id="equipmentForm"><div class="form-grid"><div class="field"><label>Location</label><select name="location_id">${locations.map(l=>`<option value="${l.id}">${esc(l.name)}</option>`).join('')}</select></div><div class="field"><label>Bay / area</label><input name="bay"></div><div class="field"><label>Category</label><select name="category">${['Vehicle Lift','Alignment System','Wheel Balancer','Tire Changer','Brake Lathe','Air Compressor','Fluid Equipment','Shop Exhaust','Cabinet / Storage','ADAS Equipment','Specialty Shop Equipment','Other Automotive Equipment'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Manufacturer</label><input name="manufacturer"></div><div class="field"><label>Model</label><input name="model"></div><div class="field"><label>Serial number</label><input name="serial_number"></div><div class="field"><label>Installed</label><input type="date" name="install_date"></div><div class="field"><label>Warranty until</label><input type="date" name="warranty_until"></div><div class="field"><label>Inspection due</label><input type="date" name="inspection_due_date"></div><div class="field"><label>Inspection interval</label><select name="inspection_interval_months"><option value="">Not set</option><option value="12">12 months</option><option value="6">6 months</option></select></div></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Add Equipment</button></div></form>`);$('#equipmentForm').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target).entries());b.customer_id=customerId;b.command_id=uid();b.inspection_interval_months=b.inspection_interval_months?+b.inspection_interval_months:null;for(const k of ['install_date','warranty_until','inspection_due_date','manufacturer','model','serial_number','bay','notes'])b[k]=b[k]||null;await api('/api/equipment',{method:'POST',body:JSON.stringify(b)});toast('Equipment added','good');closeDrawer();openCustomer(customerId)}}

window.openJob=async id=>{
 const d=await api(`/api/jobs/${id}/detail`),j=d.job,confirmation=(d.confirmations||[])[0];
 const nextButtons=[];
 if(['NEW_REQUEST','TRIAGE'].includes(j.status))nextButtons.push(`<button class="btn primary" onclick="quickJobUpdate('${j.id}',${j.version},'APPROVED_UNSCHEDULED','Schedule approved work')">Approve & Schedule</button>`);
 if(j.status==='APPROVED_UNSCHEDULED')nextButtons.push(`<button class="btn primary" onclick="closeDrawer();openSchedule('${j.id}')">Schedule</button>`);
 if(j.status==='WORK_COMPLETE')nextButtons.push(`<button class="btn primary" onclick="closeDrawer();navigate('reviews')">Review paperwork</button>`);
 if(['READY_TO_INVOICE','INVOICED'].includes(j.status))nextButtons.push(`<button class="btn ${j.status==='READY_TO_INVOICE'?'primary':''}" onclick="openAccountingHandoff('${j.id}')">${j.status==='INVOICED'?'Accounting Record':'Send to Accounting'}</button>`);
 openDrawer(`${j.job_number}`,`${j.customer_name} · ${esc(j.location_name)}`,`
 <div class="record-hero"><div><span class="pill ${tone(j.status)}">${nice(j.status)}</span>${j.priority==='HIGH'?'<span class="pill high">High priority</span>':''}${j.safety_status==='RESTRICTED'?'<span class="pill high">Safety restriction</span>':''}<h2>${esc(j.description)}</h2><p>${esc(j.job_type)} · ${mins(j.estimated_minutes)} · ${j.crew_min} tech${j.crew_min>1?'s':''}</p></div><div class="next-box"><small>Next action</small><strong>${esc(j.next_action||'No next action')}</strong></div></div>
 <div class="drawer-toolbar">${nextButtons.join('')}${j.status==='SCHEDULED'?`<button class="btn small ${confirmation?.status==='CONFIRMED'?'':'primary'}" onclick="openServiceDayConfirmation('${j.id}')">${confirmation?.status==='CONFIRMED'?'✓ Customer Confirmed':'Customer Confirmation'}</button>`:''}<button class="btn small" onclick="window.open('/api/tools/work_order_print/download?job_number=${encodeURIComponent(j.job_number)}','_blank')">Print Work Order</button>${j.equipment_id?`<button class="btn small" onclick="openInspectionCreate('${j.equipment_id}','${j.id}')">＋ Inspection</button>`:''}<button class="btn small" onclick="openJobPart('${j.id}')">＋ Part</button><button class="btn small" onclick="openJobRecommendation('${j.id}')">＋ Recommendation</button><button class="btn small" onclick="openJobForm('${j.id}','${j.customer_id}','${j.equipment_id||''}')">＋ Form</button><button class="btn small" onclick="openFilePicker('job','${j.id}')">＋ File / Photo</button><button class="btn small" onclick="openEstimateCreate('${j.customer_id}','${j.id}')">＋ Estimate</button></div>
 <div class="workspace-grid"><div>
  <div class="context-card"><h3>Scope & equipment</h3><div class="content"><b>${esc(j.description)}</b><br><br>${j.manufacturer?`${esc(j.manufacturer)} ${esc(j.model||j.category)}<br><span class="mono">${esc(j.serial_number||'No serial')}</span> · ${esc(j.bay||'No bay')}`:'No equipment attached'}<br><br>${esc([j.address1,j.city,j.state].filter(Boolean).join(', '))}</div></div>
  <div class="context-card"><h3>Visits</h3><div class="content">${d.visits.map(v=>`<div class="history-item"><strong>${fmtDate(v.start_at)} · ${fmtTime(v.start_at)}</strong><p>${esc(v.technician_name)}${v.helper_name?` + ${esc(v.helper_name)}`:''} · ${nice(v.execution_status)}</p></div>`).join('')||'Not scheduled yet.'}</div></div>
  <div class="context-card"><h3>Required / used parts</h3><div class="content">${d.parts.map(p=>`<div class="history-item"><strong>${esc(p.description)} × ${p.quantity}</strong><p><span class="pill ${tone(p.status)}">${nice(p.status)}</span>${p.vendor?` · ${esc(p.vendor)}`:''}${p.expected_date?` · expected ${fmtDate(p.expected_date)}`:''}</p></div>`).join('')||'No parts attached.'}</div></div>
  <div class="context-card"><h3>Recommendations</h3><div class="content">${d.recommendations.map(r=>`<div class="history-item"><strong>${esc(r.summary)}</strong><p>${esc(r.details||'')}<br><span class="pill ${tone(r.status)}">${nice(r.status)}</span> · ${nice(r.urgency)}</p></div>`).join('')||'No recommendations.'}</div></div>
 </div><div>
  <div class="context-card"><h3>Technician submissions</h3><div class="content">${d.submissions.map(w=>`<div class="history-item"><strong>${esc(w.technician_name)} · ${nice(w.state)}</strong><p><b>Finding:</b> ${esc(w.finding||'—')}<br><b>Correction:</b> ${esc(w.correction||'—')}<br><b>Verified:</b> ${esc(w.verification||'—')}</p>${w.outcome?`<span class="pill ${tone(w.outcome)}">${nice(w.outcome)}</span>`:''}</div>`).join('')||'No field submission yet.'}</div></div>
  ${confirmation?`<div class="context-card"><h3>Customer awareness</h3><div class="content"><div class="history-item"><strong><span class="pill ${tone(confirmation.status)}">${nice(confirmation.status)}</span> · ${fmtDate(confirmation.scheduled_date)}</strong><p>${confirmation.status==='CONFIRMED'?`${esc(confirmation.confirmed_by_name||'Customer contact')} confirmed ${fmtDate(confirmation.confirmed_at)}.`:confirmation.status==='CHANGE_REQUESTED'?'Customer asked to coordinate a different service day.':confirmation.status==='STALE'?'The schedule changed; a new confirmation is required.':'The scheduled service day is waiting for customer acknowledgement.'}</p></div></div></div>`:''}
  ${d.authorizations.length?`<div class="context-card"><h3>Authorizations</h3><div class="content">${d.authorizations.map(a=>`<div class="history-item"><strong>${nice(a.kind)} · ${esc(a.signer_name)}</strong><p>${esc(a.scope_text)}<br>${fmtDate(a.authorized_at)}</p></div>`).join('')}</div></div>`:''}
  <div class="context-card"><h3>Forms & files</h3><div class="content">${d.forms.map(f=>`<div class="history-item"><strong>${esc(f.template_name)}</strong><p>${nice(f.state)} · ${fmtDate(f.completed_at||f.created_at)}</p></div>`).join('')||''}${d.files.map(f=>`<div class="history-item"><a class="link" href="/api/files/${f.id}/download"><strong>${esc(f.original_name)}</strong></a><p>${esc(f.category)} · ${bytes(f.size_bytes)}</p></div>`).join('')||(!d.forms.length?'Nothing attached yet.':'')}</div></div>
  <div class="context-card"><h3>Timeline</h3><div class="content"><div class="timeline">${d.history.slice(0,14).map(e=>`<div class="event"><strong>${esc(e.summary)}</strong><p>${esc(e.actor_name||'System')}</p><time>${fmtDate(e.created_at)} ${fmtTime(e.created_at)}</time></div>`).join('')}</div></div></div>
 </div></div>`);
};
async function openServiceDayConfirmation(jobId){
 const detail=await api(`/api/jobs/${jobId}/detail`),j=detail.job,latest=(detail.confirmations||[])[0];
 if(latest?.status==='CONFIRMED'){
   openDrawer('Customer Confirmed',`${j.job_number} · ${fmtDate(latest.scheduled_date)}`,`<div class="confirmation-hero good"><span class="confirmation-check">✓</span><div><strong>${esc(latest.confirmed_by_name||'Customer contact')}</strong><p>Confirmed the scheduled service day on ${fmtDate(latest.confirmed_at)}.</p></div></div><div class="form-wording">The confirmation applies only to <b>${fmtDate(latest.scheduled_date)}</b>. If the service day changes, ServiceSlate will require a new acknowledgement.</div><div class="form-actions"><button class="btn primary" onclick="closeDrawer()">Done</button></div>`);return;
 }
 let link;
 try{link=await api(`/api/jobs/${jobId}/service-day-link`,{method:'POST',body:JSON.stringify({command_id:uid(),expires_days:7,recipient:j.customer_email||null,channel:'EMAIL'})});}catch(err){return toast(err.message,'bad')}
 const scheduled=link?.scheduled_date||latest?.scheduled_date,confirmationId=link?.confirmation_id||latest?.id;
 let prepared=null;try{prepared=await api(`/api/service-confirmations/${confirmationId}/prepare-message`,{method:'POST',body:JSON.stringify({command_id:uid()})})}catch(err){if(j.customer_email)toast(err.message,'bad')}
 const path=link?.path||'',absolute=path?new URL(path,location.origin).href:'',localOnly=location.hostname==='127.0.0.1'||location.hostname==='localhost';
 const replyCode=prepared?.reply_code||link?.reply_code||latest?.reply_code||'';
 openDrawer('Service Day Confirmation',`${j.customer_name} · ${j.job_number}`,`<div class="service-day-card"><div class="eyebrow">Scheduled service day</div><h2>${fmtDate(scheduled)}</h2><p>Confirm the day without promising an arrival hour.</p></div><div class="form-wording"><strong>Customer wording</strong><p>Your appointment is reserved for the <b>scheduled service day</b> unless a specific arrival time or time window has been confirmed separately. Arrival timing may vary as field service work progresses throughout the day.</p><p>If an unexpected circumstance requires a change to the scheduled date, we’ll contact you promptly with an update and coordinate the next available service day.</p></div>${localOnly?`<div class="notice"><strong>No public server needed</strong><p>The customer can reply <b>CONFIRM</b> to the Outlook email. ServiceSlate recognizes the reference <b>[SSDAY:${esc(replyCode)}]</b> when the service mailbox is checked. The web confirmation link becomes useful remotely once ServiceSlate is hosted.</p></div>`:''}<div class="confirmation-actions">${prepared?.communication_id?`<button class="btn primary" id="sendConfirmEmail">Send Through Outlook</button>`:''}${j.customer_email&&prepared?`<a class="btn" href="mailto:${encodeURIComponent(j.customer_email)}?subject=${encodeURIComponent(prepared.subject)}&body=${encodeURIComponent(prepared.body)}">Open Email App</a>`:''}${!localOnly&&absolute?`<button class="btn" id="copyConfirmLink">Copy Confirmation Link</button>`:''}${j.customer_phone?`<a class="btn" href="sms:${encodeURIComponent(j.customer_phone)}?&body=${encodeURIComponent(`Your service is scheduled for ${fmtDate(scheduled)}. Please reply CONFIRM if the day works. Ref [SSDAY:${replyCode}]`)}">Open SMS App</a>`:''}<button class="btn" id="phoneConfirmed">Confirmed by Phone / In Person</button></div><div class="tiny muted">Read receipts are supporting evidence only. Explicit customer confirmation is the actual acknowledgement.</div>`);
 $('#copyConfirmLink')?.addEventListener('click',async()=>{await navigator.clipboard.writeText(absolute);toast('Confirmation link copied','good')});
 $('#sendConfirmEmail')?.addEventListener('click',async()=>{try{const providers=await api('/api/integrations/catalog'),outlook=providers.find(p=>p.id==='OUTLOOK');if(!outlook||!['CONNECTED','CONFIGURED','AVAILABLE'].includes(outlook.state)){toast('Outlook is not ready on this computer','bad');return}await api(`/api/integrations/communications/${prepared.communication_id}/deliver`,{method:'POST',body:JSON.stringify({provider:'OUTLOOK'})});toast('Confirmation sent through Outlook','good');closeDrawer()}catch(err){toast(err.message,'bad')}});
 $('#phoneConfirmed').onclick=async()=>{const name=await askText({title:'Record customer confirmation',message:'Who confirmed the scheduled service day?',label:'Customer contact name',placeholder:'Name',confirmLabel:'Record Confirmation',required:true});if(!name)return;manualServiceDayConfirm(confirmationId,name)};
}
async function manualServiceDayConfirm(id,name){try{await api(`/api/service-confirmations/${id}/manual-confirm`,{method:'POST',body:JSON.stringify({command_id:uid(),contact_name:name,channel:'PHONE'})});toast('Service day confirmed','good');closeDrawer();}catch(err){toast(err.message,'bad')}}

async function openAccountingHandoff(jobId){
 try{
  const providers=await api('/api/integrations/catalog'),qb=providers.find(p=>p.id==='QUICKBOOKS'),mode=String(qb?.settings?.mode||'EXPORT_ONLY').toUpperCase();
  if(!qb||mode==='EXPORT_ONLY'){
   openDrawer('Accounting Handoff','ServiceSlate keeps the work record even when accounting is not connected.',`<div class="notice"><strong>Export is ready.</strong><p>Connect QuickBooks under Tools & Connections for a human-approved live handoff, or use the QuickBooks-neutral export now.</p></div><div class="form-actions"><button class="btn" onclick="closeDrawer();navigate('tools')">Tools & Connections</button><a class="btn primary" href="/api/tools/quickbooks_billing_export/download">Download Billing Export</a></div>`);return;
  }
  if(mode==='QBO'){
   const ok=await askConfirm({title:'Create QuickBooks Online invoice?',message:'ServiceSlate will use the approved estimate and create one invoice in the connected QuickBooks company. This is a human-approved accounting action.',confirmLabel:'Create Invoice'});if(!ok)return;
   const r=await api(`/api/cloud/quickbooks/qbo/jobs/${jobId}/invoice`,{method:'POST',body:JSON.stringify({command_id:uid()})});toast(r.already_created?'QuickBooks invoice already exists':'QuickBooks invoice created','good');closeDrawer();openJob(jobId);return;
  }
  if(mode==='DESKTOP_WEB_CONNECTOR'){
   const ok=await askConfirm({title:'Queue for QuickBooks Desktop?',message:'ServiceSlate will queue the approved estimate for the authorized QuickBooks Web Connector. Nothing is written to QuickBooks until the connector accepts it.',confirmLabel:'Queue Invoice'});if(!ok)return;
   const r=await api(`/api/cloud/quickbooks/desktop/jobs/${jobId}/queue-invoice`,{method:'POST',body:JSON.stringify({confirm:true})});toast(r.already_created?'QuickBooks invoice already exists':r.already_queued?'Already waiting for QuickBooks':'Queued for QuickBooks Desktop','good');closeDrawer();openJob(jobId);return;
  }
  toast('Choose a QuickBooks connection mode first','bad');
 }catch(err){toast(err.message,'bad')}
}

async function quickJobUpdate(id,version,status,next_action){try{await api(`/api/jobs/${id}`,{method:'PATCH',body:JSON.stringify({version,status,next_action})});toast('Job updated','good');closeDrawer();navigate('dashboard')}catch(e){toast(e.message,'bad')}}

async function openJobPart(jobId){const d=await api('/api/parts');openDrawer('Add Required Part','Parts holds become visible work, not a forgotten note.',`<form id="jobPartForm"><div class="field"><label>Catalog part (optional)</label><select id="partCatalog"><option value="">Not in catalog</option>${d.catalog.map(p=>`<option value="${p.id}" data-name="${esc(p.name)}">${esc(p.name)}${p.sku?` · ${esc(p.sku)}`:''}</option>`).join('')}</select></div><div class="field"><label>Description</label><input id="partDesc" name="description" required></div><div class="form-grid"><div class="field"><label>Quantity</label><input name="quantity" type="number" step=".01" min=".01" value="1"></div><div class="field"><label>Status</label><select name="status">${['NEEDED','REQUESTED','ORDERED','BACKORDERED','RECEIVED','RESERVED','LOADED'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Vendor</label><input name="vendor"></div><div class="field"><label>Expected</label><input name="expected_date" type="date"></div></div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Add Part</button></div></form>`);$('#partCatalog').onchange=e=>{const o=e.target.selectedOptions[0];if(o.dataset.name)$('#partDesc').value=o.dataset.name};$('#jobPartForm').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target).entries());b.command_id=uid();b.part_id=$('#partCatalog').value||null;b.quantity=+b.quantity;b.expected_date=b.expected_date||null;await api(`/api/jobs/${jobId}/parts`,{method:'POST',body:JSON.stringify(b)});toast('Part requirement added','good');closeDrawer();openJob(jobId)}}
function openJobRecommendation(jobId){openDrawer('Add Recommendation','Preserve it even if the customer defers it.',`<form id="recForm"><div class="field"><label>Recommendation</label><input name="summary" required autofocus></div><div class="field"><label>Details / evidence</label><textarea name="details"></textarea></div><div class="form-grid"><div class="field"><label>Urgency</label><select name="urgency">${['MONITOR','RECOMMENDED','SOON','SAFETY_CONCERN'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Follow up</label><input type="date" name="followup_due"></div></div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Save Recommendation</button></div></form>`);$('#recForm').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target).entries());b.command_id=uid();b.followup_due=b.followup_due||null;await api(`/api/jobs/${jobId}/recommendations`,{method:'POST',body:JSON.stringify(b)});toast('Recommendation saved','good');closeDrawer();openJob(jobId)}}

async function renderParts(){const d=await api('/api/parts');setMain(`<div class="page-head"><div><h1>Parts & Holds</h1><p>Know which jobs are waiting and what makes them schedulable again.</p></div><button class="btn" id="newPartCatalog">＋ Catalog Part</button></div><div class="stat-row two"><div class="stat"><div class="stat-label">Open requirements</div><div class="stat-value">${d.job_parts.filter(x=>!['RECEIVED','RESERVED','LOADED','INSTALLED','RETURNED'].includes(x.status)).length}</div><div class="stat-foot">Still preventing readiness</div></div><div class="stat"><div class="stat-label">Parts catalog</div><div class="stat-value">${d.catalog.length}</div><div class="stat-foot">Reusable part identities</div></div></div><section class="panel"><div class="panel-head"><div><h2>Job parts</h2><p>Receiving the final required part automatically makes a blocked job actionable.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Job</th><th>Customer</th><th>Part</th><th>Qty</th><th>Status</th><th>Expected</th><th></th></tr></thead><tbody>${d.job_parts.map(p=>`<tr><td><button class="link" onclick="openJob('${p.job_id}')"><strong>${esc(p.job_number)}</strong></button></td><td>${esc(p.customer_name)}</td><td>${esc(p.description)}<div class="tiny muted">${esc(p.sku||'')}</div></td><td>${p.quantity}</td><td><span class="pill ${tone(p.status)}">${nice(p.status)}</span></td><td>${fmtDate(p.expected_date)}</td><td><button class="btn small" onclick="openPartStatus('${p.id}','${p.status}')">Update</button></td></tr>`).join('')}</tbody></table></div></section>`);$('#newPartCatalog').onclick=openCatalogPart}
function openPartStatus(id,current){openDrawer('Update Part Status','One change should unblock the next action automatically.',`<form id="partStatusForm"><div class="field"><label>Status</label><select name="status">${['NEEDED','REQUESTED','ORDERED','BACKORDERED','RECEIVED','RESERVED','LOADED','INSTALLED','RETURNED'].map(x=>`<option ${x===current?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Expected date</label><input type="date" name="expected_date"></div><div class="field"><label>Note</label><textarea name="notes"></textarea></div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Update</button></div></form>`);$('#partStatusForm').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target).entries());b.command_id=uid();b.expected_date=b.expected_date||null;b.notes=b.notes||null;const r=await api(`/api/job-parts/${id}/status`,{method:'POST',body:JSON.stringify(b)});toast(r.all_ready?'All required parts ready — job returned to scheduling':'Part updated','good');closeDrawer();renderParts()}}
function openCatalogPart(){openDrawer('Add Catalog Part','Reusable identity for commonly ordered or installed parts.',`<form id="catalogPartForm"><div class="field"><label>Name</label><input name="name" required></div><div class="form-grid"><div class="field"><label>SKU</label><input name="sku"></div><div class="field"><label>Manufacturer</label><input name="manufacturer"></div><div class="field"><label>Manufacturer part #</label><input name="manufacturer_part_number"></div><div class="field"><label>Typical cost</label><input name="cost" type="number" step=".01"></div></div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Add Part</button></div></form>`);$('#catalogPartForm').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target).entries());b.default_cost_cents=b.cost?Math.round(+b.cost*100):null;delete b.cost;await api('/api/parts',{method:'POST',body:JSON.stringify(b)});toast('Catalog part added','good');closeDrawer();renderParts()}}

async function renderFollowups(){const [followups,recs]=await Promise.all([api('/api/followups'),state.me.organization_profile==='automotive_equipment'?api('/api/recommendations'):Promise.resolve([])]);const today=new Date().toISOString().slice(0,10);setMain(`<div class="page-head"><div><h1>Follow-ups</h1><p>Promises and recommendations stay visible until someone resolves them.</p></div><button class="btn" onclick="navigate('recurring')">Recurring Work</button></div><div class="content-grid"><section class="panel"><div class="panel-head"><div><h2>Pending follow-ups</h2><p>Callbacks, deferred work, customer contact and other next actions.</p></div></div>${followups.map(f=>`<div class="queue-row"><div class="queue-main"><strong>${esc(f.customer_name||f.kind)}</strong><span>${esc(f.summary)}${f.job_number?` · ${esc(f.job_number)}`:''}</span></div><div class="queue-secondary">${esc(f.owner_name||'Unassigned')}<span>${f.due_at?fmtDate(f.due_at):'No due date'}</span></div><div><span class="pill ${f.due_at&&f.due_at.slice(0,10)<=today?'warn':'blue'}">${nice(f.status)}</span></div><div class="queue-action"><button class="btn small" onclick="snoozeFollowup('${f.id}')">Snooze</button><button class="btn small primary" onclick="followupAction('${f.id}','complete')">Done</button></div></div>`).join('')||'<div class="empty"><strong>Nothing waiting.</strong>No follow-up promises are due.</div>'}</section>${state.me.organization_profile==='automotive_equipment'?`<aside class="panel"><div class="panel-head"><div><h2>Open recommendations</h2><p>Declined or deferred work never disappears.</p></div></div><div class="panel-body">${recs.filter(r=>!['CONVERTED','SUPERSEDED','EXPIRED'].includes(r.status)).slice(0,20).map(r=>`<div class="history-item"><strong>${esc(r.customer_name)} · ${esc(r.summary)}</strong><p>${esc([r.manufacturer,r.model,r.serial_number].filter(Boolean).join(' · '))}<br>${nice(r.urgency)} · ${nice(r.status)}</p><div class="inline-actions"><button class="btn small" onclick="recommendationDecision('${r.id}','DEFERRED')">Defer</button><button class="btn small" onclick="recommendationDecision('${r.id}','DECLINED')">Declined</button><button class="btn small primary" onclick="recommendationDecision('${r.id}','NEEDS_ESTIMATE')">Needs Estimate</button></div></div>`).join('')||'<div class="empty">No open recommendations.</div>'}</div></aside>`:''}</div>`)}
async function followupAction(id,action,new_due_at=null){try{await api(`/api/followups/${id}/action`,{method:'POST',body:JSON.stringify({command_id:uid(),action,new_due_at,outcome:action==='complete'?'Completed':null})});toast(action==='complete'?'Follow-up completed':'Follow-up updated','good');renderFollowups()}catch(err){toast(err.message,'bad')}}
async function snoozeFollowup(id){const d=await askText({title:'Move follow-up',message:'Choose the next date this should come back to the queue.',label:'New due date',type:'date',value:new Date(Date.now()+7*86400000).toISOString().slice(0,10),confirmLabel:'Move Follow-up',required:true});if(d)followupAction(id,'snooze',d)}
async function recommendationDecision(id,status){let followup_due=null,customer_decision=null;if(status==='DEFERRED'){followup_due=await askText({title:'Defer recommendation',message:'When should ServiceSlate bring this back for follow-up?',label:'Follow-up date',type:'date',value:new Date(Date.now()+30*86400000).toISOString().slice(0,10),confirmLabel:'Defer',required:true});if(!followup_due)return;customer_decision='Customer deferred'}if(status==='DECLINED')customer_decision='Customer declined';try{await api(`/api/recommendations/${id}/decision`,{method:'POST',body:JSON.stringify({command_id:uid(),status,customer_decision,followup_due})});toast(`Recommendation: ${nice(status)}`,'good');renderFollowups()}catch(err){toast(err.message,'bad')}}

async function renderRecurring(){const rows=await api('/api/recurring');const today=new Date().toISOString().slice(0,10);setMain(`<div class="page-head"><div><h1>Recurring Work</h1><p>Inspections and maintenance become obligations, not calendar wishes.</p></div><button class="btn primary" id="newRecurring">＋ Recurring Plan</button></div><section class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Customer</th><th>Service</th><th>Equipment</th><th>Next due</th><th>Frequency</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.customer_name)}</strong><div class="tiny muted">${esc(r.location_name||'')}</div></td><td>${esc(r.service_name)}</td><td>${esc([r.manufacturer,r.model,r.serial_number].filter(Boolean).join(' · ')||'Location-wide')}</td><td><span class="pill ${r.next_due_date<=today?'warn':'blue'}">${fmtDate(r.next_due_date)}</span></td><td>${r.frequency_months} months</td><td>${nice(r.status)}</td><td><button class="btn small primary" onclick="recurringAction('${r.id}','create_job')">Create Work</button></td></tr>`).join('')}</tbody></table></div></section>`);$('#newRecurring').onclick=openRecurringCreate}
async function recurringAction(id,action){try{const r=await api(`/api/recurring/${id}/action`,{method:'POST',body:JSON.stringify({command_id:uid(),action})});toast(r.job_number?`${r.job_number} ready for scheduling`:'Recurring plan updated','good');renderRecurring()}catch(e){toast(e.message,'bad')}}
async function openRecurringCreate(){const customers=await api('/api/customers');openDrawer('Create Recurring Plan','ServiceSlate will remember the obligation.',`<form id="recurringForm"><div class="field"><label>Customer</label><select id="recurCustomer" name="customer_id">${customers.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div id="recurRelations"></div><div class="field"><label>Service</label><input name="service_name" required placeholder="Annual Lift Inspection"></div><div class="form-grid"><div class="field"><label>Every</label><select name="frequency_months"><option value="6">6 months</option><option value="12" selected>12 months</option><option value="24">24 months</option></select></div><div class="field"><label>Start reminding</label><select name="lead_days"><option value="30">30 days before</option><option value="45" selected>45 days before</option><option value="60">60 days before</option></select></div><div class="field"><label>Next due</label><input type="date" name="next_due_date" required></div></div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Create Plan</button></div></form>`);const load=async()=>{const d=await api(`/api/customers/${$('#recurCustomer').value}`);$('#recurRelations').innerHTML=`<div class="field"><label>Location</label><select name="location_id"><option value="">Customer-wide</option>${d.locations.map(l=>`<option value="${l.id}">${esc(l.name)}</option>`).join('')}</select></div><div class="field"><label>Equipment</label><select name="equipment_id"><option value="">Location/customer-wide</option>${d.equipment.map(e=>`<option value="${e.id}">${esc(e.manufacturer||'')} ${esc(e.model||e.category)} · ${esc(e.serial_number||'')}</option>`).join('')}</select></div>`};$('#recurCustomer').onchange=load;await load();$('#recurringForm').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target).entries());b.command_id=uid();b.frequency_months=+b.frequency_months;b.lead_days=+b.lead_days;b.location_id=b.location_id||null;b.equipment_id=b.equipment_id||null;await api('/api/recurring',{method:'POST',body:JSON.stringify(b)});toast('Recurring plan created','good');closeDrawer();renderRecurring()}}

async function renderEstimates(){const rows=await api('/api/estimates');setMain(`<div class="page-head"><div><h1>Estimates</h1><p>Exact revisions, exact customer decisions, permanent authorization evidence.</p></div><button class="btn primary" id="newEstimate">＋ New estimate</button></div><section class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Estimate</th><th>Customer</th><th>Job</th><th>Revision</th><th>Total</th><th>Status</th></tr></thead><tbody>${rows.map(e=>`<tr><td><button class="link" onclick="openEstimate('${e.id}')"><strong>${esc(e.estimate_number)}</strong></button></td><td>${esc(e.customer_name)}</td><td>${esc(e.job_number||'—')}</td><td>r${e.revision}</td><td><strong>${money(e.total_cents)}</strong></td><td><span class="pill ${tone(e.status)}">${nice(e.status)}</span></td></tr>`).join('')}</tbody></table></div></section>`);$('#newEstimate').onclick=()=>openEstimateCreate()}
window.openEstimate=async id=>{const d=await api(`/api/estimates/${id}`),e=d.estimate;openDrawer(`${e.estimate_number} · Revision ${e.revision}`,`${e.customer_name}${e.job_number?` · ${e.job_number}`:''}`,`<div class="record-hero"><div><span class="pill ${tone(e.status)}">${nice(e.status)}</span><h2>${money(e.total_cents)}</h2><p>Expires ${fmtDate(e.expires_on)}</p></div></div><div class="context-card"><h3>Scope</h3><div class="content">${d.lines.map(l=>`<div class="estimate-line"><span><b>${esc(l.description)}</b><small>${nice(l.line_type)} · ${l.quantity} × ${money(l.unit_price_cents)}</small></span><strong>${money(l.amount_cents)}</strong></div>`).join('')}</div></div>${e.assumptions?`<div class="context-card"><h3>Assumptions</h3><div class="content">${esc(e.assumptions)}</div></div>`:''}${e.exclusions?`<div class="context-card"><h3>Exclusions</h3><div class="content">${esc(e.exclusions)}</div></div>`:''}${d.authorizations.length?`<div class="context-card"><h3>Approval evidence</h3><div class="content">${d.authorizations.map(a=>`<strong>${esc(a.signer_name)}</strong><br>${esc(a.scope_text)}<br>${fmtDate(a.authorized_at)}`).join('<hr>')}</div></div>`:''}<div class="form-actions"><button class="btn" onclick="reviseEstimate('${e.id}')">Create revision</button>${!['APPROVED','DECLINED','CANCELED','SUPERSEDED'].includes(e.status)?`<button class="btn" onclick="createEstimatePortalLink('${e.id}')">Customer link</button>`:''}${e.status==='DRAFT'?`<button class="btn" onclick="estimateAction('${e.id}','ready')">Ready to send</button>`:''}${['READY_TO_SEND','DRAFT'].includes(e.status)?`<button class="btn" onclick="estimateAction('${e.id}','send')">Mark sent</button>`:''}${!['APPROVED','DECLINED','CANCELED','SUPERSEDED'].includes(e.status)?`<button class="btn primary" onclick="approveEstimate('${e.id}')">Record Approval</button>`:''}</div>`)}
async function estimateAction(id,action,extra={}){try{await api(`/api/estimates/${id}/action`,{method:'POST',body:JSON.stringify({command_id:uid(),action,...extra})});toast('Estimate updated','good');closeDrawer();renderEstimates()}catch(e){toast(e.message,'bad')}}
function approveEstimate(id){openDrawer('Record Estimate Approval','This stores who approved this exact revision.',`<form id="approveEstimateForm"><div class="field"><label>Approver name</label><input name="signer_name" required autofocus></div><div class="field"><label>Title / authority</label><input name="signer_title"></div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Record Approval</button></div></form>`);$('#approveEstimateForm').onsubmit=e=>{e.preventDefault();estimateAction(id,'approve',Object.fromEntries(new FormData(e.target).entries()))}}
async function reviseEstimate(id){const r=await api(`/api/estimates/${id}/revise`,{method:'POST'});toast(`Created revision ${r.revision}`,'good');closeDrawer();openEstimate(r.id)}
async function openEstimateCreate(customerId='',jobId=''){const customers=await api('/api/customers');openDrawer('New estimate','Start simple. Revisions preserve every later material change.',`<form id="estimateForm"><div class="field"><label>Customer</label><select id="estimateCustomer" name="customer_id">${customers.map(c=>`<option value="${c.id}" ${c.id===customerId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Job (optional)</label><select id="estimateJob" name="job_id"><option value="">No job selected</option></select></div><div id="estimateLines"><div class="estimate-edit-line"><select class="lineType"><option>LABOR</option><option>PART</option><option>EQUIPMENT</option><option>FREIGHT</option><option>OTHER</option></select><input class="lineDesc" placeholder="Description" required><input class="lineQty" type="number" value="1" min=".01" step=".01"><input class="linePrice" type="number" min="0" step=".01" placeholder="$ / unit"><button type="button" class="icon-btn" onclick="this.parentElement.remove()">×</button></div></div><button type="button" class="btn small" id="addEstimateLine">＋ Line</button><div class="field"><label>Assumptions</label><textarea name="assumptions"></textarea></div><div class="field"><label>Exclusions</label><textarea name="exclusions"></textarea></div><div class="field"><label>Expires</label><input type="date" name="expires_on"></div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Create Estimate</button></div></form>`);const loadJobs=async()=>{const jobs=await api('/api/jobs');$('#estimateJob').innerHTML='<option value="">No job selected</option>'+jobs.filter(j=>j.customer_id===$('#estimateCustomer').value).map(j=>`<option value="${j.id}" ${j.id===jobId?'selected':''}>${esc(j.job_number)} · ${esc(j.description)}</option>`).join('')};$('#estimateCustomer').onchange=loadJobs;await loadJobs();$('#addEstimateLine').onclick=()=>$('#estimateLines').insertAdjacentHTML('beforeend',`<div class="estimate-edit-line"><select class="lineType"><option>LABOR</option><option>PART</option><option>EQUIPMENT</option><option>FREIGHT</option><option>OTHER</option></select><input class="lineDesc" placeholder="Description" required><input class="lineQty" type="number" value="1" min=".01" step=".01"><input class="linePrice" type="number" min="0" step=".01" placeholder="$ / unit"><button type="button" class="icon-btn" onclick="this.parentElement.remove()">×</button></div>`);$('#estimateForm').onsubmit=async e=>{e.preventDefault();const lines=$$('.estimate-edit-line').map(x=>({line_type:$('.lineType',x).value,description:$('.lineDesc',x).value,quantity:+$('.lineQty',x).value,unit_price_cents:Math.round((+$('.linePrice',x).value||0)*100)})).filter(x=>x.description);if(!lines.length)return toast('Add at least one estimate line','bad');const f=Object.fromEntries(new FormData(e.target).entries());const b={command_id:uid(),customer_id:f.customer_id,job_id:f.job_id||null,lines,assumptions:f.assumptions||null,exclusions:f.exclusions||null,expires_on:f.expires_on||null};const r=await api('/api/estimates',{method:'POST',body:JSON.stringify(b)});toast(`${r.estimate_number} created`,'good');closeDrawer();openEstimate(r.id)}}


async function renderInspections(){
 const [rows,templates]=await Promise.all([api('/api/inspections'),api('/api/inspections/templates')]);
 setMain(`<div class="page-head"><div><h1>Inspections</h1><p>Structured, versioned inspection records tied to permanent equipment history.</p></div><button class="btn primary" id="newInspection">＋ Record Inspection</button></div><div class="stat-row"><div class="stat"><div class="stat-label">Recorded</div><div class="stat-value">${rows.length}</div><div class="stat-foot">Permanent inspection records</div></div><div class="stat"><div class="stat-label">Templates</div><div class="stat-value">${templates.length}</div><div class="stat-foot">Published company procedures</div></div><div class="stat"><div class="stat-label">Deficiencies</div><div class="stat-value">${rows.filter(x=>x.result==='FAIL').length}</div><div class="stat-foot">Inspection results needing attention</div></div></div><section class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Customer / Equipment</th><th>Template</th><th>Inspector</th><th>Result</th></tr></thead><tbody>${rows.map(i=>`<tr><td>${fmtDate(i.inspection_date)}</td><td><button class="link" onclick="openInspection('${i.id}')"><strong>${esc(i.customer_name)}</strong></button><br><span class="muted">${esc([i.manufacturer,i.model,i.serial_number,i.bay].filter(Boolean).join(' · '))}</span></td><td>${esc(i.template_name)} · v${i.template_version}</td><td>${esc(i.inspector_name)}</td><td><span class="pill ${i.result==='PASS'?'good':'high'}">${esc(i.result||'—')}</span></td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">No inspections recorded yet.</div></td></tr>'}</tbody></table></div></section>`);
 $('#newInspection').onclick=()=>openInspectionCreate();
}
window.openInspection=async id=>{const d=await api(`/api/inspections/${id}`),i=d.inspection;openDrawer(`${i.template_name}`,`${i.customer_name} · ${fmtDate(i.inspection_date)}`,`<div class="record-hero"><div><span class="pill ${i.result==='PASS'?'good':'high'}">${esc(i.result)}</span><h2>${esc([i.manufacturer,i.model].filter(Boolean).join(' '))}</h2><p>${esc(i.serial_number||'No serial')} · ${esc(i.bay||'No bay')} · ${esc(i.inspector_name)}</p></div></div><div class="notice">${esc(i.procedure_reference||'Use the organization’s approved procedure and applicable manufacturer references.')}</div><div class="context-card"><h3>Inspection points</h3><div class="content">${d.items.map(x=>`<div class="inspection-result"><span><strong>${esc(x.label)}</strong>${x.comment?`<small>${esc(x.comment)}</small>`:''}${x.measurement_value!=null?`<small>${esc(x.measurement_value)} ${esc(x.measurement_unit||'')}</small>`:''}</span><span class="pill ${x.result==='PASS'?'good':x.result==='FAIL'?'high':'blue'}">${esc(x.result)}</span></div>`).join('')}</div></div>${i.summary?`<div class="context-card"><h3>Summary</h3><div class="content">${esc(i.summary)}</div></div>`:''}${i.customer_ack_name?`<div class="context-card"><h3>Customer acknowledgement</h3><div class="content">${esc(i.customer_ack_name)}</div></div>`:''}${i.next_due_date?`<div class="notice">Next due ${fmtDate(i.next_due_date)}</div>`:''}`)};
window.openInspectionCreate=async (equipmentId=null,jobId=null)=>{
 const [templates,equipment]=await Promise.all([api('/api/inspections/templates'),api('/api/equipment')]);if(!templates.length)return toast('No published inspection template is available','bad');const eligible=equipment.filter(e=>!equipmentId||e.id===equipmentId);if(!eligible.length)return toast('Add or select equipment first','bad');const today=new Date().toISOString().slice(0,10),next=new Date();next.setFullYear(next.getFullYear()+1);const nextDue=next.toISOString().slice(0,10);
 openDrawer('Record Inspection','This record is locked when saved. It references the exact template version used.',`<form id="inspectionForm"><div class="field"><label>Equipment</label><select id="inspectionEquipment" name="equipment_id">${eligible.map(e=>`<option value="${e.id}" ${e.id===equipmentId?'selected':''}>${esc(e.customer_name)} · ${esc(e.manufacturer||'')} ${esc(e.model||e.category)} · ${esc(e.serial_number||'No serial')}</option>`).join('')}</select></div><div class="field"><label>Inspection template</label><select id="inspectionTemplate" name="template_id">${templates.map(t=>`<option value="${t.id}">${esc(t.name)} · v${t.version}</option>`).join('')}</select></div><div id="inspectionProcedure" class="notice"></div><div id="inspectionItems"></div><div class="field"><label>Summary</label><textarea name="summary" placeholder="Overall condition, deficiencies, corrective recommendation…"></textarea></div><div class="form-grid"><div class="field"><label>Inspection date</label><input type="date" name="inspection_date" value="${today}" required></div><div class="field"><label>Next due</label><input type="date" name="next_due_date" value="${nextDue}"></div></div><div class="field"><label>Customer acknowledgement (optional)</label><input name="customer_ack_name" placeholder="Name"></div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Lock Inspection Record</button></div></form>`);
 const draw=()=>{const t=templates.find(x=>x.id===$('#inspectionTemplate').value);$('#inspectionProcedure').textContent=t.procedure_reference||'Use the company-approved procedure.';$('#inspectionItems').innerHTML=t.items.map((x,i)=>`<div class="inspection-entry" data-key="${esc(x.key)}" data-label="${esc(x.label)}"><div class="inspection-entry-head"><strong>${esc(x.label)}</strong><select class="inspection-result-input"><option value="PASS">Pass</option><option value="FAIL">Fail</option><option value="NA">N/A</option></select></div><div class="form-grid"><div class="field"><label>Measurement (optional)</label><input class="inspection-measure" type="number" step="any"></div><div class="field"><label>Unit</label><input class="inspection-unit" value="${esc(x.measurement_unit||'')}"></div></div><div class="field"><label>Comment${''}</label><input class="inspection-comment" placeholder="Required when failed"></div></div>`).join('')};$('#inspectionTemplate').onchange=draw;draw();
 $('#inspectionForm').onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(e.target).entries()),items=$$('.inspection-entry').map(row=>({item_key:row.dataset.key,label:row.dataset.label,result:$('.inspection-result-input',row).value,measurement_value:$('.inspection-measure',row).value===''?null:+$('.inspection-measure',row).value,measurement_unit:$('.inspection-unit',row).value||null,comment:$('.inspection-comment',row).value||null}));try{const r=await api('/api/inspections',{method:'POST',body:JSON.stringify({command_id:uid(),equipment_id:fd.equipment_id,template_id:fd.template_id,job_id:jobId||null,inspection_date:fd.inspection_date,items,summary:fd.summary||null,customer_ack_name:fd.customer_ack_name||null,next_due_date:fd.next_due_date||null})});toast(`Inspection recorded · ${r.result}`,'good');closeDrawer();jobId?openJob(jobId):renderInspections()}catch(err){toast(err.message,'bad')}};
};


window.openTechInspection=(jobId,equipmentId,templates)=>{
 const today=new Date().toISOString().slice(0,10),next=new Date();next.setFullYear(next.getFullYear()+1);const nextDue=next.toISOString().slice(0,10);
 openDrawer('Field Inspection','Saved inspection data can queue on this device if the connection drops.',`<form id="techInspectionForm"><div class="field"><label>Inspection</label><select id="techInspectionTemplate" name="template_id">${templates.map(t=>`<option value="${t.id}">${esc(t.name)} · v${t.version}</option>`).join('')}</select></div><div id="techInspectionProcedure" class="notice"></div><div id="techInspectionItems"></div><div class="field"><label>Summary</label><textarea name="summary" placeholder="Overall condition or corrective recommendation"></textarea></div><div class="form-grid"><div class="field"><label>Date</label><input type="date" name="inspection_date" value="${today}" required></div><div class="field"><label>Next due</label><input type="date" name="next_due_date" value="${nextDue}"></div></div><div class="field"><label>Customer acknowledgement (optional)</label><input name="customer_ack_name"></div><div class="save-state">Fail items require a deficiency comment. The record locks after successful sync.</div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Save Inspection</button></div></form>`);
 const draw=()=>{const t=templates.find(x=>x.id===$('#techInspectionTemplate').value);$('#techInspectionProcedure').textContent=t.procedure_reference||'Use the current company-approved procedure.';$('#techInspectionItems').innerHTML=t.items.map(x=>`<div class="inspection-entry" data-key="${esc(x.key)}" data-label="${esc(x.label)}"><div class="inspection-entry-head"><strong>${esc(x.label)}</strong><select class="inspection-result-input"><option value="PASS">Pass</option><option value="FAIL">Fail</option><option value="NA">N/A</option></select></div><div class="field"><label>Comment</label><input class="inspection-comment" placeholder="Required for failed items"></div><div class="form-grid"><div class="field"><label>Measurement</label><input class="inspection-measure" type="number" step="any"></div><div class="field"><label>Unit</label><input class="inspection-unit" value="${esc(x.measurement_unit||'')}"></div></div></div>`).join('')};$('#techInspectionTemplate').onchange=draw;draw();
 $('#techInspectionForm').onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(e.target).entries()),items=$$('#techInspectionItems .inspection-entry').map(row=>({item_key:row.dataset.key,label:row.dataset.label,result:$('.inspection-result-input',row).value,measurement_value:$('.inspection-measure',row).value===''?null:+$('.inspection-measure',row).value,measurement_unit:$('.inspection-unit',row).value||null,comment:$('.inspection-comment',row).value||null})),body={command_id:uid(),equipment_id:equipmentId,template_id:fd.template_id,job_id:jobId,inspection_date:fd.inspection_date,items,summary:fd.summary||null,customer_ack_name:fd.customer_ack_name||null,next_due_date:fd.next_due_date||null};try{const r=await api('/api/inspections',{method:'POST',body:JSON.stringify(body)});toast(`Inspection delivered · ${r.result}`,'good');closeDrawer();openTechJob(jobId)}catch(err){if(err.isNetworkError||!err.status||err.status>=500){await queueJson('/api/inspections',body);toast('Inspection saved on this device and will sync later','good');closeDrawer();renderTech()}else{toast(err.message,'bad')}}};
};

async function createEstimatePortalLink(id){try{const r=await api(`/api/estimates/${id}/portal-link`,{method:'POST',body:JSON.stringify({expires_days:7})}),url=new URL(r.path,location.origin).href;openDrawer('Customer Approval Link','This secure link is tied to this exact estimate revision.',`<div class="context-card"><h3>Copy this link</h3><div class="content"><code class="path-code" id="portalUrl">${esc(url)}</code><p class="tiny muted" style="margin-top:8px">Expires ${fmtDate(r.expires_at)}. In this local Alpha the recipient can open it only while this ServiceSlate computer is reachable; hosted deployment removes that limitation.</p></div></div><div class="form-actions"><button class="btn" onclick="closeDrawer()">Close</button><button class="btn primary" id="copyPortal">Copy Link</button></div>`);$('#copyPortal').onclick=async()=>{try{await navigator.clipboard.writeText(url);toast('Link copied','good')}catch{toast('Clipboard access is unavailable. Select the link above and copy it manually.','warn')}}}catch(err){toast(err.message,'bad')}}
async function renderPublicPortal(token){
 document.body.classList.add('portal-mode');let d;
 try{d=await api(`/api/public/portal/${encodeURIComponent(token)}`)}catch(err){app.innerHTML=`<div class="portal-page"><div class="portal-card portal-message"><div class="login-brand"><img class="brand-logo" src="/static/brand-icon-192.png" alt=""><div class="wordmark">Service<em>Slate</em></div></div><div class="portal-icon">!</div><h1>This link needs attention</h1><p>${esc(err.message)}</p><div class="tiny muted portal-foot">Contact the service team if you need a current link.</div></div></div>`;return}
 if(d.kind==='service_day'){
   const terminal=['CONFIRMED','CHANGE_REQUESTED'].includes(d.status);
   app.innerHTML=`<div class="portal-page"><main class="portal-card service-confirm-portal"><div class="portal-head"><div class="login-brand"><img class="brand-logo" src="/static/brand-icon-192.png" alt=""><div class="wordmark">Service<em>Slate</em></div></div><span class="pill ${tone(d.status)}">${nice(d.status)}</span></div><div class="eyebrow">${esc(d.organization_name)}</div><h1>Service Day Confirmation</h1><p>For <strong>${esc(d.customer_name)}</strong>${d.location_name?` at ${esc(d.location_name)}`:''}</p><section class="service-date-focus"><span>Scheduled service day</span><strong>${fmtDate(d.scheduled_date)}</strong><small>${esc(d.job_number)} · ${esc(d.description)}</small></section><section class="portal-note service-day-notice"><h3>What to expect</h3><p>Your appointment is reserved for the <strong>scheduled service day</strong> unless a specific arrival time or time window has been confirmed separately. Arrival timing may vary as field service work progresses throughout the day.</p><p>If an unexpected circumstance requires a change to the scheduled date, we’ll contact you promptly with an update and coordinate the next available service day.</p></section>${terminal?`<div class="confirmation-hero ${d.status==='CONFIRMED'?'good':'warn'}"><span class="confirmation-check">${d.status==='CONFIRMED'?'✓':'↻'}</span><div><strong>${d.status==='CONFIRMED'?'Service day confirmed':'Different day requested'}</strong><p>${d.status==='CONFIRMED'?`${esc(d.confirmed_by_name||'Customer contact')} confirmed ${fmtDate(d.scheduled_date)}.`:'The service team will contact you to coordinate another day.'}</p></div></div>`:`<form id="portalDecision"><div class="field"><label>Your name</label><input name="signer_name" required autocomplete="name" placeholder="Name of person confirming"></div><div class="portal-actions"><button type="button" class="btn" id="portalChange">Request a Different Day</button><button class="btn primary">Confirm ${fmtDate(d.scheduled_date)}</button></div></form>`}<div class="tiny muted portal-foot">This confirmation applies only to the scheduled date shown above.</div></main></div>`;
   if(!terminal){const send=async action=>{const name=$('#portalDecision [name=signer_name]').value.trim();if(!name)return toast('Enter your name to continue','bad');let note=null;if(action==='request_change'){note=await askText({title:'Request a different service day',message:'Optional: tell us what day or timing would work better.',label:'Note (optional)',type:'textarea',confirmLabel:'Continue'});if(note===undefined)return;note=note||null}try{await api(`/api/public/portal/${encodeURIComponent(token)}/decision`,{method:'POST',body:JSON.stringify({command_id:uid(),action,signer_name:name,note})});await renderPublicPortal(token)}catch(err){toast(err.message,'bad')}};$('#portalDecision').onsubmit=e=>{e.preventDefault();send('confirm')};$('#portalChange').onclick=()=>send('request_change')}
   return;
 }
 const terminal=['APPROVED','DECLINED','CANCELED','SUPERSEDED'].includes(d.status);
 app.innerHTML=`<div class="portal-page"><main class="portal-card"><div class="portal-head"><div class="login-brand"><img class="brand-logo" src="/static/brand-icon-192.png" alt=""><div class="wordmark">Service<em>Slate</em></div></div><span class="pill ${tone(d.status)}">${nice(d.status)}</span></div><div class="eyebrow">${esc(d.organization_name)}</div><h1>${esc(d.estimate_number)} · Revision ${d.revision}</h1><p>Prepared for <strong>${esc(d.customer_name)}</strong></p><section class="portal-total"><span>Total</span><strong>${money(d.total_cents)}</strong></section><section class="portal-lines">${d.lines.map(l=>`<div><span><b>${esc(l.description)}</b><small>${nice(l.line_type)} · ${l.quantity} × ${money(l.unit_price_cents)}</small></span><strong>${money(l.amount_cents)}</strong></div>`).join('')}</section>${d.assumptions?`<section class="portal-note"><h3>Assumptions</h3><p>${esc(d.assumptions)}</p></section>`:''}${d.exclusions?`<section class="portal-note"><h3>Exclusions</h3><p>${esc(d.exclusions)}</p></section>`:''}${terminal?`<div class="notice ${d.status==='APPROVED'?'good':''}"><strong>Decision recorded: ${nice(d.status)}</strong><br>This exact revision is no longer waiting for a decision.</div>`:`<form id="portalDecision"><div class="field"><label>Your name</label><input name="signer_name" required autocomplete="name"></div><div class="field"><label>Title / role (optional)</label><input name="signer_title"></div><label class="checkline"><input type="checkbox" id="portalConfirm" required> I am authorized to make this decision for ${esc(d.customer_name)}.</label><div class="portal-actions"><button type="button" class="btn" id="portalDecline">Decline</button><button class="btn primary">Approve ${money(d.total_cents)}</button></div></form>`}<div class="tiny muted portal-foot">Secure link · exact estimate revision · expires ${fmtDate(d.link_expires_at)}</div></main></div>`;
 if(!terminal){const send=async action=>{const f=$('#portalDecision'),fd=Object.fromEntries(new FormData(f).entries());if(!fd.signer_name||!$('#portalConfirm').checked)return toast('Enter your name and confirm authority','bad');try{await api(`/api/public/portal/${encodeURIComponent(token)}/decision`,{method:'POST',body:JSON.stringify({command_id:uid(),action,signer_name:fd.signer_name,signer_title:fd.signer_title||null})});await renderPublicPortal(token)}catch(err){toast(err.message,'bad')}};$('#portalDecision').onsubmit=e=>{e.preventDefault();send('approve')};$('#portalDecline').onclick=async()=>{if(await askConfirm({title:'Decline this estimate?',message:'This records a customer decision against this exact estimate revision.',confirmLabel:'Decline Estimate',danger:true}))send('decline')}}
}

async function renderServices(){
 const services=await api('/api/service-catalog'),auto=state.me.organization_profile==='automotive_equipment',canBranch=auto&&['ADMIN','MANAGER'].includes(state.me.role);
 let branches=[];if(canBranch)try{branches=await api('/api/branches')}catch{}
 setMain(`<div class="page-head"><div><h1>Services</h1><p>Reusable defaults make new work faster without locking anyone into them.</p></div><button class="btn primary" id="addService">＋ Add Service</button></div>
 <div class="content-grid"><section class="panel"><div class="panel-head"><div><h2>Service catalog</h2><p>Duration, crew and qualification are smart defaults—the coordinator can still override them.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Service</th><th>Category</th><th>Typical time</th><th>Crew</th><th>Qualification</th><th></th></tr></thead><tbody>${services.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${esc(x.category||'General')}</td><td>${mins(x.default_minutes)}</td><td>${x.default_crew} tech${x.default_crew===1?'':'s'}</td><td>${esc(x.qualification_required||'None')}</td><td><button class="btn small" onclick="openServiceEditor('${x.id}')">Edit</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">No services yet.</div></td></tr>'}</tbody></table></div></section>
 <aside class="suggestion-col">${canBranch?`<section class="panel"><div class="panel-head"><div><h2>Branches</h2><p>Normal workday starting points. Not GPS locations.</p></div><button class="btn small" id="addBranch">＋ Branch</button></div><div class="panel-body">${branches.map(b=>`<div class="compact-item"><div><strong>${esc(b.name)}</strong><span>${esc([b.address1,b.city,b.state,b.postal_code].filter(Boolean).join(', ')||'Address not set')}</span></div><span class="pill good">Active</span></div>`).join('')||'<div class="empty">No branch recorded.</div>'}</div></section>`:''}<section class="panel ${canBranch?'aside-gap':''}"><div class="panel-head"><div><h2>Why defaults?</h2></div></div><div class="panel-body"><div class="notice">Pick a service on a new request and ServiceSlate suggests the routine time, crew and qualification. The person creating the work can change any suggestion.</div></div></section></aside></div>`);
 $('#addService').onclick=()=>openServiceEditor();$('#addBranch')?.addEventListener('click',openBranchCreate);
 state.serviceCatalog=services;
}
function serviceCategories(){return state.me.organization_profile==='grooming'?['Grooming','Bath','Coat Care','Nails','Specialty']:['Service','Repair','Inspection','Installation','Maintenance','Training','Site Survey','Warranty'];}
function openServiceEditor(id=null){const existing=(state.serviceCatalog||[]).find(x=>x.id===id),cats=serviceCategories();openDrawer(existing?'Edit Service':'Add Service',existing?'Change the defaults used when new work is created.':'Create a reusable service with safe scheduling defaults.',`<form id="serviceEditor"><div class="field"><label>Service name</label><input name="name" value="${esc(existing?.name||'')}" required autofocus></div><div class="form-grid"><div class="field"><label>Category</label><select name="category">${cats.map(c=>`<option ${existing?.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="field"><label>Typical time</label><input name="default_minutes" type="number" min="15" step="15" value="${existing?.default_minutes||60}" required></div><div class="field"><label>Typical crew</label><input name="default_crew" type="number" min="1" max="8" value="${existing?.default_crew||1}" required></div>${state.me.organization_profile==='automotive_equipment'?`<div class="field"><label>Qualification</label><input name="qualification_required" value="${esc(existing?.qualification_required||'')}" placeholder="None required"></div>`:''}</div><div class="form-actions">${existing?'<button type="button" class="btn danger" id="retireService">Retire Service</button>':''}<button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">${existing?'Save Changes':'Add Service'}</button></div></form>`);$('#serviceEditor').onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(e.target).entries()),body={name:fd.name,category:fd.category,default_minutes:+fd.default_minutes,default_crew:+fd.default_crew,qualification_required:fd.qualification_required||null};try{await api(existing?`/api/service-catalog/${id}`:'/api/service-catalog',{method:existing?'PATCH':'POST',body:JSON.stringify(body)});toast(existing?'Service updated':'Service added','good');closeDrawer();renderServices()}catch(err){toast(err.message,'bad')}};if(existing)$('#retireService').onclick=async()=>{if(!(await askConfirm({title:`Retire ${existing.name}?`,message:'Existing jobs and history stay unchanged. The service will stop appearing for new work.',confirmLabel:'Retire Service',danger:true})))return;try{await api(`/api/service-catalog/${id}`,{method:'PATCH',body:JSON.stringify({active:false})});toast('Service retired','good');closeDrawer();renderServices()}catch(err){toast(err.message,'bad')}}}
function openBranchCreate(){openDrawer('Add Branch','A normal workday start location—not a tracking point.',`<form id="branchCreate"><div class="field"><label>Branch name</label><input name="name" required autofocus placeholder="Fresno"></div><div class="field"><label>Address</label><input name="address1"></div><div class="form-grid"><div class="field"><label>City</label><input name="city"></div><div class="field"><label>State</label><input name="state" value="CA"></div><div class="field"><label>ZIP</label><input name="postal_code"></div></div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Add Branch</button></div></form>`);$('#branchCreate').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target).entries());try{await api('/api/branches',{method:'POST',body:JSON.stringify(b)});toast('Branch added','good');closeDrawer();renderServices()}catch(err){toast(err.message,'bad')}}}

async function renderForms(){const [templates,completions]=await Promise.all([api('/api/forms/templates'),api('/api/forms/completions')]);const canBuild=['ADMIN','MANAGER','COORDINATOR','RECEPTION'].includes(state.me.role);setMain(`<div class="page-head"><div><h1>Forms & Evidence</h1><p>Published wording is versioned; completed evidence does not silently change.</p></div>${canBuild?'<button class="btn primary" id="newFormTemplate">＋ New Form</button>':''}</div><div class="content-grid"><section class="panel"><div class="panel-head"><div><h2>Published templates</h2><p>Only the active business profile appears.</p></div></div>${templates.map(t=>`<div class="queue-row three"><div class="queue-main"><strong>${esc(t.name)}</strong><span>${esc(t.wording||'')}</span></div><div><span class="pill blue">${nice(t.category)}</span></div><div class="queue-action"><span class="tiny muted">Version ${t.version} · ${t.schema.length} field${t.schema.length===1?'':'s'}</span></div></div>`).join('')||'<div class="empty">No forms published yet.</div>'}</section><aside class="panel"><div class="panel-head"><div><h2>Recent completions</h2></div></div><div class="panel-body">${completions.slice(0,8).map(f=>`<div class="history-item"><strong>${esc(f.template_name)}</strong><p>${nice(f.state)} · ${fmtDate(f.completed_at||f.created_at)}</p></div>`).join('')||'<div class="empty">No completed forms yet.</div>'}</div></aside></div>`);if(canBuild)$('#newFormTemplate').onclick=openFormTemplateCreate}

function openFormTemplateCreate(){
 openDrawer('Create Form','Keep it short. Ask only what the business actually needs.',`<form id="templateCreate"><div class="form-grid"><div class="field"><label>Form name</label><input name="name" required autofocus placeholder="Service Completion Acknowledgement"></div><div class="field"><label>Category</label><select name="category"><option>Service</option><option>Authorization</option><option>Inspection</option><option>Intake</option><option>Safety</option><option>Photo Release</option><option>Custom</option></select></div></div><div class="field"><label>What the person should read first</label><textarea name="wording" placeholder="Plain-language wording shown above the questions."></textarea></div><div class="panel inset"><div class="panel-head"><div><h3>Questions</h3><p>Use only the fields this form truly needs.</p></div><button type="button" class="btn small" id="addFormQuestion">＋ Add Question</button></div><div id="formQuestionRows" class="panel-body"></div></div><div class="notice">Publishing locks version 1. Completed forms always remember the exact version used.</div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Publish Form</button></div></form>`);
 let rows=[];
 const draw=()=>{$('#formQuestionRows').innerHTML=rows.map((r,i)=>`<div class="builder-row" data-i="${i}"><div class="field grow"><label>Question</label><input data-k="label" value="${esc(r.label)}" placeholder="What should we ask?"></div><div class="field"><label>Answer type</label><select data-k="type"><option value="text" ${r.type==='text'?'selected':''}>Short text</option><option value="long_text" ${r.type==='long_text'?'selected':''}>Long text</option><option value="number" ${r.type==='number'?'selected':''}>Number</option><option value="date" ${r.type==='date'?'selected':''}>Date</option><option value="choice" ${r.type==='choice'?'selected':''}>Choice</option><option value="checkbox" ${r.type==='checkbox'?'selected':''}>Checkbox</option></select></div><div class="field choice-options ${r.type==='choice'?'':'hide'}"><label>Choices</label><input data-k="options" value="${esc(r.options||'')}" placeholder="Pass, Fail, N/A"></div><label class="checkline compact"><input data-k="required" type="checkbox" ${r.required?'checked':''}> Required</label><button type="button" class="icon-btn danger" data-remove="${i}" aria-label="Remove question">×</button></div>`).join('')||'<div class="empty">No questions yet. Add only what must be captured.</div>';$$('#formQuestionRows [data-k]').forEach(el=>{el.onchange=el.oninput=()=>{const row=el.closest('.builder-row'),i=+row.dataset.i,k=el.dataset.k;rows[i][k]=el.type==='checkbox'?el.checked:el.value;if(k==='type')draw()}});$$('#formQuestionRows [data-remove]').forEach(b=>b.onclick=()=>{rows.splice(+b.dataset.remove,1);draw()})};
 $('#addFormQuestion').onclick=()=>{rows.push({label:'',type:'text',options:'',required:false});draw()};draw();
 $('#templateCreate').onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(e.target).entries());const fields=rows.filter(r=>r.label.trim()).map((r,i)=>({key:r.label.trim().toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'')||`field_${i+1}`,label:r.label.trim(),type:r.type,required:!!r.required,options:r.type==='choice'?(r.options||'').split(',').map(x=>x.trim()).filter(Boolean):[]}));try{await api('/api/forms/templates',{method:'POST',body:JSON.stringify({command_id:uid(),name:fd.name,category:fd.category,wording:fd.wording||null,fields})});toast('Form published','good');closeDrawer();renderForms()}catch(err){toast(err.message,'bad')}};
}
async function openJobForm(jobId,customerId,equipmentId){const templates=await api('/api/forms/templates');openDrawer('Complete Form','Choose the exact published form.',`<form id="jobFormCompletion"><div class="field"><label>Form</label><select id="formTemplate">${templates.map(t=>`<option value="${t.id}">${esc(t.name)} · v${t.version}</option>`).join('')}</select></div><div id="dynamicFormFields"></div><div class="field"><label>Completed / signed by</label><input name="completed_by_name"></div><div class="field"><label>Signature text (if required)</label><input name="signature_text"></div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Complete Form</button></div></form>`);const draw=()=>{const t=templates.find(x=>x.id===$('#formTemplate').value);$('#dynamicFormFields').innerHTML=`<div class="form-wording">${esc(t.wording||'')}</div>`+t.schema.map(f=>formFieldHtml(f)).join('')};$('#formTemplate').onchange=draw;draw();$('#jobFormCompletion').onsubmit=async e=>{e.preventDefault();const values={};$$('[data-form-key]').forEach(x=>values[x.dataset.formKey]=x.type==='checkbox'?x.checked:x.value);const fd=Object.fromEntries(new FormData(e.target).entries());await api('/api/forms/completions',{method:'POST',body:JSON.stringify({command_id:uid(),template_id:$('#formTemplate').value,customer_id:customerId,job_id:jobId,equipment_id:equipmentId||null,completed_by_name:fd.completed_by_name||null,signature_text:fd.signature_text||null,values,submit:true})});toast('Form completed and version locked','good');closeDrawer();openJob(jobId)}}

