async function renderTools(){
 const [tools,providers]=await Promise.all([api('/api/tools'),api('/api/integrations/catalog')]); state.tools=tools;state.providers=providers; const cats=[...new Set(tools.map(t=>t.category))];
 const connected=providers.filter(p=>['CONNECTED','CONFIGURED','AVAILABLE'].includes(p.state)).length;
 const outlook=providers.find(p=>p.id==='OUTLOOK'),mobile=providers.find(p=>p.id==='MOBILE_SMS'),drive=providers.find(p=>p.id==='GOOGLE_DRIVE'),graph=providers.find(p=>p.id==='MICROSOFT_GRAPH');
 const advanced=providers.filter(p=>!['OUTLOOK','MOBILE_SMS','GOOGLE_DRIVE','MICROSOFT_GRAPH'].includes(p.id));
 const simpleConnection=(p,title,description,buttonLabel='Set Up')=>p?`<article class="integration-card simple-connection"><div class="tool-card-top"><span class="pill blue">Recommended</span><span class="pill ${tone(p.state)}">${p.state==='NOT_CONNECTED'?'Not set up':nice(p.state)}</span></div><h3>${esc(title)}</h3><p>${esc(description)}</p><button class="btn small block" data-integration="${p.id}">${p.configured?'Manage':buttonLabel}</button>${p.id==='OUTLOOK'?'<button class="btn small block secondary-action" data-outlook-scan>Check for New Mail</button>':''}</article>`:'';
 setMain(`<div class="page-head"><div><div class="eyebrow">Useful tools without extra subscriptions</div><h1>Tools & Connections</h1><p>ServiceSlate uses the computer, phone and Outlook you already have. Extra services are optional.</p></div><div class="page-actions"><span class="pill good">${tools.length} tools ready</span><span class="pill blue">${connected} connections available</span></div></div>
 <section class="panel tool-section"><div class="panel-head"><div><h2>Everyday connections</h2><p>These are the normal choices. You should not need the advanced section for routine use.</p></div></div><div class="integration-grid">${simpleConnection(outlook,'Outlook Email','Send customer email and review FastField reports or customer confirmation replies using Outlook.','Use Outlook')}${simpleConnection(mobile,'Text Messages','Prepare a text and send it through the paired phone and its existing mobile plan.','Use My Phone')}${simpleConnection(drive,'Google Drive','Use the company’s existing Google Drive for documents and off-site backups. ServiceSlate keeps structured data in its database.','Connect Drive')}${simpleConnection(graph,'New Outlook / Microsoft 365','Use supported Microsoft 365 mail and calendar synchronization when the company authorizes it.','Connect Microsoft 365')}<article class="integration-card simple-connection"><div class="tool-card-top"><span class="pill good">Built in</span><span class="pill good">Ready</span></div><h3>FastField Intake</h3><p>FastField reports arriving in Outlook are extracted and staged for human review. Nothing important is trusted automatically.</p><button class="btn small block" data-outlook-scan>Check for Reports</button></article></div></section>
 <section class="panel tool-section"><div class="panel-head"><div><h2>Built-in tools</h2><p>Calculators, documents and device handoffs that work without another subscription.</p></div></div><div class="panel-body"><div class="tool-category-tabs"><button class="btn small active" data-toolcat="all">All</button>${cats.map(c=>`<button class="btn small" data-toolcat="${esc(c)}">${esc(c)}</button>`).join('')}</div><div class="tool-grid" id="toolGrid">${tools.map(t=>toolCard(t)).join('')}</div></div></section>
 <details class="panel tool-section advanced-connections"><summary><span><strong>Advanced connections</strong><small>Optional open-source, self-hosted and paid services</small></span><span>Show</span></summary><div class="panel-body"><div class="notice"><strong>You normally do not need these.</strong><p>They are here for companies that later want their own hosted messaging, storage, calendar, maps, OCR, or paid delivery provider.</p></div><div class="integration-grid">${advanced.map(integrationCard).join('')}</div></div></details>`);
 $$('[data-toolcat]').forEach(b=>b.onclick=()=>{ $$('[data-toolcat]').forEach(x=>x.classList.remove('active'));b.classList.add('active');const cat=b.dataset.toolcat;$$('.tool-card').forEach(c=>c.classList.toggle('hide',cat!=='all'&&c.dataset.category!==cat));});
 $$('[data-tool]').forEach(b=>b.onclick=()=>openTool(b.dataset.tool));
 $$('[data-integration]').forEach(b=>b.onclick=()=>openIntegration(b.dataset.integration)); $$('[data-outlook-scan]').forEach(b=>b.onclick=checkOutlookNow);
}

function integrationCard(p){const badge=p.open_source?'Open / self-hostable':p.mode==='paid_adapter'?'Paid optional':p.mode==='handoff'?'Uses existing device':'Optional';const stateLabel=p.state==='NOT_CONNECTED'?'Not connected':nice(p.state);return `<article class="integration-card"><div class="tool-card-top"><span class="pill ${p.open_source?'good':p.mode==='paid_adapter'?'warn':'blue'}">${badge}</span><span class="pill ${tone(p.state)}">${esc(stateLabel)}</span></div><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><div class="integration-meta"><span>${esc(p.category)}</span><span>${esc(p.license)}</span></div><button class="btn small block" data-integration="${p.id}">${p.mode==='handoff'?'Open Options':p.configured?'Manage':'Connect'}</button>${p.id==='OUTLOOK'?'<button class="btn small block secondary-action" data-outlook-scan>Check for New Mail</button>':''}</article>`}
function integrationFieldLabel(k){return ({base_url:'Server URL',collection_url:'Collection URL',host:'Mail server',port:'Port',username:'Username',from_email:'From email',from_name:'From name',security:'Security',topic:'Topic',url:'URL',folder:'Folder',endpoint_url:'S3 endpoint',bucket:'Bucket',region:'Region',access_key_id:'Access key ID',prefix:'Folder / prefix',account_email:'Account email',tenant_id:'Microsoft tenant',client_id:'Application ID',from_number:'From number',tag:'Apprise tag',user_agent:'Application contact / User-Agent',allow_public_osm:'Allow public OSM endpoint',executable:'Executable',language:'OCR language',mode:'Connection mode',mailbox:'Mailbox (optional)',mail_folder:'Folder to check',calendar_id:'Calendar',fastfield_folder:'Folder to check',fastfield_sender_filter:'FastField sender contains',fastfield_subject_filter:'FastField subject contains',request_read_receipt:'Request read receipt',auto_check:'Check Outlook while ServiceSlate is open',local_folder:'Google Drive folder on this computer',file_subfolder:'Documents folder',backup_subfolder:'Backup folder',shared_drive_id:'Shared Drive ID',root_folder_id:'Drive documents folder ID',backup_folder_id:'Drive backup folder ID',redirect_base_url:'Public ServiceSlate address',sync_files:'Copy ServiceSlate files to this storage',sync_backups:'Copy backups off-site',sync_mail:'Check mailbox',sync_calendar:'Synchronize calendar',environment:'Environment',realm_id:'QuickBooks company ID',web_connector_url:'Hosted Web Connector address',web_connector_username:'Web Connector username',desktop_service_item_name:'QuickBooks Desktop service item name',service_item_id:'QuickBooks service item ID'})[k]||nice(k)}
function integrationInput(k,v='',provider=''){
 const boolKeys=['request_read_receipt','auto_check','allow_public_osm','sync_files','sync_backups','sync_mail','sync_calendar','mirror_files','mirror_backups'];
 if(boolKeys.includes(k))return `<select name="${k}"><option value="true" ${v===true||v==='true'?'selected':''}>Yes</option><option value="false" ${v===false||v==='false'||v===''?'selected':''}>No</option></select>`;
 if(k==='mode'){
   if(provider==='OUTLOOK')return `<select name="${k}"><option value="AUTO" ${!v||v==='AUTO'?'selected':''}>Use Outlook on this computer</option><option value="CLASSIC_LOCAL" ${v==='CLASSIC_LOCAL'?'selected':''}>Classic Outlook on this computer</option></select>`;
   if(provider==='GOOGLE_DRIVE')return `<select name="${k}"><option value="LOCAL_FOLDER" ${!v||v==='LOCAL_FOLDER'?'selected':''}>Use Google Drive folder on this computer</option><option value="API" ${v==='API'?'selected':''}>Connect company Shared Drive directly</option></select>`;
   if(provider==='QUICKBOOKS')return `<select name="${k}"><option value="EXPORT_ONLY" ${!v||v==='EXPORT_ONLY'?'selected':''}>Export only</option><option value="QBO" ${v==='QBO'?'selected':''}>QuickBooks Online</option><option value="DESKTOP_WEB_CONNECTOR" ${v==='DESKTOP_WEB_CONNECTOR'?'selected':''}>QuickBooks Desktop Web Connector</option></select>`;
 }
 if(k==='environment')return `<select name="${k}"><option value="production" ${v!=='sandbox'?'selected':''}>Production</option><option value="sandbox" ${v==='sandbox'?'selected':''}>Sandbox</option></select>`;
 if(k==='security')return `<select name="${k}"><option ${v==='STARTTLS'?'selected':''}>STARTTLS</option><option ${v==='SSL'?'selected':''}>SSL</option><option ${v==='NONE'?'selected':''}>NONE</option></select>`;
 return `<input name="${k}" value="${esc(v)}" ${k==='port'?'type="number"':''}>`;
}
async function startMailboxWatch(){
 if(!state.me||!['ADMIN','MANAGER','COORDINATOR','RECEPTION'].includes(state.me.role))return;
 if(state.mailboxTimer){clearInterval(state.mailboxTimer);state.mailboxTimer=null}
 try{
   const providers=await api('/api/integrations/catalog'),p=providers.find(x=>x.id==='OUTLOOK');
   if(!p?.configured||p.settings?.auto_check===false)return;
   const quiet=async()=>{try{const r=await api('/api/integrations/outlook/scan',{method:'POST'});if((r.fastfield||0)>0||(r.confirmations||0)>0){toast(`${r.fastfield||0} FastField report${r.fastfield===1?'':'s'} · ${r.confirmations||0} customer repl${r.confirmations===1?'y':'ies'}`,'good');if(state.view==='dashboard')renderDashboard()}}catch{/* Outlook may be closed/unavailable; manual Check explains the issue. */}};
   setTimeout(quiet,8000); state.mailboxTimer=setInterval(quiet,5*60*1000);
 }catch{}
}
async function checkOutlookNow(){try{toast('Checking Outlook…');const r=await api('/api/integrations/outlook/scan',{method:'POST'});const batches=(r.results||[]).filter(x=>x.batch_id);const confirmed=(r.results||[]).filter(x=>x.type==='SERVICE_DAY_REPLY'&&x.state==='CONFIRMED').length;toast(`${r.fastfield||0} FastField report${r.fastfield===1?'':'s'} · ${confirmed} confirmation${confirmed===1?'':'s'}`,'good');if(batches.length)openImportReview(batches[0].batch_id);else renderTools()}catch(err){openDrawer('Outlook needs attention','ServiceSlate could not check Outlook on this computer.',`<div class="notice"><strong>${esc(err.message)}</strong><p>If you use the new Outlook, automatic local mailbox access is not available through the old Windows Outlook interface. You can still use the email app normally, or connect the supported Microsoft 365 mailbox method when your company is ready.</p></div><div class="form-actions"><button class="btn primary" onclick="closeDrawer()">Got it</button></div>`)}}
function openIntegration(id){
 const p=(state.providers||[]).find(x=>x.id===id);if(!p)return;
 if(p.mode==='handoff'){
   openDrawer(p.name,p.description,`<div class="notice"><strong>No account or API required.</strong><p>ServiceSlate prepares the number/message; you approve and send it through the phone/carrier. This remains a handoff, so ServiceSlate will not claim delivery.</p></div>${(p.links||[]).map(l=>`<a class="btn block integration-link" href="${esc(l.url)}" target="_blank" rel="noopener">${esc(l.label)} ↗</a>`).join('')}<div class="tiny muted" style="margin-top:12px">On Windows, Phone Link can send SMS/MMS through a paired phone. Google Messages for web and KDE Connect are additional options.</div>`);return;
 }
 const canEdit=['ADMIN','MANAGER'].includes(state.me.role),secretSet=new Set(p.secret_fields_set||[]);
 const outlookExtra=id==='OUTLOOK'?`<section class="panel inset integration-helper"><div class="panel-head"><div><h3>FastField & customer replies</h3><p>Use the Outlook profile already signed in on this Windows computer.</p></div></div><div class="panel-body"><button type="button" class="btn block" id="outlookCheckInside">Check Outlook Now</button><div class="field compact-upload"><label>Fallback: import a saved Outlook email (.eml)</label><input id="outlookEml" type="file" accept=".eml,message/rfc822"></div><div class="tiny muted">New Outlook / hosted Microsoft 365 uses the separate Microsoft 365 connection.</div></div></section>`:'';
 const providerExtra=id==='GOOGLE_DRIVE'?`<section class="panel inset integration-helper"><div class="panel-body"><strong>Company Drive</strong><p>Easy mode uses the Google Drive folder already synced on this computer. Direct mode connects a Shared Drive after your administrator approves it.</p><div class="form-actions"><button type="button" class="btn" id="driveConnect">Connect Google Account</button><button type="button" class="btn" id="driveBackup">Back Up to Drive Now</button></div></div></section>`:id==='MICROSOFT_GRAPH'?`<section class="panel inset integration-helper"><div class="panel-body"><strong>Microsoft 365 sign-in</strong><p>Used for New Outlook mailbox intake and two-way calendar review. ServiceSlate never silently accepts an Outlook schedule edit.</p><div class="form-actions"><button type="button" class="btn" id="msStart">Start Microsoft Sign-in</button><button type="button" class="btn" id="msFinish">Finish Sign-in</button><button type="button" class="btn" id="msMail">Check Mail</button><button type="button" class="btn" id="msCalendar">Sync Calendar</button></div><div id="msDeviceCode" class="tiny muted"></div></div></section>`:id==='QUICKBOOKS'?`<section class="panel inset integration-helper"><div class="panel-body"><strong>Accounting activation</strong><p>Export-only always works. QuickBooks Online can connect here. Desktop Web Connector still requires permission from whoever administers the hosted QuickBooks environment.</p><div class="form-actions"><button type="button" class="btn" id="qboConnect">Connect QuickBooks Online</button><a class="btn" href="/api/cloud/quickbooks/desktop/qwc">Download Desktop Connector File</a></div></div></section>`:'';
 openDrawer(p.name,p.description,`<div class="integration-provider-head"><span class="pill ${p.open_source?'good':p.mode==='paid_adapter'?'warn':'blue'}">${p.open_source?'Open / self-hostable':p.mode==='paid_adapter'?'Paid optional':'Optional'}</span><span class="pill ${tone(p.state)}">${nice(p.state)}</span></div><form id="integrationForm">${(p.fields||[]).map(k=>`<div class="field"><label>${integrationFieldLabel(k)}</label>${integrationInput(k,p.settings?.[k]??'',p.id)}</div>`).join('')}${(p.secret_fields||[]).map(k=>`<div class="field"><label>${nice(k)}</label><input name="secret_${k}" type="password" placeholder="${secretSet.has(k)?'Saved — leave blank to keep it':'Enter secret'}"></div>`).join('')}<div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Close</button>${canEdit?`<button type="button" class="btn" id="testIntegration">Test</button><button class="btn primary">Save Connection</button>`:'<span class="tiny muted">Manager/admin can change connections.</span>'}</div></form>${outlookExtra}${providerExtra}<div id="integrationTestResult" class="tiny muted"></div>`);
 $('#outlookCheckInside')?.addEventListener('click',checkOutlookNow);
 $('#outlookEml')?.addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;const form=new FormData();form.append('file',f);try{const r=await rawFetch('/api/integrations/outlook/import-eml',{method:'POST',body:form});if(r.batch_id){toast('Email staged for human review','good');closeDrawer();openImportReview(r.batch_id)}else{toast(r.state==='CONFIRMED'?'Customer confirmation recorded':'Email reviewed','good');closeDrawer()}}catch(err){toast(err.message,'bad')}});
 $('#driveConnect')?.addEventListener('click',async()=>{try{const r=await api('/api/cloud/google-drive/authorize-url');window.open(r.url,'_blank','noopener');toast('Google authorization opened','good')}catch(err){toast(err.message,'bad')}});
 $('#driveBackup')?.addEventListener('click',async()=>{try{const r=await api('/api/cloud/google-drive/backup-now',{method:'POST'});toast(`Backed up ${r.backup} to Google Drive`,'good')}catch(err){toast(err.message,'bad')}});
 $('#msStart')?.addEventListener('click',async()=>{try{const r=await api('/api/cloud/microsoft/start',{method:'POST'});$('#msDeviceCode').innerHTML=`Open <a href="${esc(r.verification_uri)}" target="_blank" rel="noopener">Microsoft sign-in</a> and enter <strong>${esc(r.user_code)}</strong>, then choose Finish Sign-in.`;window.open(r.verification_uri,'_blank','noopener')}catch(err){toast(err.message,'bad')}});
 $('#msFinish')?.addEventListener('click',async()=>{try{const r=await api('/api/cloud/microsoft/finish',{method:'POST'});toast(`Microsoft 365 connected${r.account?` · ${r.account}`:''}`,'good');closeDrawer();renderTools()}catch(err){toast(err.message,'bad')}});
 $('#msMail')?.addEventListener('click',async()=>{try{const r=await api('/api/cloud/microsoft/mail/scan',{method:'POST'});toast(`${r.processed} new mailbox item${r.processed===1?'':'s'} reviewed`,'good')}catch(err){toast(err.message,'bad')}});
 $('#msCalendar')?.addEventListener('click',async()=>{try{const r=await api('/api/cloud/microsoft/calendar/sync',{method:'POST'});toast(`${r.pushed||0} ServiceSlate visit${r.pushed===1?'':'s'} synchronized · ${r.conflicts||0} need review`,'good')}catch(err){toast(err.message,'bad')}});
 $('#qboConnect')?.addEventListener('click',async()=>{try{const r=await api('/api/cloud/quickbooks/qbo/authorize-url');window.open(r.url,'_blank','noopener');toast('QuickBooks authorization opened','good')}catch(err){toast(err.message,'bad')}});
 if(!canEdit)return;const form=$('#integrationForm');
 form.onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(form).entries()),settings={},secrets={};for(const k of (p.fields||[])){let v=fd[k]??'';if(['allow_public_osm','request_read_receipt','auto_check','sync_files','sync_backups','sync_mail','sync_calendar','mirror_files','mirror_backups'].includes(k))v=v==='true';settings[k]=v}for(const k of (p.secret_fields||[]))if(fd[`secret_${k}`])secrets[k]=fd[`secret_${k}`];try{await api(`/api/integrations/${id}`,{method:'PUT',body:JSON.stringify({enabled:true,settings,secrets})});toast('Connection saved','good');closeDrawer();renderTools()}catch(err){toast(err.message,'bad')}};
 $('#testIntegration').onclick=async()=>{let target=null;if(['SMTP','TWILIO_SMS','O365_OUTBOUND'].includes(id))target=await askText({title:'Test connection',message:'Where should ServiceSlate send the test?',label:id==='TWILIO_SMS'?'Phone number':'Email address',type:id==='TWILIO_SMS'?'tel':'email',confirmLabel:'Send Test',required:true});if(['SMTP','TWILIO_SMS','O365_OUTBOUND'].includes(id)&&!target)return;try{$('#integrationTestResult').textContent='Testing…';const r=await api(`/api/integrations/${id}/test`,{method:'POST',body:JSON.stringify({target})});$('#integrationTestResult').innerHTML=`<span class="health-ok">✓ Connection worked</span> · ${esc(r.reference||'accepted')}`;toast('Connection worked','good')}catch(err){$('#integrationTestResult').textContent=err.message;toast(err.message,'bad')}};
}
function toolCard(t){return `<article class="tool-card" data-category="${esc(t.category)}"><div class="tool-card-top"><span class="tool-glyph">${toolGlyph(t.category)}</span><span class="pill good">Ready</span></div><h3>${esc(t.name)}</h3><p>${esc(t.description)}</p><div class="tool-foot"><span>${esc(t.category)}</span><button class="btn small" data-tool="${t.id}">Open</button></div></article>`}
function toolGlyph(c){return c==='Field Math'?'∑':c==='Office Math'?'$':c==='Planning'?'◷':c==='Handoffs'?'↗':c==='Documents'?'▤':'⇄'}
function fieldForTool(f){let def=f.default==='today'?new Date().toISOString().slice(0,10):(f.default??'');if(f.type==='select')return `<div class="field"><label>${esc(f.label)}</label><select name="${esc(f.key)}">${(f.options||[]).map(o=>`<option value="${esc(o)}" ${String(o)===String(def)?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`;if(f.type==='textarea')return `<div class="field"><label>${esc(f.label)}</label><textarea name="${esc(f.key)}" ${f.required===false?'':'required'}>${esc(def)}</textarea></div>`;return `<div class="field"><label>${esc(f.label)}</label><input name="${esc(f.key)}" type="${esc(f.type||'number')}" value="${esc(def)}" ${f.required===false?'':'required'} ${f.type==='number'?'step="any"':''}></div>`}
function openTool(id){const t=(state.tools||[]).find(x=>x.id===id);if(!t)return;if(t.client_tool)return openClientTool(t);openDrawer(t.name,t.description,`<form id="toolForm"><div class="tool-form-grid">${(t.fields||[]).map(fieldForTool).join('')||'<div class="tool-ready-note">No setup needed. ServiceSlate will generate the file from your current organization data.</div>'}</div><div id="toolResult"></div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Close</button><button class="btn primary">${(t.fields||[]).length?'Run Tool':'Generate'}</button></div></form>`);$('#toolForm').onsubmit=async e=>{e.preventDefault();const inputs=Object.fromEntries(new FormData(e.target).entries());const btn=e.submitter;btn.disabled=true;btn.textContent='Working…';try{const r=await api(`/api/tools/${id}/run`,{method:'POST',body:JSON.stringify({inputs})});renderToolResult(r)}catch(err){toast(err.message,'bad')}finally{btn.disabled=false;btn.textContent=(t.fields||[]).length?'Run Tool':'Generate'}}}

function openClientTool(t){
 if(t.id==='voice_note')return openVoiceTool();
 if(t.id==='barcode_scan')return openBarcodeTool();
 if(t.id==='photo_optimizer')return openPhotoTool();
 if(t.id==='share_text')return openShareTool();
 toast('This device tool is not supported yet','bad');
}
function openVoiceTool(){openDrawer('Voice Note Pad','Dictation availability depends on the browser/device. You review the text before copying it anywhere.',`<div class="field"><label>Note</label><textarea id="voicePad" rows="8" placeholder="Dictate or type here…"></textarea></div><div class="mini-sync"><span id="voiceStatus">Nothing leaves this pad until you copy it.</span></div><div class="form-actions"><button class="btn" id="voiceStart">Start Dictation</button><button class="btn primary" id="voiceCopy">Copy Note</button></div>`);const SR=window.SpeechRecognition||window.webkitSpeechRecognition;const start=$('#voiceStart');if(!SR){start.disabled=true;$('#voiceStatus').textContent='Speech recognition is not exposed by this browser. Device keyboard dictation or typing still works.'}else start.onclick=()=>{const r=new SR();r.continuous=true;r.interimResults=true;r.onstart=()=>{$('#voiceStatus').textContent='Listening… review the text before using it.';start.textContent='Listening…'};r.onerror=e=>{$('#voiceStatus').textContent=`Dictation stopped: ${e.error}`;start.textContent='Start Dictation'};r.onend=()=>{start.textContent='Start Dictation';$('#voiceStatus').textContent='Dictation stopped. Review before copying.'};r.onresult=e=>{let final='';for(let i=e.resultIndex;i<e.results.length;i++)if(e.results[i].isFinal)final+=e.results[i][0].transcript+' ';if(final)$('#voicePad').value+=final};r.start()};$('#voiceCopy').onclick=async()=>{try{await navigator.clipboard.writeText($('#voicePad').value);toast('Note copied','good')}catch{toast('Copy is not available in this browser','bad')}}}
function openBarcodeTool(){openDrawer('Barcode / QR Reader','Take or choose a photo. Detection happens on this device when the browser provides BarcodeDetector.',`<div class="field"><label>Barcode photo</label><input id="barcodeFile" type="file" accept="image/*" capture="environment"></div><div id="barcodeResult" class="tool-result"><h2>Ready for image</h2><p>No continuous camera or GPS is used.</p></div>`);$('#barcodeFile').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;const out=$('#barcodeResult');if(!('BarcodeDetector' in window)){out.innerHTML='<h2>Browser reader unavailable</h2><p>This browser does not expose BarcodeDetector. Keep the photo or enter the serial manually; a native/mobile wrapper can add broader scanning later.</p>';return}try{const bmp=await createImageBitmap(file);const formats=await BarcodeDetector.getSupportedFormats();const detector=new BarcodeDetector({formats});const codes=await detector.detect(bmp);out.innerHTML=codes.length?`<h2>${codes.length} code${codes.length===1?'':'s'} found</h2>${codes.map(c=>`<p><strong>${esc(c.rawValue)}</strong> · ${esc(c.format)}</p>`).join('')}<button class="btn small" id="copyBarcode">Copy First</button>`:'<h2>No readable code found</h2><p>Try a closer, sharper photo or enter the serial manually.</p>';if(codes.length)$('#copyBarcode').onclick=()=>navigator.clipboard.writeText(codes[0].rawValue).then(()=>toast('Code copied','good'))}catch(err){out.innerHTML=`<h2>Could not read image</h2><p>${esc(err.message)}</p>`}}}
function openPhotoTool(){openDrawer('Photo Optimizer','Resize a large image locally before attaching it. The original is not modified.',`<div class="field"><label>Photo</label><input id="photoFile" type="file" accept="image/*" capture="environment"></div><div class="form-grid"><div class="field"><label>Max width/height</label><select id="photoMax"><option value="1280">1280 px</option><option value="1600" selected>1600 px</option><option value="2048">2048 px</option></select></div><div class="field"><label>JPEG quality</label><select id="photoQuality"><option value="0.72">Smaller</option><option value="0.82" selected>Balanced</option><option value="0.9">Higher quality</option></select></div></div><div id="photoResult" class="tool-result"><h2>Choose a photo</h2><p>Processing stays in this browser.</p></div>`);$('#photoFile').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;const max=+$('#photoMax').value,q=+$('#photoQuality').value,bmp=await createImageBitmap(file),scale=Math.min(1,max/Math.max(bmp.width,bmp.height)),w=Math.round(bmp.width*scale),h=Math.round(bmp.height*scale),canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;canvas.getContext('2d').drawImage(bmp,0,0,w,h);canvas.toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob),saved=Math.max(0,100-(blob.size/file.size*100));$('#photoResult').innerHTML=`<h2>${w} × ${h}</h2><p>${bytes(file.size)} → ${bytes(blob.size)} · ${saved.toFixed(0)}% smaller</p><a class="btn primary small" href="${url}" download="ServiceSlate-${esc(file.name.replace(/\.[^.]+$/,''))}.jpg">Download Optimized Photo</a>`},'image/jpeg',q)}}
function openShareTool(){openDrawer('Device Share Sheet','Useful for handing text to an installed app without making ServiceSlate responsible for delivery.',`<div class="field"><label>Title</label><input id="shareTitle"></div><div class="field"><label>Text</label><textarea id="shareText" rows="7"></textarea></div><div class="form-actions"><button class="btn primary" id="shareNow">Open Share Sheet</button></div>`);$('#shareNow').onclick=async()=>{if(!navigator.share)return toast('This browser does not expose a share sheet','bad');try{await navigator.share({title:$('#shareTitle').value,text:$('#shareText').value})}catch(err){if(err.name!=='AbortError')toast(err.message,'bad')}}}

function renderToolResult(r){const el=$('#toolResult');if(!el)return;el.innerHTML=`<div class="tool-result"><span class="eyebrow">Result</span><h2>${esc(r.headline||'Ready')}</h2>${(r.details||[]).map(x=>`<p>${esc(x)}</p>`).join('')}${r.copy_value?`<button type="button" class="btn small" id="copyToolResult">Copy Result</button>`:''}${r.action?`<a class="btn primary small" id="toolAction" href="${esc(r.action.url)}" ${/^(https?:|mailto:|sms:|tel:)/.test(r.action.url)?'target="_blank" rel="noopener"':''}>${esc(r.action.label)}</a>`:''}</div>`;if(r.copy_value)$('#copyToolResult').onclick=async()=>{try{await navigator.clipboard.writeText(r.copy_value);toast('Copied','good')}catch{toast('Copy is not available in this browser','bad')}}}


async function renderSales(){
 const [d,customers]=await Promise.all([api('/api/sales/pipeline'),api('/api/customers')]);
 const stages=['DISCOVERY','SITE_SURVEY','QUOTE','CUSTOMER_REVIEW','APPROVED','ORDERED','INSTALLATION','COMMISSIONED','WON','LOST','ON_HOLD'];
 setMain(`<div class="page-head"><div><div class="eyebrow">Sales → installation → lifetime service</div><h1>Sales & Install</h1><p>Keep the sale connected to the equipment that will eventually need service.</p></div><button class="btn primary" id="newOpp">＋ New Opportunity</button></div>
 <div class="stat-row"><div class="stat"><div class="stat-label">Opportunities</div><div class="stat-value">${d.opportunities.length}</div><div class="stat-foot">Active sales memory</div></div><div class="stat"><div class="stat-label">Equipment orders</div><div class="stat-value">${d.orders.length}</div><div class="stat-foot">Purchase-to-install continuity</div></div><div class="stat"><div class="stat-label">Install projects</div><div class="stat-value">${d.projects.length}</div><div class="stat-foot">Commissioning creates lifetime records</div></div></div>
 <section class="panel"><div class="panel-head"><div><h2>Opportunities</h2><p>Human-owned stages; ServiceSlate remembers the next step.</p></div></div>${d.opportunities.length?d.opportunities.map(o=>`<div class="queue-row three"><div class="queue-main"><strong>${esc(o.title)}</strong><span>${esc(o.customer_name)}${o.location_name?` · ${esc(o.location_name)}`:''} · ${money(o.expected_value_cents||0)}</span></div><div><span class="pill ${tone(o.stage)}">${nice(o.stage)}</span><div class="tiny muted">${o.probability_pct||0}% · ${esc(o.owner_name||'Unassigned')}</div></div><div class="queue-action"><button class="btn small" onclick="openOpportunity('${o.id}')">Open</button></div></div>`).join(''):'<div class="empty"><strong>No opportunities yet.</strong>Create one when a customer starts discussing equipment, a site survey, or a purchase.</div>'}</section>
 <div class="content-grid"><section class="panel"><div class="panel-head"><div><h2>Equipment orders</h2></div></div>${d.orders.length?d.orders.map(o=>`<div class="history-item"><strong>${esc(o.order_number||'Equipment order')} · ${esc(o.customer_name)}</strong><p>${nice(o.status)}${o.expected_at?` · Expected ${fmtDate(o.expected_at)}`:''} · ${money(o.total_cents||0)}</p><button class="btn small" onclick="openSalesOrder('${o.id}')">Plan Installation</button></div>`).join(''):'<div class="empty">Approved purchases appear here.</div>'}</section><aside><section class="panel"><div class="panel-head"><div><h2>Install & commission</h2></div></div><div class="panel-body">${d.projects.length?d.projects.map(p=>`<div class="history-item"><strong>${esc(p.name)}</strong><p>${esc(p.customer_name)} · ${esc(p.location_name)} · ${nice(p.status)}</p><button class="btn small" onclick="openInstallProject('${p.id}')">Open Project</button></div>`).join(''):'<div class="empty">Installation projects stay linked through commissioning and equipment creation.</div>'}</div></section></aside></div>`);
 $('#newOpp').onclick=()=>openNewOpportunity(customers);
}

function openNewOpportunity(customers){openDrawer('New Opportunity','Start with the customer and the next real sales step.',`<form id="oppForm"><div class="field"><label>Customer</label><select name="customer_id" required>${customers.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Opportunity</label><input name="title" required placeholder="8 new vehicle lifts"></div><div class="form-grid"><div class="field"><label>Expected value</label><input name="value" type="number" step="0.01"></div><div class="field"><label>Target close date</label><input name="target_close_date" type="date"></div></div><div class="field"><label>Next action</label><input name="next_action" placeholder="Schedule site survey"></div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Create Opportunity</button></div></form>`);$('#oppForm').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target).entries());try{await api('/api/sales/opportunities',{method:'POST',body:JSON.stringify({command_id:uid(),customer_id:f.customer_id,title:f.title,expected_value_cents:f.value?Math.round(+f.value*100):null,target_close_date:f.target_close_date||null,next_action:f.next_action||null})});toast('Opportunity created','good');closeDrawer();renderSales()}catch(err){toast(err.message,'bad')}}}

async function openOpportunity(id){const d=await api('/api/sales/pipeline'),o=d.opportunities.find(x=>x.id===id);if(!o)return;const estimates=await api('/api/estimates');const eligible=estimates.filter(e=>e.customer_id===o.customer_id);openDrawer(o.title,`${o.customer_name} · ${nice(o.stage)}`,`<div class="field"><label>Stage</label><select id="oppStage">${['DISCOVERY','SITE_SURVEY','QUOTE','CUSTOMER_REVIEW','APPROVED','ORDERED','INSTALLATION','COMMISSIONED','WON','LOST','ON_HOLD'].map(x=>`<option ${x===o.stage?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Next action</label><input id="oppNext" value="${esc(o.next_action||'')}"></div><div class="form-actions"><button class="btn primary" id="oppSave">Save</button></div>${eligible.length?`<hr><h3>Quote</h3><div class="field"><select id="oppEstimate">${eligible.map(e=>`<option value="${e.id}">${esc(e.estimate_number)} rev ${e.revision} · ${money(e.total_cents)}</option>`).join('')}</select></div><button class="btn" id="oppQuote">Link Quote</button>`:''}<hr><h3>Purchase</h3><button class="btn" id="oppOrder">Create Equipment Order</button>`);$('#oppSave').onclick=async()=>{try{await api(`/api/sales/opportunities/${id}`,{method:'PATCH',body:JSON.stringify({version:o.version,stage:$('#oppStage').value,next_action:$('#oppNext').value||null})});toast('Opportunity updated','good');closeDrawer();renderSales()}catch(err){toast(err.message,'bad')}};$('#oppQuote')?.addEventListener('click',async()=>{try{await api(`/api/sales/opportunities/${id}/quote`,{method:'POST',body:JSON.stringify({command_id:uid(),estimate_id:$('#oppEstimate').value})});toast('Quote linked','good');closeDrawer();renderSales()}catch(err){toast(err.message,'bad')}});$('#oppOrder').onclick=async()=>{const number=await askText({title:'Create equipment order',label:'Vendor / PO reference (optional)',confirmLabel:'Create Order'});if(number===undefined)return;try{await api(`/api/sales/opportunities/${id}/orders`,{method:'POST',body:JSON.stringify({command_id:uid(),order_number:number||null})});toast('Equipment order created','good');closeDrawer();renderSales()}catch(err){toast(err.message,'bad')}}}

async function openSalesOrder(id){const [d,customers]=await Promise.all([api('/api/sales/pipeline'),api('/api/customers')]),o=d.orders.find(x=>x.id===id);if(!o)return;const c=customers.find(x=>x.id===o.customer_id),detail=await api(`/api/customers/${o.customer_id}`),locs=detail.locations||[];openDrawer('Plan Installation',`${o.customer_name} · ${o.order_number||'Equipment order'}`,`<form id="installForm"><div class="field"><label>Location</label><select name="location_id">${locs.map(l=>`<option value="${l.id}">${esc(l.name)}</option>`).join('')}</select></div><div class="field"><label>Project name</label><input name="name" value="${esc(o.opportunity_title||'Equipment Installation')}" required></div><div class="form-grid"><div class="field"><label>Planned start</label><input name="planned_start" type="date"></div><div class="field"><label>Planned finish</label><input name="planned_finish" type="date"></div></div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Create Installation Project</button></div></form>`);$('#installForm').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target).entries());try{await api(`/api/sales/orders/${id}/installation`,{method:'POST',body:JSON.stringify({command_id:uid(),location_id:f.location_id,name:f.name,planned_start:f.planned_start||null,planned_finish:f.planned_finish||null})});toast('Installation project created','good');closeDrawer();renderSales()}catch(err){toast(err.message,'bad')}}}

async function openInstallProject(id){const d=await api('/api/sales/pipeline'),p=d.projects.find(x=>x.id===id);if(!p)return;openDrawer(p.name,`${p.customer_name} · ${p.location_name}`,`<div class="notice"><strong>${nice(p.status)}</strong><p>The project can create a real installation work order, installed equipment record, and commissioning evidence.</p></div><button class="btn block" id="createInstallJob">Create Installation Work Order</button><button class="btn block" id="createInstalledEquipment">Add Installed Equipment</button><button class="btn primary block" id="commissionProject">Record Commissioning</button>`);$('#createInstallJob').onclick=async()=>{try{const r=await api(`/api/sales/projects/${id}/job`,{method:'POST',body:JSON.stringify({command_id:uid()})});toast(`${r.job_number} created and ready to schedule`,'good');closeDrawer();renderSales()}catch(err){toast(err.message,'bad')}};$('#createInstalledEquipment').onclick=()=>{openDrawer('Installed Equipment','Create the permanent service identity that survives the sale.',`<form id="installedEquipmentForm"><div class="form-grid"><div class="field"><label>Category</label><input name="category" value="Vehicle Lift" required></div><div class="field"><label>Manufacturer</label><input name="manufacturer"></div><div class="field"><label>Model</label><input name="model"></div><div class="field"><label>Serial</label><input name="serial_number"></div><div class="field"><label>Bay / area</label><input name="bay"></div><div class="field"><label>Install date</label><input name="install_date" type="date"></div></div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Create Equipment Record</button></div></form>`);$('#installedEquipmentForm').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target).entries());try{await api(`/api/sales/projects/${id}/installed-equipment`,{method:'POST',body:JSON.stringify({command_id:uid(),...f})});toast('Installed equipment is now part of lifetime service history','good');closeDrawer();renderSales()}catch(err){toast(err.message,'bad')}}};$('#commissionProject').onclick=async()=>{const result=await askText({title:'Record commissioning',message:'Enter PASS when commissioning is complete, or describe the result.',label:'Result',value:'PASS',required:true});if(!result)return;try{await api(`/api/sales/projects/${id}/commission`,{method:'POST',body:JSON.stringify({command_id:uid(),result})});toast('Commissioning recorded','good');closeDrawer();renderSales()}catch(err){toast(err.message,'bad')}}}

async function renderReadiness(){const [r,evidence,sec]=await Promise.all([api('/api/cloud/readiness'),api('/api/cloud/readiness/evidence'),api('/api/security/status')]);setMain(`<div class="page-head"><div><div class="eyebrow">Activation, not guesswork</div><h1>Production Readiness</h1><p>ServiceSlate shows what is built, what is connected, and what still needs a real company decision.</p></div><button class="btn" id="securitySetup">Account Security</button></div><section class="panel"><div class="panel-head"><div><h2>Readiness checklist</h2><p>A missing credential or human test stays visible instead of being marked complete.</p></div></div>${r.checks.map(c=>`<div class="queue-row"><div class="queue-main"><strong>${esc(c.label)}</strong><span>${esc(c.detail||'')}</span></div><div><span class="pill ${c.state==='PASS'||c.state==='NOT_REQUIRED'?'good':c.state==='OPTIONAL'?'blue':'warn'}">${nice(c.state)}</span></div></div>`).join('')}</section><div class="content-grid"><section class="panel"><div class="panel-head"><div><h2>Human sign-offs</h2></div></div><div class="panel-body"><button class="btn block" id="recordLegal">Record Approved Customer Wording</button><button class="btn block" id="recordUsability">Record Zero-Training Test</button><button class="btn block" id="recordDevice">Record Field Device Test</button><div class="tiny muted" style="margin-top:12px">These buttons record a real person’s decision/test. They do not pretend ServiceSlate performed legal or usability review itself.</div></div></section><aside><section class="panel"><div class="panel-head"><div><h2>Evidence on file</h2></div></div><div class="panel-body"><div class="compact-item"><div><strong>Legal/business approvals</strong></div><span class="pill blue">${evidence.legal.length}</span></div><div class="compact-item"><div><strong>Zero-training sessions</strong></div><span class="pill blue">${evidence.usability.length}</span></div><div class="compact-item"><div><strong>Field-device reports</strong></div><span class="pill blue">${evidence.devices.length}</span></div><div class="compact-item"><div><strong>Authenticator MFA</strong></div><span class="pill ${sec.mfa_enabled?'good':'warn'}">${sec.mfa_enabled?'On':'Available'}</span></div></div></section></aside></div>`);$('#securitySetup').onclick=openSecuritySetup;$('#recordLegal').onclick=recordLegalApproval;$('#recordUsability').onclick=recordUsability;$('#recordDevice').onclick=recordDeviceReadiness}

async function openSecuritySetup(){const s=await api('/api/security/status');openDrawer('Account Security','Use stronger controls when ServiceSlate moves beyond a local demo.',`${s.mfa_enabled?'<div class="notice"><strong>Authenticator MFA is on.</strong><p>Your password and authenticator code are required at sign-in.</p></div><button class="btn" id="disableMfa">Turn Off MFA</button>':'<div class="notice"><strong>Authenticator MFA is available.</strong><p>Set it up with any standard authenticator app.</p></div><button class="btn primary" id="setupMfa">Set Up MFA</button>'}<div class="tiny muted" style="margin-top:12px">Passkeys are reserved for a stable HTTPS deployment; ServiceSlate will not fake passkey support on an unstable local origin.</div>`);$('#setupMfa')?.addEventListener('click',async()=>{try{const r=await api('/api/security/mfa/setup',{method:'POST'});openDrawer('Add ServiceSlate to your authenticator','Use the secret or provisioning link, then enter the current code.',`<div class="field"><label>Authenticator secret</label><code class="path-code">${esc(r.secret)}</code></div><div class="field"><label>6-digit code</label><input id="enableMfaCode" inputmode="numeric"></div><button class="btn primary block" id="enableMfa">Turn On MFA</button>`);$('#enableMfa').onclick=async()=>{try{await api('/api/security/mfa/enable',{method:'POST',body:JSON.stringify({code:$('#enableMfaCode').value})});toast('MFA enabled','good');closeDrawer()}catch(err){toast(err.message,'bad')}}}catch(err){toast(err.message,'bad')}});$('#disableMfa')?.addEventListener('click',async()=>{const code=await askText({title:'Turn off MFA',label:'Authenticator code',required:true});if(!code)return;try{await api('/api/security/mfa/disable',{method:'POST',body:JSON.stringify({code})});toast('MFA disabled','good');closeDrawer()}catch(err){toast(err.message,'bad')}})}

async function recordLegalApproval(){const wording=await askText({title:'Record wording approval',message:'Paste the exact customer-facing wording that a manager/legal reviewer approved.',label:'Approved wording',type:'textarea',required:true,confirmLabel:'Record Approval'});if(!wording)return;try{await api('/api/cloud/legal-approvals',{method:'POST',body:JSON.stringify({content_type:'CUSTOMER_DISCLOSURE',content_id:'service-day-confirmation',content_version:'1',wording})});toast('Human approval recorded','good');renderReadiness()}catch(err){toast(err.message,'bad')}}
async function recordUsability(){const role=await askText({title:'Zero-training test',message:'Record the role of the first-time user who actually tried the workflow without coaching.',label:'Tester role',required:true});if(!role)return;const notes=await askText({title:'What slowed them down?',label:'Friction notes',type:'textarea',confirmLabel:'Save Test'});try{await api('/api/cloud/readiness/usability',{method:'POST',body:JSON.stringify({tester_role:role,friction_notes:notes||null,task_results:[],completed:true})});toast('Usability test recorded','good');renderReadiness()}catch(err){toast(err.message,'bad')}}
async function recordDeviceReadiness(){const label=await askText({title:'Field device test',message:'Use a real phone/tablet. Only mark this complete after offline work, reconnect, and camera/photo handling were actually tested.',label:'Device',placeholder:'Chris’s Android phone',required:true});if(!label)return;const ok=await askConfirm({title:'Did all three tests pass?',message:'Offline draft survived, reconnect synced correctly, and camera/photo workflow worked on this device.',confirmLabel:'Yes — all passed'});try{await api('/api/cloud/readiness/device',{method:'POST',body:JSON.stringify({device_label:label,browser:navigator.userAgent,capabilities:{serviceWorker:'serviceWorker' in navigator,indexedDB:!!window.indexedDB,barcode:'BarcodeDetector' in window},offline_tested:ok,reconnect_tested:ok,camera_tested:ok})});toast(ok?'Field device marked ready':'Device test saved as incomplete','good');renderReadiness()}catch(err){toast(err.message,'bad')}}



function officeDeviceId(){let id=localStorage.getItem('serviceslate-office-device');if(!id){id='dev-'+uid();localStorage.setItem('serviceslate-office-device',id)}return id}
async function officeHeartbeat(){if(!state.me||!navigator.onLine)return;try{await api('/api/lan/heartbeat',{method:'POST',body:JSON.stringify({device_id:officeDeviceId(),device_label:`${navigator.platform||'Workstation'} · ${navigator.userAgent.includes('Mobile')?'Mobile':'Browser'}`})})}catch{}}
function startLanHeartbeat(){officeHeartbeat();if(window._serviceSlateLanTimer)clearInterval(window._serviceSlateLanTimer);window._serviceSlateLanTimer=setInterval(officeHeartbeat,30000)}

async function renderOffice(){
 const [status,people,messages]=await Promise.all([api('/api/lan/status'),api('/api/lan/presence'),api('/api/lan/messages')]);
 const online=people.filter(p=>p.online);
 setMain(`<div class="page-head"><div><div class="eyebrow">Same office · same data</div><h1>Office Network</h1><p>Share one authoritative ServiceSlate workspace across computers on the same private network.</p></div><button class="btn primary" id="newOfficeMessage">＋ Message teammate</button></div>
 <div class="stat-row"><div class="stat"><div class="stat-label">Office sharing</div><div class="stat-value ${status.sharing_active?'health-ok':''}">${status.sharing_active?'Active':status.mode==='client'?'Joined':'Standalone'}</div><div class="stat-foot">${status.sharing_active?'This computer is the office host':status.mode==='client'?'Using the office host':'Local-only mode'}</div></div><div class="stat"><div class="stat-label">People online</div><div class="stat-value">${status.online_users}</div><div class="stat-foot">Seen in the last 90 seconds</div></div><div class="stat"><div class="stat-label">Unread messages</div><div class="stat-value">${status.unread_messages}</div><div class="stat-foot">Direct internal messages</div></div><div class="stat"><div class="stat-label">Shared data</div><div class="stat-value health-ok">One source</div><div class="stat-foot">Jobs · customers · files · schedules</div></div></div>
 ${status.sharing_active&&status.lan_url?`<section class="panel"><div class="panel-head"><div><h2>Join this office</h2><p>On another ServiceSlate computer, run <strong>CONFIGURE_OFFICE_NETWORK.cmd</strong>, choose Join Office, and enter this address.</p></div></div><div class="panel-body"><code class="path-code">${esc(status.lan_url)}</code>${status.lan_ip_url&&status.lan_ip_url!==status.lan_url?`<div class="tiny muted" style="margin-top:6px">IP fallback: <code>${esc(status.lan_ip_url)}</code></div>`:''}<div class="notice" style="margin-top:12px"><strong>Private network only.</strong><p>LAN mode is for a trusted office Ethernet/Wi-Fi network. Internet-facing access should use the hardened HTTPS deployment instead.</p></div></div></section>`:''}
 <div class="content-grid"><section class="panel"><div class="panel-head"><div><h2>Internal messages</h2><p>Messages stay inside your ServiceSlate organization.</p></div></div><div id="officeMessages">${officeMessageRows(messages)}</div></section><aside class="suggestion-col"><section class="panel"><div class="panel-head"><div><h2>Office presence</h2><p>Recently active ServiceSlate users.</p></div></div><div class="panel-body">${people.map(p=>`<div class="compact-item"><div><strong>${esc(p.name)}</strong><span>${esc(nice(p.role))}${p.last_seen_at?` · ${p.online?'active now':`last seen ${fmtDate(p.last_seen_at)} ${fmtTime(p.last_seen_at)}`}`:''}</span></div><span class="pill ${p.online?'good':''}">${p.online?'Online':'Offline'}</span></div>`).join('')}</div></section><section class="panel aside-gap"><div class="panel-head"><div><h2>How data sharing works</h2></div></div><div class="panel-body"><p>Joined computers do not replicate competing databases. They use the Office Host's ServiceSlate database and file store directly.</p><p class="tiny muted">Technician browser drafts/outbox still protect unsent field work when a device briefly loses Wi-Fi.</p></div></section></aside></div>`);
 $('#newOfficeMessage').onclick=()=>openOfficeMessage(people);
 $$('[data-office-message]').forEach(b=>b.onclick=async()=>{const id=b.dataset.officeMessage;try{await api(`/api/lan/messages/${id}/read`,{method:'POST'});b.closest('.queue-row')?.classList.remove('unread');b.remove()}catch(err){toast(err.message,'bad')}});
}
function officeMessageRows(messages){if(!messages.length)return '<div class="empty"><strong>No internal messages yet.</strong>Use Message teammate for a direct note or an office-wide announcement.</div>';return messages.map(m=>`<div class="queue-row three ${!m.read_at&&m.recipient_user_id===state.me.id?'unread':''}"><div class="queue-main"><strong>${esc(m.sender_name)} → ${m.recipient_name?esc(m.recipient_name):'Everyone'}</strong><span>${esc(m.body)}</span>${m.linked_entity_type?`<span class="tiny muted">Linked to ${esc(nice(m.linked_entity_type))} ${esc(m.linked_entity_id||'')}</span>`:''}</div><div><span class="pill blue">${fmtDate(m.created_at)} ${fmtTime(m.created_at)}</span></div><div class="queue-action">${!m.read_at&&m.recipient_user_id===state.me.id?`<button class="btn small" data-office-message="${m.id}">Mark Read</button>`:''}</div></div>`).join('')}
function openOfficeMessage(people){const recipients=people.filter(p=>p.user_id!==state.me.id);openDrawer('Internal Message','Send a direct ServiceSlate message or an office-wide announcement.',`<form id="officeMessageForm"><div class="field"><label>To</label><select name="recipient_user_id"><option value="">Everyone in this ServiceSlate organization</option>${recipients.map(p=>`<option value="${esc(p.user_id)}">${esc(p.name)} · ${esc(nice(p.role))}${p.online?' · online':''}</option>`).join('')}</select></div><div class="field"><label>Message</label><textarea name="body" maxlength="4000" required autofocus></textarea></div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Send</button></div></form>`);$('#officeMessageForm').onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(e.target).entries());try{await api('/api/lan/messages',{method:'POST',body:JSON.stringify({recipient_user_id:fd.recipient_user_id||null,body:fd.body})});toast('Internal message sent','good');closeDrawer();renderOffice()}catch(err){toast(err.message,'bad')}}}

async function renderSystem(){const [h,s,g]=await Promise.all([api('/api/health'),api('/api/system/status'),api('/api/governance/policy')]);const outbox=await outboxList();setMain(`<div class="page-head"><div><div class="eyebrow">System</div><h1>Settings & Backup</h1><p>Your data, backups and optional connections in one place.</p></div><div class="page-actions"><button class="btn" id="readinessBtn">Production Readiness</button><button class="btn" id="updatesBtn">Updates</button><button class="btn" id="exportAll">Export My Data</button><button class="btn primary" id="backupNow">Back Up ServiceSlate</button></div></div><div class="stat-row"><div class="stat"><div class="stat-label">Data</div><div class="stat-value health-ok">✓ Working</div><div class="stat-foot">Schema v${esc(s.schema_version)}</div></div><div class="stat"><div class="stat-label">Local files</div><div class="stat-value health-ok">✓ Working</div><div class="stat-foot">${s.records.files} attached files</div></div><div class="stat"><div class="stat-label">Field outbox</div><div class="stat-value">${outbox.length}</div><div class="stat-foot">Stored only on this browser</div></div><div class="stat"><div class="stat-label">Free space</div><div class="stat-value health-ok">${bytes(s.disk_free_bytes)}</div><div class="stat-foot">On this computer</div></div><div class="stat"><div class="stat-label">Decision safety</div><div class="stat-value health-ok">Rules first</div><div class="stat-foot">AI ${g.ai_enabled?'suggestions only':'off'} · human approval on</div></div></div><div class="content-grid"><section class="panel"><div class="panel-head"><div><h2>Backups</h2><p>Backups can be verified before you trust them.</p></div></div>${s.backups.length?s.backups.map(b=>`<div class="queue-row three"><div class="queue-main"><strong>${esc(b.name)}</strong><span>${bytes(b.size_bytes)} · ${fmtDate(b.modified_at)} ${fmtTime(b.modified_at)}</span></div><div><span class="pill blue">Local backup</span></div><div class="queue-action backup-actions"><a class="btn small" href="/api/backups/${encodeURIComponent(b.name)}/download">Download</a><button class="btn small" onclick="verifyBackup('${b.name}')">Verify</button></div></div>`).join(''):'<div class="empty"><strong>No backup yet.</strong>Create one before entering important real data.</div>'}</section><aside class="suggestion-col"><section class="panel"><div class="panel-head"><div><h2>Connections</h2><p>Optional adapters never block core records.</p></div></div><div class="panel-body">${s.integrations.map(i=>`<div class="compact-item"><div><strong>${esc(i.provider)}</strong><span>${i.last_error?esc(i.last_error):'Core ServiceSlate works without it.'}</span></div><span class="pill ${tone(i.state)}">${nice(i.state)}</span></div>`).join('')||'<div class="empty">No connectors configured.</div>'}</div></section><section class="panel aside-gap"><div class="panel-head"><div><h2>Bring in customers</h2><p>CSV staging checks problems before committing records.</p></div></div><div class="panel-body"><input id="importCsv" type="file" accept=".csv,text/csv"><div id="importResult" class="tiny muted" style="margin-top:9px">Nothing imports until you review the preview.</div></div></section>${state.me.organization_profile==='automotive_equipment'?`<section class="panel aside-gap"><div class="panel-head"><div><h2>Bring in old work orders</h2><p>Preserve FastField / NoteWise history with its original source.</p></div></div><div class="panel-body"><div class="field"><label>Source</label><select id="historySource"><option>FastField</option><option>NoteWise</option><option>QuickBooks</option><option>Legacy</option></select></div><input id="importHistoryCsv" type="file" accept=".csv,text/csv"><div id="historyImportResult" class="tiny muted" style="margin-top:9px">CSV columns can include customer, work order, date, serial, technician, complaint, finding, cause, correction and verification.</div></div></section>`:''}<section class="panel aside-gap"><div class="panel-head"><div><h2>Restore</h2><p>ServiceSlate creates a safety backup first.</p></div></div><div class="panel-body"><input id="restoreBackup" type="file" accept=".zip,application/zip"><div class="tiny muted" style="margin-top:9px">Choose a ServiceSlate backup. You will confirm before anything changes.</div></div></section><section class="panel aside-gap"><div class="panel-head"><div><h2>Data location</h2></div></div><div class="panel-body"><code class="path-code">${esc(s.data_path)}</code></div></section></aside></div>`);
 $('#readinessBtn').onclick=()=>navigate('readiness');$('#updatesBtn').onclick=openUpdateStatus;
 $('#backupNow').onclick=async()=>{const r=await api('/api/backups',{method:'POST'});toast(`Backup created: ${r.filename}`,'good');renderSystem()};
 $('#exportAll').onclick=()=>{window.location='/api/export/all'};
 $('#importCsv').onchange=async e=>{const f=e.target.files[0];if(!f)return;const form=new FormData();form.append('file',f);try{const r=await rawFetch('/api/import/customers/preview',{method:'POST',body:form});$('#importResult').innerHTML=`<b>${r.row_count} rows found.</b> ${r.ready_count} ready · ${r.issue_count} need review. <button class="btn small" id="reviewImport">Review</button>`;$('#reviewImport').onclick=()=>openImportReview(r.batch_id)}catch(err){toast(err.message,'bad')}};const history=$('#importHistoryCsv');if(history)history.onchange=async e=>{const f=e.target.files[0];if(!f)return;const form=new FormData();form.append('file',f);form.append('source_system',$('#historySource').value);try{const r=await rawFetch('/api/import/work-history/preview',{method:'POST',body:form});$('#historyImportResult').innerHTML=`<b>${r.row_count} old work orders found.</b> ${r.ready_count} ready · ${r.issue_count} need review. <button class="btn small" id="reviewHistoryImport">Review</button>`;$('#reviewHistoryImport').onclick=()=>openImportReview(r.batch_id)}catch(err){toast(err.message,'bad')}};
 const restore=$('#restoreBackup');if(restore)restore.onchange=async e=>{const f=e.target.files[0];if(!f)return;if(!(await askConfirm({title:'Restore this backup?',message:'ServiceSlate will create a safety backup of the current data first, then replace the working data with this backup.',confirmLabel:'Restore Backup',danger:true}))){e.target.value='';return}const form=new FormData();form.append('file',f);try{const r=await rawFetch('/api/restore',{method:'POST',body:form});toast(r.message,'good');state.me=null;setTimeout(renderLogin,500)}catch(err){toast(err.message,'bad');e.target.value=''}};
}
async function openUpdateStatus(){try{const u=await api('/api/updates/status');const action=u.available&&u.role_can_install?'<button class="btn primary block" id="installUpdate">Verify & Install Update</button>':'';const rollback=u.rollback_available&&u.role_can_install?'<button class="btn block" id="rollbackUpdate">Roll Back Application Version</button>':'';openDrawer('ServiceSlate Updates',u.configured?'ServiceSlate checks a company-approved release manifest and verifies the installer before it can run.':'No update channel is connected yet.',`<div class="notice"><strong>${esc(nice(u.state))}</strong><p>Current: ${esc(u.current_version)}${u.latest_version?` · Latest: ${esc(u.latest_version)}`:''}</p>${u.notes?`<p>${esc(u.notes)}</p>`:''}</div>${action}${rollback}<div class="tiny muted">Company data is stored separately from the application. ServiceSlate makes a safety backup before an update or rollback. Database restoration is always a separate explicit decision.</div>`);$('#installUpdate')?.addEventListener('click',async()=>{if(!(await askConfirm({title:'Install verified ServiceSlate update?',message:'ServiceSlate will make a safety backup before launching the signed installer.',confirmLabel:'Install Update'})))return;try{const r=await api('/api/updates/install',{method:'POST',body:JSON.stringify({confirm:true})});toast(`Update ${r.version||''} launched`,'good')}catch(err){toast(err.message,'bad')}});$('#rollbackUpdate')?.addEventListener('click',async()=>{if(!(await askConfirm({title:'Roll back the ServiceSlate application?',message:'This changes the application version only. Your company data is not silently rolled back. ServiceSlate creates a fresh safety backup first.',confirmLabel:'Launch Rollback',danger:true})))return;try{await api('/api/updates/rollback',{method:'POST',body:JSON.stringify({confirm:true})});toast('Verified rollback installer launched','good')}catch(err){toast(err.message,'bad')}})}catch(err){toast(err.message,'bad')}}
async function verifyBackup(name){try{await api(`/api/backups/${encodeURIComponent(name)}/verify`,{method:'POST'});toast('Backup verified','good')}catch(e){toast(e.message,'bad')}}
async function openImportReview(id){const d=await api(`/api/import/${id}`),history=['WORK_HISTORY_CSV','FASTFIELD_EMAIL'].includes(d.batch.source_type),fastfield=d.batch.source_type==='FASTFIELD_EMAIL';openDrawer(history?'Work History Review':'Import Preview',`${d.batch.ready_count} ready · ${d.batch.issue_count} need attention`,`${fastfield?'<div class="notice"><strong>FastField source preserved · AI not used.</strong><p>ServiceSlate extracted structured information and matched what it could. A human must accept important information before it becomes trusted company history.</p></div>':''}${d.rows.slice(0,50).map(r=>{const method=r.normalized._provenance?.method||r.normalized.derivation_method||r.derivation_method||'DETERMINISTIC_IMPORT';const ai=!!(r.normalized._provenance?.ai_used||r.normalized.ai_used||r.ai_used);return `<div class="history-item"><strong>${esc(r.normalized.name||r.normalized.customer||r.normalized['customer name']||r.normalized.source_reference||`Row ${r.row_number}`)}</strong><p>${history&&r.normalized.performed_at?`${esc(r.normalized.performed_at)} · `:''}${r.issue?`⚠ ${esc(r.issue)}`:(r.review_state==='HUMAN_APPROVED'?'Accepted by a person':'Ready for your review')}</p><div class="provenance-row"><span class="pill ${r.review_state==='HUMAN_APPROVED'?'good':r.state==='READY'?'blue':'warn'}">${r.review_state==='HUMAN_APPROVED'?'Human approved':r.state==='READY'?'Needs human approval':nice(r.state)}</span><span class="tiny muted">${esc(nice(method))}${ai?' · AI-assisted':' · AI not used'}</span></div></div>`}).join('')}<div class="form-actions"><button class="btn" onclick="closeDrawer()">Close</button><button class="btn primary" id="commitImport">${history?'Approve & Add Ready History':'Import Ready Records'}</button></div>`);$('#commitImport').onclick=async()=>{const endpoint=history?`/api/import/work-history/${id}/commit`:`/api/import/${id}/commit`;const r=await api(endpoint,{method:'POST',body:JSON.stringify({command_id:uid()})});toast(history?`${r.created} reviewed historical work order${r.created===1?'':'s'} added`:`${r.created} customers imported`,'good');closeDrawer();navigate(history?'search':'customers')}}

async function rawFetch(path,opt={}){const headers={...(state.me?.csrf_token?{'X-CSRF-Token':state.me.csrf_token}:{}),...(opt.headers||{})};const r=await fetch(path,{...opt,headers});let body=null;try{body=await r.json()}catch{}if(!r.ok){const e=new Error(body?.detail||`Request failed (${r.status})`);e.status=r.status;throw e}return body}
async function openFilePicker(entityType,entityId){openDrawer('Add File or Photo','Files are hashed so a retry does not create duplicates.',`<form id="uploadForm"><div class="field"><label>Category</label><select name="category"><option>PHOTO</option><option>DOCUMENT</option><option>NAMEPLATE</option><option>BEFORE</option><option>AFTER</option><option>DEFICIENCY</option></select></div><div class="field"><label>File / photo</label><input type="file" name="file" required accept="image/*,.pdf,.txt,.csv"></div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Upload</button></div></form>`);$('#uploadForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);fd.append('entity_type',entityType);fd.append('entity_id',entityId);try{const r=await rawFetch('/api/files',{method:'POST',body:fd});toast(r.already_exists?'That file was already attached':'File attached','good');closeDrawer();if(entityType==='job')openJob(entityId)}catch(err){toast(err.message,'bad')}}}

// V2 durable field cache and outbox.
async function storeGet(store,key){const db=await openDraftDB();const actual=store===CACHE_STORE?scopedKey(key):key;return await new Promise((res,rej)=>{const r=db.transaction(store).objectStore(store).get(actual);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
async function storePut(store,key,value){const db=await openDraftDB();const actual=store===CACHE_STORE?scopedKey(key):key;return await new Promise((res,rej)=>{const tx=db.transaction(store,'readwrite');const os=tx.objectStore(store);store===OUTBOX_STORE?os.put(value):os.put(value,actual);tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})}
async function storeDelete(store,key){const db=await openDraftDB();const actual=store===CACHE_STORE?scopedKey(key):key;return await new Promise((res,rej)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).delete(actual);tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})}
async function outboxList(){try{const db=await openDraftDB();return await new Promise((res,rej)=>{const r=db.transaction(OUTBOX_STORE).objectStore(OUTBOX_STORE).getAll();r.onsuccess=()=>res((r.result||[]).filter(x=>state.me&&x.ownerOrg===state.me.organization_id&&x.ownerUser===state.me.id));r.onerror=()=>rej(r.error)})}catch{return []}}
async function queueJson(path,body){const item={id:body.command_id||uid(),kind:'json',path,method:'POST',body,ownerOrg:state.me.organization_id,ownerUser:state.me.id,createdAt:new Date().toISOString()};await storePut(OUTBOX_STORE,item.id,item);return item}
async function queueFile(jobId,file,category='PHOTO'){const id=uid();await storePut(OUTBOX_STORE,id,{id,kind:'file',jobId,category,name:file.name,type:file.type,blob:file,ownerOrg:state.me.organization_id,ownerUser:state.me.id,createdAt:new Date().toISOString()});return id}
async function syncOutbox(){if(!navigator.onLine||!state.me)return;const items=(await outboxList()).sort((a,b)=>a.createdAt.localeCompare(b.createdAt));for(const item of items){try{if(item.kind==='json'){await api(item.path,{method:item.method||'POST',body:JSON.stringify(item.body)})}else if(item.kind==='file'){const fd=new FormData();fd.append('entity_type','job');fd.append('entity_id',item.jobId);fd.append('category',item.category);fd.append('file',item.blob,item.name);await rawFetch('/api/files',{method:'POST',body:fd})}await storeDelete(OUTBOX_STORE,item.id)}catch(e){if(e.status===401||String(e.message).includes('Sign in'))break;if(e.status&&e.status<500){item.needsAttention=true;item.lastError=e.message;await storePut(OUTBOX_STORE,item.id,item);const badge=$('#draftStatus');if(badge)badge.textContent='Saved work needs attention before it can sync';return}return}}const badge=$('#draftStatus');if(badge)badge.textContent='All saved field work is synced'}
async function reviewFieldOutbox(){const items=await outboxList();openDrawer('Saved Field Work','These items remain on this device until ServiceSlate confirms them.',items.length?items.map(i=>`<div class="history-item"><strong>${i.kind==='file'?`Photo · ${esc(i.name)}`:`Pending ${esc(i.path.split('/').pop())}`}</strong><p>Saved ${fmtDate(i.createdAt)} ${fmtTime(i.createdAt)}${i.lastError?`<br><span class="pill high">${esc(i.lastError)}</span>`:''}</p>${i.kind==='file'?`<button class="btn small" data-save-local="${i.id}">Save a Copy</button>`:''}</div>`).join('')+`<div class="form-actions"><button class="btn" onclick="closeDrawer()">Close</button>${navigator.onLine?'<button class="btn primary" onclick="syncOutbox();closeDrawer()">Try Sync Again</button>':''}</div>`:'<div class="empty"><strong>Nothing waiting.</strong>All submitted field work has been confirmed by ServiceSlate.</div>');$$('[data-save-local]').forEach(b=>b.onclick=async()=>{const all=await outboxList(),item=all.find(x=>x.id===b.dataset.saveLocal);if(!item?.blob)return;const url=URL.createObjectURL(item.blob),a=document.createElement('a');a.href=url;a.download=item.name||'ServiceSlate-field-photo';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}
window.addEventListener('online',()=>{toast('Connection restored — syncing saved field work','good');syncOutbox()});
setInterval(()=>syncOutbox().catch(()=>{}),20000);

async function renderTech(){
 try{if(navigator.storage?.persist)await navigator.storage.persist()}catch{}
 let d;
 try{d=await api('/api/tech/today');await storePut(CACHE_STORE,'tech-today',d)}catch(e){d=await storeGet(CACHE_STORE,'tech-today');if(!d)throw e;toast('Showing downloaded work — ServiceSlate is currently unreachable')}
 if(d.profile==='grooming')return renderGroomerTech(d);
 const visits=d.visits||[],pending=await outboxList();
 setMain(`<div class="page-head"><div><div class="eyebrow">My work</div><h1>Today</h1><p>Everything you need for the job. Your notes save on this device as you work.</p></div><div><span class="pill ${navigator.onLine?'good':'warn'}">${navigator.onLine?'Online':'Offline'}</span></div></div><div class="mobile-shell">${visits.length?`<section class="tech-next"><div class="eyebrow">Next assigned work</div><h2>${esc(visits[0].customer_name)}</h2><p>${esc(visits[0].job_number)} · ${esc(visits[0].description)}</p><p>${esc([visits[0].manufacturer,visits[0].model,visits[0].serial_number].filter(Boolean).join(' · '))}</p>${visits[0].crew_min>1?`<div class="notice">Crew job · ${visits[0].crew_min} technicians${visits[0].simultaneous_crew_minutes?` · ${visits[0].simultaneous_crew_minutes} shared minutes`:''}</div>`:''}<button class="btn primary block tech-primary" onclick="openTechJob('${visits[0].job_id}')">Start or continue</button></section>`:'<div class="empty"><strong>No assigned work.</strong>Your field queue is clear.</div>'}<div class="tech-list">${visits.slice(1).map(v=>`<div class="tech-job"><div><h3>${esc(v.customer_name)}</h3><p>${fmtTime(v.start_at)} · ${esc(v.description)}</p></div><button class="btn small" onclick="openTechJob('${v.job_id}')">Open</button></div>`).join('')}</div><div class="offline-bar"><span class="dot ${pending.length?'local':''}"></span><span id="draftStatus">${pending.length?`${pending.length} change${pending.length===1?'':'s'} stored on this device${pending.some(x=>x.needsAttention)?' · needs attention':''}`:'Field drafts save on this device'}</span>${pending.length?'<button class="mini-sync" onclick="reviewFieldOutbox()">Review</button>':''}${pending.length&&navigator.onLine?'<button class="mini-sync" onclick="syncOutbox()">Sync</button>':''}</div></div>`);syncOutbox().catch(()=>{})
}

window.openTechJob=async jobId=>{
 let d;try{d=await api(`/api/jobs/${jobId}/context`);await storePut(CACHE_STORE,`context:${jobId}`,d)}catch(e){d=await storeGet(CACHE_STORE,`context:${jobId}`);if(!d)throw e;toast('Using downloaded job context')}
 const j=d.job,draft=await draftGet(jobId)||{};state.techInspectionTemplates=d.inspection_templates||[];
 openDrawer(j.customer_name,`${j.job_number} · ${j.manufacturer||''} ${j.model||j.job_type}`,`
 <div class="context-card tech-context"><h3>What you are here for</h3><div class="content"><b>${esc(j.description)}</b><br>${esc([j.address1,j.city,j.bay].filter(Boolean).join(' · '))}<br>${esc([j.manufacturer,j.model,j.serial_number].filter(Boolean).join(' · '))}</div></div>
 <details class="context-card" open><summary>Relevant approved history <span>${d.history.length}</span></summary><div class="content">${d.history.map(h=>`<div class="history-item"><strong>${esc(h.job_number)} · ${esc(h.description)}</strong><p><b>Finding:</b> ${esc(h.finding||'—')}<br><b>Correction:</b> ${esc(h.correction||'—')}<br><b>Verified:</b> ${esc(h.verification||'—')}</p>${h.parts?.length?`<p><b>Parts:</b> ${h.parts.map(p=>esc(p.part||p.name||p.description)).join(', ')}</p>`:''}</div>`).join('')||'No approved history for this equipment.'}</div></details>
 ${j.warranty_until||j.inspection_due_date||d.open_recommendations?.length?`<details class="context-card" open><summary>Watch before you work</summary><div class="content">${j.warranty_until?`<div class="history-item"><strong>Warranty on file</strong><p>Through ${fmtDate(j.warranty_until)}. Confirm coverage before treating work as ordinary billable repair.</p></div>`:''}${j.inspection_due_date?`<div class="history-item"><strong>Inspection due</strong><p>${fmtDate(j.inspection_due_date)}</p></div>`:''}${(d.open_recommendations||[]).map(r=>`<div class="history-item"><strong>${esc(r.summary)}</strong><p>${nice(r.urgency)} · ${esc(r.details||'Open recommendation')}</p></div>`).join('')}</div></details>`:''}
 ${d.contacts?.length?`<details class="context-card"><summary>Site contacts & access</summary><div class="content">${d.contacts.map(c=>`<div class="history-item"><strong>${esc(c.name)}${c.title?` · ${esc(c.title)}`:''}</strong><p>${esc(c.phone||'')}${c.email?` · ${esc(c.email)}`:''}</p></div>`).join('')}${j.access_notes?`<div class="notice">${esc(j.access_notes)}</div>`:''}</div></details>`:''}
 ${d.similar_history?.length?`<details class="context-card"><summary>Similar approved repairs <span>${d.similar_history.length}</span></summary><div class="content">${d.similar_history.map(h=>`<div class="history-item"><strong>${esc(h.job_number)} · ${esc(h.manufacturer||'')} ${esc(h.model||'')}</strong><p><b>Finding:</b> ${esc(h.finding||'—')}<br><b>Correction:</b> ${esc(h.correction||'—')}</p></div>`).join('')}</div></details>`:''}
 ${d.files?.length?`<details class="context-card"><summary>Job & equipment files <span>${d.files.length}</span></summary><div class="content">${d.files.map(f=>`<div class="compact-item"><div><strong>${esc(f.original_name)}</strong><span>${nice(f.category)} · ${bytes(f.size_bytes)}</span></div><a class="btn small" href="/api/files/${f.id}/download" target="_blank">Open</a></div>`).join('')}</div></details>`:''}
 ${d.inspections?.length?`<details class="context-card"><summary>Previous inspections <span>${d.inspections.length}</span></summary><div class="content">${d.inspections.map(i=>`<div class="history-item"><strong>${fmtDate(i.inspection_date)} · ${esc(i.template_name)}</strong><p><span class="pill ${i.result==='PASS'?'good':'high'}">${esc(i.result)}</span> · ${esc(i.inspector_name)}${i.summary?`<br>${esc(i.summary)}`:''}</p></div>`).join('')}</div></details>`:''}
 ${d.inspection_templates?.length?`<div class="tech-primary-action"><button type="button" class="btn block" onclick="openTechInspection('${jobId}','${j.equipment_id}',state.techInspectionTemplates)">◈ Record Equipment Inspection</button></div>`:''}
 <form id="techForm"><div class="field"><label>What did you find?</label><textarea name="finding" required placeholder="What was actually wrong?">${esc(draft.finding||'')}</textarea></div><div class="field"><label>Cause (if known)</label><textarea name="cause" placeholder="What caused it?">${esc(draft.cause||'')}</textarea></div><div class="field"><label>What did you do?</label><textarea name="correction" required placeholder="Repair, adjustment, replacement, inspection…">${esc(draft.correction||'')}</textarea></div><div class="field"><label>How did you verify it?</label><textarea name="verification" required placeholder="Cycles, measurement, functional test…">${esc(draft.verification||'')}</textarea></div>
 <div class="entry-builder"><div class="builder-head"><strong>Measurements</strong><button type="button" class="btn small" id="addMeasurement">＋ Measurement</button></div><div id="measurementRows"></div></div>
 <div class="entry-builder"><div class="builder-head"><strong>Parts used / needed</strong><button type="button" class="btn small" id="addTechPart">＋ Part</button></div><div id="techPartRows"></div></div>
 <div class="entry-builder"><div class="builder-head"><strong>Recommendations</strong><button type="button" class="btn small" id="addTechRec">＋ Recommendation</button></div><div id="techRecRows"></div></div>
 <div class="entry-builder"><div class="builder-head"><strong>Photos</strong><span class="tiny muted">Saved locally until uploaded</span></div><input id="techPhotos" type="file" accept="image/*" capture="environment" multiple></div>
 <div class="field"><label>Customer summary</label><textarea name="customer_report" placeholder="What the customer should see on the completed work record.">${esc(draft.customer_report||'')}</textarea></div><div class="field"><label>Internal note</label><textarea name="internal_note" placeholder="Technical detail for the next person. This is not customer-facing.">${esc(draft.internal_note||'')}</textarea></div><div class="form-grid"><div class="field"><label>Outcome</label><select name="outcome">${['COMPLETED','NEED_PARTS','NEED_RETURN_VISIT','NEED_SECOND_TECHNICIAN','NEED_MORE_DIAGNOSTIC_TIME','NEED_MANUFACTURER_INFORMATION','CUSTOMER_UNAVAILABLE','EQUIPMENT_INACCESSIBLE','ADDITIONAL_AUTHORIZATION_REQUIRED','UNABLE_TO_REPRODUCE','SAFETY_RESTRICTION'].map(o=>`<option value="${o}" ${draft.outcome===o?'selected':''}>${nice(o)}</option>`).join('')}</select></div><div class="field"><label>Labor minutes</label><input name="labor_minutes" type="number" min="0" value="${esc(draft.labor_minutes||'')}"></div><div class="field"><label>Customer acknowledgement (if needed)</label><input name="signature_name" value="${esc(draft.signature_name||'')}" placeholder="Signer name"></div></div><div class="field"><label>Safety restriction details (only when applicable)</label><textarea name="safety_restriction">${esc(draft.safety_restriction||'')}</textarea></div><div class="save-state" id="saveState">${draft._savedAt?`Draft restored · ${fmtTime(draft._savedAt)}`:'Saved automatically on this device'}</div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Close</button><button class="btn primary" type="submit">Send to Coordinator</button></div></form>`);
 const f=$('#techForm');
 const addMeasure=(x={})=>$('#measurementRows').insertAdjacentHTML('beforeend',`<div class="structured-row measurement-row"><input class="mName" placeholder="Measurement" value="${esc(x.name||'')}"><input class="mBefore" placeholder="Before" type="number" step="any" value="${esc(x.before??'')}"><span>→</span><input class="mAfter" placeholder="After / value" type="number" step="any" value="${esc(x.after??x.value??'')}"><input class="mUnit" placeholder="Unit" value="${esc(x.unit||'')}"><button type="button" class="icon-btn" onclick="this.parentElement.remove()">×</button></div>`);
 const addPart=(x={})=>$('#techPartRows').insertAdjacentHTML('beforeend',`<div class="structured-row part-row"><input class="pName" placeholder="Part / material" value="${esc(x.part||x.name||'')}"><input class="pQty" placeholder="Qty" type="number" step=".01" min=".01" value="${esc(x.qty||1)}"><button type="button" class="icon-btn" onclick="this.parentElement.remove()">×</button></div>`);
 const addRec=(x={})=>$('#techRecRows').insertAdjacentHTML('beforeend',`<div class="structured-row rec-row"><input class="rSummary" placeholder="Recommendation" value="${esc(x.summary||'')}"><select class="rUrgency">${['MONITOR','RECOMMENDED','SOON','SAFETY_CONCERN'].map(v=>`<option ${x.urgency===v?'selected':''}>${v}</option>`).join('')}</select><button type="button" class="icon-btn" onclick="this.parentElement.remove()">×</button></div>`);
 (draft.measurements||[]).forEach(addMeasure);(draft.parts||[]).forEach(addPart);(draft.recommendations||[]).forEach(addRec);
 $('#addMeasurement').onclick=()=>addMeasure();$('#addTechPart').onclick=()=>addPart();$('#addTechRec').onclick=()=>addRec();
 const collect=()=>{const obj=Object.fromEntries(new FormData(f).entries());obj.labor_minutes=obj.labor_minutes?+obj.labor_minutes:null;obj.measurements=$$('.measurement-row').map(r=>({name:$('.mName',r).value,before:$('.mBefore',r).value===''?null:+$('.mBefore',r).value,after:$('.mAfter',r).value===''?null:+$('.mAfter',r).value,unit:$('.mUnit',r).value})).filter(x=>x.name);obj.parts=$$('.part-row').map(r=>({part:$('.pName',r).value,qty:+$('.pQty',r).value||1})).filter(x=>x.part);obj.recommendations=$$('.rec-row').map(r=>({summary:$('.rSummary',r).value,urgency:$('.rUrgency',r).value})).filter(x=>x.summary);return obj};
 const save=async()=>{const obj=collect();obj._savedAt=new Date().toISOString();await draftPut(jobId,obj);$('#saveState').textContent='Saved on this device ✓'};let t;f.oninput=()=>{clearTimeout(t);$('#saveState').textContent='Saving…';t=setTimeout(save,300)};
 $('#techPhotos').onchange=async e=>{for(const file of e.target.files)await queueFile(jobId,file,'PHOTO');$('#saveState').textContent=`${e.target.files.length} photo${e.target.files.length===1?'':'s'} saved on this device`;if(navigator.onLine)syncOutbox()};
 f.onsubmit=async e=>{e.preventDefault();await save();const obj=collect();if(!obj.finding||!obj.correction||!obj.verification)return toast('Finding, correction and verification are required','bad');if(obj.outcome==='SAFETY_RESTRICTION'&&!obj.safety_restriction)return toast('Describe the safety restriction','bad');const payload={command_id:uid(),complaint:j.description,...obj};try{await api(`/api/jobs/${jobId}/submit-work`,{method:'POST',body:JSON.stringify(payload)});await draftDelete(jobId);toast('Work sent to coordinator','good');closeDrawer();renderTech();syncOutbox()}catch(err){if(err.status&&err.status<500){toast(err.message,'bad');return}await queueJson(`/api/jobs/${jobId}/submit-work`,payload);await draftDelete(jobId);toast('ServiceSlate is unreachable. Submission is safely stored on this device and will sync later.','good');closeDrawer();renderTech()}}
};



async function openBusinessSetup(){
 const info=await fetch('/api/setup/status').then(r=>r.json());
 openDrawer('Set Up ServiceSlate','Five short steps. No server or database setup.',`<form id="businessSetupForm">
 <div class="setup-step"><span>1</span><div><strong>What kind of business?</strong><p>Only the tools for this business will load.</p></div></div>
 <div class="profile-choice">${info.profiles.map((p,i)=>`<label><input type="radio" name="profile" value="${p.id}" ${i===0?'checked':''}><span><b>${esc(p.name)}</b><small>${esc(p.description)}</small></span></label>`).join('')}</div>
 <div class="setup-step"><span>2</span><div><strong>Your business</strong><p>Start with the basics. You can add the rest later.</p></div></div>
 <div class="field"><label>Business name</label><input name="business_name" required autofocus></div>
 <div class="form-grid"><div class="field"><label>Main phone</label><input name="phone"></div><div class="field"><label>Street address</label><input name="address1"></div><div class="field"><label>City</label><input name="city"></div><div class="field"><label>State</label><input name="state" value="CA"></div><div class="field"><label>ZIP</label><input name="postal_code"></div></div>
 <div class="setup-step"><span>3</span><div><strong>Your administrator account</strong><p>This is the person setting up ServiceSlate.</p></div></div>
 <div class="field"><label>Your name</label><input name="admin_name" required></div><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>Password</label><input name="password" type="password" minlength="12" required><small class="muted">At least 12 characters.</small></div>
 <div class="setup-ready"><b>That’s it.</b><span>ServiceSlate will create the local data store and open your business.</span></div>
 <div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Create My ServiceSlate</button></div></form>`);
 $('#businessSetupForm').onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.target).entries());try{await api('/api/setup/organization',{method:'POST',body:JSON.stringify(body)});toast('ServiceSlate is ready','good');closeDrawer();await boot()}catch(err){toast(err.message,'bad')}};
}

async function renderTeam(){
 const team=await api('/api/team');
 const roles=state.me.organization_profile==='grooming'?['ADMIN','MANAGER','RECEPTION','GROOMER','READ_ONLY']:['ADMIN','MANAGER','COORDINATOR','TECHNICIAN','BILLING','READ_ONLY'];
 setMain(`<div class="page-head"><div><h1>Team</h1><p>Add people with the smallest role they need. Account recovery stays human-controlled.</p></div><button class="btn primary" id="addTeamMember">＋ Add Person</button></div><section class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Person</th><th>Role</th><th>Qualifications</th><th>Status</th><th></th></tr></thead><tbody>${team.map(m=>`<tr><td><strong>${esc(m.name)}</strong><div class="tiny muted">${esc(m.email||'')}</div></td><td><span class="pill blue">${nice(m.role)}</span></td><td>${(m.qualifications||[]).map(q=>`<span class="pill">${esc(q)}</span>`).join(' ')||'<span class="muted">—</span>'}</td><td><span class="pill ${m.locked_until?'warn':m.active?'good':'warn'}">${m.locked_until?'Locked':m.active?'Active':'Inactive'}</span>${m.force_password_change?'<div class="tiny muted">Password change required</div>':''}</td><td><button class="btn small" data-account="${m.id}">Account</button></td></tr>`).join('')}</tbody></table></div></section>`);
 $('#addTeamMember').onclick=()=>openTeamMember(roles);
 $$('[data-account]').forEach(b=>b.onclick=()=>openTeamAccount(team.find(x=>x.id===b.dataset.account)));
}
function openTeamMember(roles){openDrawer('Add Person','Give them a role and a temporary password. They can be required to replace it at first sign-in.',`<form id="teamMemberForm"><div class="field"><label>Name</label><input name="name" required autofocus></div><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>Role</label><select name="role">${roles.map(r=>`<option value="${r}">${nice(r)}</option>`).join('')}</select></div><div class="field"><label>Temporary password</label><input name="temporary_password" minlength="12" autocomplete="new-password" required></div><div class="field"><label>Qualifications (optional)</label><input name="qualifications_text" placeholder="LIFT, INSTALL, HUNTER"></div><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Add Person</button></div></form>`);$('#teamMemberForm').onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(e.target).entries());const body={name:fd.name,email:fd.email,role:fd.role,temporary_password:fd.temporary_password,qualifications:(fd.qualifications_text||'').split(',').map(x=>x.trim()).filter(Boolean)};try{await api('/api/team',{method:'POST',body:JSON.stringify(body)});toast('Person added','good');closeDrawer();renderTeam()}catch(err){toast(err.message,'bad')}}}


async function renderVehicles(){
 const [rows,team,remote,branches]=await Promise.all([api('/api/vehicles'),api('/api/team'),api('/api/remote-starts'),api('/api/branches')]);
 const techs=team.filter(x=>x.role==='TECHNICIAN');for(const v of rows){try{v.stock=await api(`/api/vehicles/${v.id}/stock`)}catch{v.stock=[]}}
 const canApprove=['ADMIN','MANAGER'].includes(state.me.role);
 setMain(`<div class="page-head"><div><h1>Vehicles</h1><p>Work resources and soft stock. ServiceSlate does not collect GPS, dash-cam or driver-history data.</p></div><div class="page-actions"><button class="btn" id="remoteStartBtn" ${canApprove?'':'disabled'}>Approved Remote Start</button><button class="btn primary" id="addVehicle">＋ Vehicle</button></div></div>
 ${remote.length?`<section class="panel" style="margin-bottom:14px"><div class="panel-head"><div><h2>Approved remote starts</h2><p>Specific workday exceptions only — not employee location history.</p></div></div>${remote.map(r=>`<div class="queue-row three"><div class="queue-main"><strong>${esc(r.technician_name)} · ${fmtDate(r.work_date)}</strong><span>${esc(r.origin_label)}${r.unit_number?` · Truck ${esc(r.unit_number)}`:''}</span></div><div class="queue-secondary">${esc(r.reason)}<span>${r.expected_return_label?`Return: ${esc(r.expected_return_label)}`:''}</span></div><div><span class="pill good">Approved</span></div></div>`).join('')}</section>`:''}
 <div class="vehicle-grid">${rows.map(v=>`<article class="vehicle-card"><header><div><span class="eyebrow">Truck</span><h2>${esc(v.unit_number)}</h2><p>${esc(v.description||'Service vehicle')}</p></div><span class="pill ${tone(v.availability)}">${nice(v.availability)}</span></header><div class="vehicle-meta"><span><small>Assigned</small><b>${esc(v.assigned_technician||'Unassigned')}</b></span><span><small>Normal start</small><b>${esc(v.branch||'—')} branch</b></span></div><div class="stock-list"><h3>Soft inventory</h3>${v.stock.map(i=>`<div><span>${esc(i.item_name)}</span><span class="pill ${tone(i.state)}">${nice(i.state)}</span></div>`).join('')||'<p class="muted tiny">No expected stock recorded.</p>'}</div><button class="btn small block" onclick="openVehicleStock('${v.id}')">Update Stock</button></article>`).join('')}</div>`);
 $('#addVehicle').onclick=()=>openVehicleCreate(techs,branches);if(canApprove)$('#remoteStartBtn').onclick=()=>openRemoteStart(techs,rows);
}
function openRemoteStart(techs,vehicles){const tomorrow=new Date(Date.now()+86400000).toISOString().slice(0,10);openDrawer('Approve Remote Start','A one-day planning exception. No GPS is collected.',`<form id="remoteStartForm"><div class="field"><label>Technician</label><select name="technician_user_id">${techs.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></div><div class="field"><label>Truck</label><select name="vehicle_id"><option value="">No truck selected</option>${vehicles.map(v=>`<option value="${v.id}">Truck ${esc(v.unit_number)}</option>`).join('')}</select></div><div class="field"><label>Workday</label><input type="date" name="work_date" value="${tomorrow}" required></div><div class="field"><label>Approved start area</label><input name="origin_label" placeholder="Example: Madera area" required><small class="muted">Use the minimum location detail needed for planning.</small></div><div class="field"><label>Why?</label><textarea name="reason" placeholder="Long-distance first job; company truck approved overnight." required></textarea></div><div class="field"><label>Expected return</label><input name="expected_return_label" placeholder="Fresno branch"></div><details class="context-card"><summary>Advanced planning coordinates (optional)</summary><div class="content"><div class="form-grid"><div class="field"><label>Latitude</label><input name="latitude" type="number" step="any"></div><div class="field"><label>Longitude</label><input name="longitude" type="number" step="any"></div></div><span class="tiny muted">Only use these if the business intentionally supplies an approved planning point. ServiceSlate never reads vehicle GPS.</span></div></details><div class="form-actions"><button type="button" class="btn" onclick="closeDrawer()">Cancel</button><button class="btn primary">Approve Exception</button></div></form>`);$('#remoteStartForm').onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(e.target).entries());const body={command_id:uid(),...fd,vehicle_id:fd.vehicle_id||null,latitude:fd.latitude?+fd.latitude:null,longitude:fd.longitude?+fd.longitude:null};try{await api('/api/remote-starts',{method:'POST',body:JSON.stringify(body)});toast('Remote start approved','good');closeDrawer();renderVehicles()}catch(err){toast(err.message,'bad')}}}


async function openTechCustomer(id){const d=await api(`/api/customers/${id}/field-history`);openDrawer(d.customer.name,'Approved company history only — no other technician live activity.',`<div class="context-card"><h3>Equipment at this customer</h3><div class="content">${d.equipment.map(e=>`<div class="history-item"><button class="link" onclick="openEquipment('${e.id}')"><strong>${esc(e.manufacturer||'')} ${esc(e.model||e.category)}</strong></button><p>${esc(e.location_name||'')} · ${esc(e.serial_number||'No serial')} · ${esc(e.bay||'No bay')}</p></div>`).join('')||'No equipment records.'}</div></div><div class="context-card"><h3>Approved work history</h3><div class="content">${d.approved_history.map(h=>`<div class="history-item"><strong>${esc(h.job_number)} · ${esc(h.description)}</strong><p>${esc([h.manufacturer,h.model,h.serial_number].filter(Boolean).join(' · '))}<br><b>Finding:</b> ${esc(h.finding||'—')}<br><b>Correction:</b> ${esc(h.correction||'—')}<br><b>Verified:</b> ${esc(h.verification||'—')}</p></div>`).join('')||'No approved work history yet.'}</div></div>`) }

if('serviceWorker' in navigator) navigator.serviceWorker.register('/sw.js').catch(()=>{});
const portalToken=new URLSearchParams(location.search).get('portal');
portalToken?renderPublicPortal(portalToken):boot();
